window.__BANK_DATA__=Object.assign(window.__BANK_DATA__||{},{"ch5-high-yield-immunity-metabolism":[{"id":"CH5-HY-001","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Guillain-Barré syndrome","question":"A client with Guillain-Barré syndrome develops increasing weakness. Which assessment is the priority?","options":["Visual acuity","Respiratory effort, vital capacity, and ability to clear secretions","Skin turgor and daily weight","Bowel sounds and stool frequency"],"answer":1,"rationales":["Visual acuity is not the priority assessment for ascending motor weakness.","Ascending paralysis can involve respiratory muscles. Respiratory status and vital capacity can deteriorate rapidly and require ventilatory support.","Hydration is important but does not detect impending respiratory failure.","GI function matters but is not the immediate life threat in progressive neuromuscular weakness."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-002","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Guillain-Barré syndrome","question":"Which finding in a client with Guillain-Barré syndrome requires immediate escalation?","options":["Absent deep tendon reflexes","A falling forced vital capacity with a weak cough","Anxiety about the diagnosis","Mild tingling in the feet"],"answer":1,"rationales":["Areflexia is characteristic of Guillain-Barré syndrome; it is not by itself the most urgent new change.","Declining respiratory measurements and ineffective cough signal impending respiratory failure.","Anxiety deserves support but does not take priority over airway and breathing.","Paresthesia is common and should be monitored, but is less urgent than respiratory decline."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-003","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Guillain-Barré syndrome","question":"Which pattern is most characteristic of Guillain-Barré syndrome?","options":["Symmetric ascending weakness that may progress to paralysis","Fluctuating ptosis that worsens with activity","Resting tremor with shuffling gait","Unilateral facial droop with sudden aphasia"],"answer":0,"rationales":["Ascending symmetric weakness and reduced reflexes are classic findings.","Fatigable weakness and ptosis are more characteristic of myasthenia gravis.","Resting tremor and shuffling gait are associated with Parkinson disease.","Sudden focal deficits suggest stroke and require a different emergency response."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-004","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Guillain-Barré syndrome","question":"Which therapy may be prescribed to reduce the immune-mediated course of Guillain-Barré syndrome?","options":["IV immunoglobulin or plasma exchange","Insulin infusion","Long-term oral antibiotics","Thyroid hormone replacement"],"answer":0,"rationales":["IVIG and plasma exchange are established treatments; supportive respiratory and autonomic monitoring remain essential.","Insulin treats hyperglycemia, not the underlying neurologic disorder.","Antibiotics do not treat the autoimmune peripheral nerve process.","Thyroid replacement treats hypothyroidism, not Guillain-Barré syndrome."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-005","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Myasthenia gravis","question":"A client with myasthenia gravis reports difficulty chewing near the end of a meal. What is the best nursing action?","options":["Offer thin liquids without assessing swallowing","Plan meals when strength is best and allow rest before eating","Encourage the client to finish meals quickly","Schedule meals immediately after strenuous activity"],"answer":1,"rationales":["Thin liquids may be difficult to control and can increase aspiration risk; assess swallowing and follow recommendations.","Fatigable bulbar weakness increases aspiration risk; schedule meals during stronger periods and assess swallowing.","Rushing increases fatigue and aspiration risk.","Activity worsens fatigability and is a poor time to eat."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-006","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Myasthenia gravis","question":"Which finding in myasthenia gravis is most concerning?","options":["Diplopia late in the day","Ptosis that improves after rest","Muscle weakness that worsens with activity","New dysphagia, weak cough, or respiratory difficulty"],"answer":3,"rationales":["Diplopia is common; respiratory and swallowing changes take priority.","Improvement with rest is a typical pattern, not the most urgent change.","Fatigability is expected, but new swallowing or breathing impairment is more urgent.","Bulbar and respiratory weakness can signal myasthenic crisis and threaten airway protection."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-007","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Myasthenia gravis","question":"When should pyridostigmine generally be timed for a client who has difficulty swallowing?","options":["Only when severe weakness occurs","Before meals as prescribed to improve muscle strength during eating","Only at bedtime","After meals so the client can rest"],"answer":1,"rationales":["Pyridostigmine is usually scheduled regularly; it is not simply a rescue medication.","Taking it before meals as prescribed can improve chewing and swallowing strength.","Bedtime-only dosing would not support mealtime function.","After-meal dosing misses the opportunity to improve swallowing during the meal."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-008","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Myasthenic vs cholinergic crisis","question":"A client with myasthenia gravis has severe weakness and respiratory distress. What is the first priority?","options":["Encourage ambulation to improve strength","Give an extra dose of pyridostigmine immediately","Offer oral fluids","Support airway and ventilation; prepare for emergency respiratory support"],"answer":3,"rationales":["Ambulation is unsafe with respiratory compromise.","An extra anticholinesterase dose may worsen cholinergic crisis and should not precede assessment and stabilization.","Oral fluids are unsafe with possible bulbar weakness and respiratory distress.","Both myasthenic and cholinergic crises can cause respiratory failure; airway and ventilation come first."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-009","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Anaphylaxis","question":"A client develops wheezing, facial swelling, and hypotension minutes after an injection. Which medication is first-line?","options":["Inhaled corticosteroid","IM epinephrine in the anterolateral thigh","IV corticosteroid as the only treatment","An oral antihistamine"],"answer":1,"rationales":["Inhaled corticosteroids do not rapidly reverse systemic anaphylaxis.","IM epinephrine is the first-line treatment for anaphylaxis because it reverses airway edema, bronchospasm, and hypotension.","Corticosteroids have delayed effects and are not first-line rescue treatment.","Antihistamines may help skin symptoms but do not replace epinephrine or treat shock."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-010","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Anaphylaxis","question":"After administering IM epinephrine for anaphylaxis, what should the nurse do next?","options":["Give oral fluids before reassessing","Wait to see whether the rash disappears","Activate emergency response, support airway/oxygenation, and prepare for repeat epinephrine if needed","Encourage the client to walk"],"answer":2,"rationales":["Oral intake is unsafe with airway compromise and does not treat shock.","Waiting risks deterioration; treat systemic symptoms immediately.","Anaphylaxis can rapidly recur or progress; emergency support, airway management, monitoring, and repeat dosing per protocol may be needed.","Walking can worsen hypotension and is unsafe."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-011","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Anaphylaxis","question":"Which finding most strongly indicates anaphylaxis rather than a mild localized allergy?","options":["Itching limited to the injection site","Hypotension with wheezing and generalized symptoms","A small localized rash without other symptoms","Mild sneezing alone"],"answer":1,"rationales":["Localized itching alone is not systemic anaphylaxis.","Airway or breathing compromise and circulatory collapse indicate systemic anaphylaxis.","A limited rash without systemic symptoms is less consistent with anaphylaxis.","Sneezing alone is not evidence of life-threatening systemic reaction."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-012","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Angioedema","question":"A client taking an ACE inhibitor develops tongue swelling and a muffled voice. What is the priority?","options":["Offer water to soothe the throat","Place the client flat and leave the room","Prepare for airway intervention and activate emergency help","Apply a cool compress and reassess in one hour"],"answer":2,"rationales":["Oral fluids may be unsafe with progressive airway edema.","The client needs close monitoring and airway support, not to be left unattended.","Tongue/laryngeal swelling can obstruct the airway; airway assessment and emergency intervention take priority.","A compress cannot treat internal airway swelling and delay is dangerous."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-013","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Angioedema","question":"Which medication history is especially important when assessing new angioedema?","options":["Calcium supplement use","Topical emollient use","Routine multivitamin use","ACE inhibitor use"],"answer":3,"rationales":["Calcium supplements are not a common cause of ACE-inhibitor-type angioedema.","Topical emollients do not explain tongue or laryngeal edema.","A multivitamin is not the key medication association.","ACE inhibitors can cause bradykinin-mediated angioedema, even after prolonged use."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-014","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Systemic lupus erythematosus","question":"Which laboratory result is commonly associated with systemic lupus erythematosus?","options":["Positive troponin as a diagnostic marker","Elevated TSH as a defining test","Low serum sodium as a defining test","Positive antinuclear antibody (ANA)"],"answer":3,"rationales":["Troponin indicates myocardial injury, not SLE diagnosis.","TSH evaluates thyroid function, not SLE.","Hyponatremia is nonspecific and not a defining SLE test.","ANA is sensitive for SLE but not specific; diagnosis uses clinical findings and additional antibodies."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-015","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Systemic lupus erythematosus","question":"A client with lupus reports foamy urine and new ankle edema. Which complication should the nurse suspect?","options":["Thyroid storm","Myasthenic crisis","Diabetes insipidus","Lupus nephritis"],"answer":3,"rationales":["Thyroid storm causes severe thyrotoxicosis.","Myasthenic crisis causes respiratory/bulbar weakness, not proteinuria.","Diabetes insipidus causes large volumes of dilute urine and dehydration, not typically proteinuria with edema.","Proteinuria and edema can indicate renal involvement from lupus nephritis and require prompt evaluation."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-016","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Systemic lupus erythematosus","question":"Which teaching is most important for a client with lupus?","options":["Use sun protection and report signs of infection promptly","Receive live vaccines while taking high-dose immunosuppressants","Stop immunosuppressants when symptoms improve","Avoid all physical activity permanently"],"answer":0,"rationales":["UV exposure can trigger flares; immunosuppression increases infection risk.","Live vaccines may be contraindicated during significant immunosuppression; verify vaccine safety with the care team.","Abruptly stopping prescribed therapy can cause disease flare; discuss changes with the prescriber.","Activity should be balanced with rest, not universally prohibited."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-017","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Rheumatoid arthritis","question":"Which assessment finding is most characteristic of rheumatoid arthritis?","options":["Symmetric inflammatory joint pain with prolonged morning stiffness","Sudden severe monoarticular pain with fever only","Pain that worsens only after a traumatic injury","Heberden nodes without systemic inflammation"],"answer":0,"rationales":["RA commonly causes symmetric inflammatory polyarthritis and prolonged morning stiffness.","Acute monoarthritis with fever raises concern for septic arthritis or gout.","A traumatic injury does not describe the typical systemic autoimmune pattern.","Heberden nodes are more typical of osteoarthritis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-018","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Rheumatoid arthritis","question":"A client taking methotrexate for rheumatoid arthritis calls to report fever and sore throat. What should the nurse advise?","options":["Hold further dose and contact the prescriber promptly for infection evaluation","Take an extra dose to control inflammation","Ignore symptoms unless a rash develops","Receive a live vaccine today"],"answer":0,"rationales":["Methotrexate suppresses immune function and can cause bone marrow suppression; infection symptoms need prompt evaluation and prescriber guidance.","Extra dosing increases toxicity.","Fever and sore throat may be early infection or neutropenia and should not be ignored.","Live vaccines may be unsafe during immunosuppressive therapy."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-019","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"DMARDs","question":"What is the primary purpose of disease-modifying antirheumatic drugs (DMARDs)?","options":["Slow disease progression and prevent joint damage","Provide immediate relief of acute pain within minutes","Treat bacterial infections","Replace deficient thyroid hormone"],"answer":0,"rationales":["DMARDs target disease activity and reduce long-term joint damage; onset may be delayed.","DMARDs are not rapid analgesics; NSAIDs may provide symptom relief but do not replace DMARDs.","Antibiotics treat bacterial infections, not autoimmune arthritis.","Thyroid hormone treats hypothyroidism."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-020","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Sjogren syndrome","question":"Which symptom pattern is most consistent with Sjögren syndrome?","options":["Persistent dry eyes and dry mouth","Excessive sweating and heat intolerance","Ascending paralysis and areflexia","Polyuria and intense thirst"],"answer":0,"rationales":["Autoimmune destruction of exocrine glands causes xerophthalmia and xerostomia.","Sweating and heat intolerance suggest hyperthyroidism.","Ascending paralysis suggests Guillain-Barré syndrome.","Polyuria and polydipsia suggest diabetes mellitus or diabetes insipidus."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-021","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV/AIDS","question":"Which laboratory value best reflects the degree of immune system damage in a client with HIV?","options":["Hemoglobin A1c","CD4 T-cell count","Serum potassium","Serum calcium"],"answer":1,"rationales":["A1c reflects average glucose control.","CD4 count estimates immune function and helps assess risk for opportunistic infections.","Potassium evaluates electrolyte balance, not HIV immune status.","Calcium is not the principal marker of HIV-related immune suppression."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-022","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV/AIDS","question":"Which test is used to monitor response to antiretroviral therapy?","options":["Serum amylase","HIV viral load","ANA titer","Rheumatoid factor"],"answer":1,"rationales":["Amylase helps evaluate pancreatic injury.","Viral load measures circulating HIV RNA; suppression indicates treatment effectiveness.","ANA is used in evaluation of autoimmune disease such as lupus.","Rheumatoid factor supports evaluation for rheumatoid arthritis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-023","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV/AIDS","question":"A client with HIV has a CD4 count of 160 cells/mm³. Which concern is most important?","options":["Risk for hypocalcemia only","Increased risk for opportunistic infections","Risk for acute appendicitis only","Increased risk for hyperthyroidism"],"answer":1,"rationales":["Hypocalcemia is not the defining risk of severe HIV-related immunosuppression.","A CD4 count below 200 cells/mm³ indicates advanced immunosuppression and increased opportunistic infection risk.","Appendicitis risk is not the key implication of low CD4 count.","CD4 count does not predict hyperthyroidism."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-024","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV/AIDS","question":"Which statement by a client taking antiretroviral therapy indicates understanding?","options":["I only need treatment when my viral load rises.","I should take my medications consistently and avoid missed doses.","I should share extra medication with a partner.","I can stop treatment once I feel healthy."],"answer":1,"rationales":["Treatment is continuous, not only taken when laboratory values worsen.","Consistent adherence helps maintain viral suppression and reduce resistance.","Medications should never be shared; each regimen is individualized.","HIV treatment is ongoing; stopping can allow viral rebound and resistance."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-025","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunosuppression","question":"Which finding in an immunosuppressed client requires prompt follow-up even if the client appears well?","options":["Mild dry skin","Hunger before lunch","A new fever or subtle change in mental status","A stable old scar"],"answer":2,"rationales":["Dry skin is not the priority infection cue.","Hunger is not an urgent sign of infection.","Immunosuppressed clients may have muted inflammatory signs; fever or subtle deterioration can signal serious infection.","A stable scar is not an acute concern."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-026","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunosuppression","question":"Which instruction is appropriate for a client taking significant immunosuppressive therapy?","options":["Eat raw eggs to increase protein intake","Avoid close contact with people who have contagious illnesses and report fever","Receive all live vaccines without consultation","Stop medication whenever a minor cold begins"],"answer":1,"rationales":["Raw eggs increase foodborne infection risk, especially with immunosuppression.","Reducing exposure and promptly reporting infection are important; vaccine type and medication changes require provider guidance.","Live vaccines may be contraindicated with immunosuppression.","Do not independently stop immunosuppressants; contact the care team for illness guidance."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-027","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immune assessment","question":"Which laboratory pattern is most concerning for infection risk in a client receiving immunosuppressants?","options":["Normal sodium","Markedly decreased absolute neutrophil count","Mildly elevated HDL","Slightly increased albumin"],"answer":1,"rationales":["Normal sodium does not indicate neutropenia.","Neutropenia reduces defense against bacterial and fungal infection; severe neutropenia requires precautions and prompt response to fever.","HDL is not a measure of infection defense.","Albumin is not the primary marker of neutrophil-mediated infection risk."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-028","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"SIADH","question":"A client with SIADH has a sodium level of 119 mEq/L and confusion. What is the priority concern?","options":["Seizures and cerebral edema from severe hyponatremia","Dehydration from excessive dilute urine","Hypercalcemia","Hypoglycemia from insulin excess"],"answer":0,"rationales":["SIADH causes water retention and dilutional hyponatremia; severe neurologic symptoms raise seizure risk.","Excessive dilute urine is characteristic of diabetes insipidus.","Hypercalcemia is a parathyroid-related concern, not the primary SIADH complication.","Hypoglycemia is not the defining complication of SIADH."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-029","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"SIADH","question":"Which assessment pattern is expected with SIADH?","options":["High serum sodium and very dilute urine","High serum glucose with ketones","High calcium and low phosphate","Low serum sodium and osmolality with concentrated urine"],"answer":3,"rationales":["This pattern is typical of diabetes insipidus.","Hyperglycemia with ketones suggests diabetic ketoacidosis.","This pattern suggests hyperparathyroidism.","Excess ADH causes water retention, dilutional hyponatremia, low serum osmolality, and concentrated urine."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-030","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"SIADH","question":"Which intervention is commonly prescribed for a stable client with SIADH?","options":["Fluid restriction with careful intake/output and sodium monitoring","Increase free-water intake before bedtime","Encourage unrestricted oral water","Administer hypotonic IV fluids rapidly"],"answer":0,"rationales":["Fluid restriction helps correct dilutional hyponatremia; monitor neurologic status, sodium, and fluid balance.","Increasing free water worsens the underlying problem.","Unrestricted water worsens water retention and hyponatremia.","Hypotonic fluids can worsen hyponatremia and cerebral edema."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-031","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"SIADH","question":"A client with severe symptomatic hyponatremia from SIADH is prescribed hypertonic saline. What is essential?","options":["Frequent sodium and neurologic monitoring; correct sodium carefully","Rapidly normalize sodium to the highest normal value","Give the infusion without an infusion pump","Encourage large amounts of oral water"],"answer":0,"rationales":["Overly rapid correction can cause osmotic demyelination; hypertonic saline requires close monitoring and controlled correction.","Rapid correction is dangerous.","A controlled infusion device and protocol are important for hypertonic saline.","Free water can worsen hyponatremia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-032","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes insipidus","question":"Which finding is most characteristic of diabetes insipidus?","options":["Large amounts of very dilute urine with intense thirst","Bradycardia and hypothermia","Edema and weight gain with low sodium","Low urine output with concentrated urine"],"answer":0,"rationales":["Insufficient ADH effect causes inability to concentrate urine, resulting in polyuria, polydipsia, and dehydration risk.","Bradycardia and hypothermia are not hallmark DI findings.","Edema and dilutional hyponatremia are more consistent with SIADH.","Oliguria and concentrated urine suggest water retention, such as SIADH."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-033","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes insipidus","question":"Which laboratory pattern is expected in untreated diabetes insipidus?","options":["Low blood glucose and ketones","Increased serum sodium/osmolality and decreased urine specific gravity","Decreased serum sodium and concentrated urine","Low serum osmolality and high urine osmolality"],"answer":1,"rationales":["Glucose and ketones are not the defining DI pattern.","Free-water loss causes hypernatremia and concentrated serum, while urine remains dilute.","This pattern is typical of SIADH.","This is also consistent with SIADH, not DI."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-034","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes insipidus","question":"A client with central diabetes insipidus is prescribed desmopressin. Which finding suggests the medication is effective?","options":["Thirst becomes more intense","Urine output increases further","Urine output decreases and urine becomes more concentrated","Serum sodium rises"],"answer":2,"rationales":["Worsening thirst suggests persistent dehydration.","Increasing urine output suggests inadequate response or another problem.","Desmopressin replaces ADH activity, reducing excessive urine output and increasing urine concentration.","Rising sodium suggests ongoing free-water loss."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-035","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"SIADH vs DI","question":"Which comparison is correct?","options":["Both disorders are treated with unrestricted fluids","SIADH causes hypernatremia; DI causes hyponatremia","Both disorders cause concentrated urine and fluid overload","SIADH retains water; diabetes insipidus loses excessive free water"],"answer":3,"rationales":["Fluid management differs; unrestricted fluids can worsen SIADH.","The sodium patterns are generally reversed.","DI urine is typically dilute, and DI does not cause fluid overload.","SIADH causes water retention and dilutional hyponatremia; DI causes polyuria and dehydration/hypernatremia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-036","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hypothyroidism","question":"Which assessment pattern is most consistent with hypothyroidism?","options":["Heat intolerance, weight loss, diarrhea, and tachycardia","Polyuria and severe thirst","Fatigue, cold intolerance, constipation, weight gain, and bradycardia","Exophthalmos and tremor"],"answer":2,"rationales":["This is the classic hyperthyroid pattern.","Polyuria and polydipsia suggest diabetes mellitus or DI.","Low thyroid hormone slows metabolism, producing cold intolerance, fatigue, constipation, weight gain, and bradycardia.","Exophthalmos and tremor are associated with Graves hyperthyroidism."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-037","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hypothyroidism","question":"Which laboratory pattern is expected in primary hypothyroidism?","options":["Low TSH and low T4 from primary thyroid failure","Low TSH and high free T4","High TSH and high T4","High TSH and low free T4"],"answer":3,"rationales":["Low TSH with low T4 suggests central (pituitary/hypothalamic) hypothyroidism, not primary thyroid failure.","This is typical of primary hyperthyroidism.","High TSH with high T4 is not the usual primary hypothyroid pattern.","In primary thyroid failure, low T4 reduces negative feedback, so pituitary TSH rises."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-038","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Levothyroxine","question":"Which instruction should the nurse give a client taking levothyroxine?","options":["Take an extra dose whenever weight increases","Take it consistently on an empty stomach, usually 30–60 minutes before breakfast","Stop it when fatigue resolves","Take it with calcium and iron to improve absorption"],"answer":1,"rationales":["Dose changes should be based on laboratory monitoring and prescriber instructions.","Levothyroxine absorption is best when taken consistently on an empty stomach; calcium and iron should be separated by several hours.","Most clients require lifelong replacement; symptoms improving does not mean the condition is cured.","Calcium and iron decrease absorption and should be spaced apart."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-039","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Levothyroxine","question":"Which finding may indicate excessive levothyroxine dosing?","options":["Bradycardia and cold intolerance","Increasing somnolence with hypothermia","Constipation and slowed speech","Palpitations, tachycardia, tremor, and heat intolerance"],"answer":3,"rationales":["These are hypothyroid findings and may indicate inadequate replacement.","Somnolence and hypothermia may indicate severe hypothyroidism.","These findings are consistent with slowed metabolism.","Excess thyroid replacement can cause hyperthyroid symptoms and increase dysrhythmia risk."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-040","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Myxedema coma","question":"A client with severe hypothyroidism is hypothermic, bradycardic, hypotensive, and difficult to arouse. What is the priority?","options":["Encourage ambulation and oral fluids","Delay treatment until TSH results return","Emergency support of airway, breathing, circulation, and temperature; anticipate IV thyroid hormone","Administer a sedative for agitation"],"answer":2,"rationales":["Ambulation and oral intake are unsafe in a patient with decreased consciousness and instability.","Treatment is urgent and should not be delayed for confirmatory testing when clinically suspected.","Myxedema coma is life-threatening; stabilize ABCs and initiate emergency treatment without avoidable delay.","Sedatives can worsen respiratory depression and altered consciousness."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-041","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hyperthyroidism","question":"Which assessment pattern is most consistent with hyperthyroidism?","options":["Edema, low urine output, and hyponatremia","Weight loss, heat intolerance, tremor, diarrhea, and tachycardia","Polyuria with very dilute urine","Weight gain, cold intolerance, constipation, and bradycardia"],"answer":1,"rationales":["This pattern may occur with SIADH or renal/cardiac disease.","Excess thyroid hormone increases metabolic activity and sympathetic effects.","This is typical of diabetes insipidus.","This is typical of hypothyroidism."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-042","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hyperthyroidism","question":"Which laboratory pattern is expected in primary hyperthyroidism?","options":["High TSH with low T4","Low TSH with low T4","Low TSH with elevated T3 and/or T4","High TSH with high T4"],"answer":2,"rationales":["This is typical of primary hypothyroidism.","Low TSH and low T4 suggests central hypothyroidism.","High circulating thyroid hormone suppresses pituitary TSH through negative feedback.","This is not the usual pattern of primary thyroid disease."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-043","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroid storm","question":"A client with untreated hyperthyroidism develops a temperature of 104°F, severe tachycardia, agitation, and vomiting. What should the nurse suspect?","options":["Addisonian crisis","Myxedema coma","Thyroid storm","Hypocalcemic tetany"],"answer":2,"rationales":["Addisonian crisis causes hypotension and electrolyte/glucose abnormalities.","Myxedema coma is severe hypothyroidism with hypothermia and bradycardia.","Thyroid storm is an acute life-threatening hypermetabolic state with fever, severe tachycardia, and CNS/GI changes.","Tetany is associated with hypocalcemia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-044","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroid storm","question":"Which intervention is appropriate for thyroid storm?","options":["Apply warming blankets and administer levothyroxine","Rapid supportive care, cooling, cardiac monitoring, beta blockade, and antithyroid therapy as prescribed","Give iodine before antithyroid medication without following protocol","Encourage exercise to reduce agitation"],"answer":1,"rationales":["Warming and thyroid hormone would worsen thyrotoxicosis.","Thyroid storm requires emergency stabilization, cooling, cardiac monitoring, and ordered therapies such as beta blockers and antithyroid drugs.","Medication sequence matters; iodine is generally given after a thionamide to block hormone release, per protocol.","Exercise increases metabolic and cardiac demand."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-045","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Methimazole/PTU","question":"A client taking methimazole reports fever and sore throat. What is the nurse’s priority instruction?","options":["Stop all fluids","Use an over-the-counter cold medicine and ignore the symptoms","Take the next dose early","Contact the provider immediately for possible agranulocytosis; obtain CBC as directed"],"answer":3,"rationales":["Fluid restriction is unrelated and potentially harmful.","Infection symptoms must not be masked or ignored.","Extra dosing increases risk and is unsafe.","Thionamides can cause agranulocytosis; fever and sore throat require prompt evaluation and CBC."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-046","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Propylthiouracil","question":"Which serious adverse effect is especially associated with propylthiouracil (PTU)?","options":["Pulmonary fibrosis as the primary boxed concern","Ototoxicity","Severe hepatotoxicity","Permanent hypoglycemia"],"answer":2,"rationales":["Pulmonary fibrosis is not the primary PTU warning.","Ototoxicity is not the major PTU safety concern.","PTU can cause severe liver injury; monitor for jaundice, dark urine, abdominal pain, and unusual fatigue.","PTU does not cause permanent hypoglycemia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-047","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Radioactive iodine","question":"Which teaching is appropriate after radioactive iodine treatment for hyperthyroidism?","options":["Expect immediate permanent cure without follow-up","Avoid all laboratory testing","Take extra thyroid hormone immediately without an order","Follow radiation-safety instructions and understand hypothyroidism may develop later"],"answer":3,"rationales":["The effect is not immediate, and follow-up is essential.","TSH/T4 monitoring is needed to detect treatment response and hypothyroidism.","Replacement is started only when indicated and prescribed.","Radioactive iodine destroys thyroid tissue gradually; radiation precautions and ongoing thyroid monitoring are necessary."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-048","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroidectomy","question":"Which postoperative finding after thyroidectomy requires immediate action?","options":["Stridor or difficulty breathing","Mild incisional discomfort","A small amount of expected drainage","Mild sore throat"],"answer":0,"rationales":["Stridor can indicate airway obstruction from edema, hematoma, or laryngeal injury and is an emergency.","Pain is expected and can be treated while monitoring.","Small expected drainage is not as urgent as airway compromise.","A sore throat may occur after intubation but is less urgent than stridor."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-049","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroidectomy","question":"Which equipment should be readily available after thyroidectomy?","options":["A defibrillator as the only emergency equipment","A chest tube drainage system","A feeding pump only","Suction, oxygen, and emergency airway equipment; assess for hypocalcemia"],"answer":3,"rationales":["Cardiac emergency equipment may be available per setting, but it does not replace airway and calcium precautions.","Chest tubes are not routinely required.","Feeding equipment does not address immediate postoperative risks.","Airway compromise and postoperative hypocalcemia are key risks; have airway equipment and monitor calcium/tetany."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-050","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroidectomy","question":"A client develops tingling around the mouth and hand spasms after thyroidectomy. What should the nurse suspect?","options":["Hypernatremia","Hypercalcemia from excess PTH","Thyroid storm","Hypocalcemia from parathyroid injury or manipulation"],"answer":3,"rationales":["Hypernatremia does not explain classic tetany.","Hypercalcemia causes weakness, constipation, and stones rather than tetany.","Thyroid storm causes hypermetabolic symptoms.","Parathyroid disruption can reduce PTH and calcium, causing paresthesia, tetany, and positive Chvostek/Trousseau signs."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-051","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hyperparathyroidism","question":"Which findings are expected with hyperparathyroidism?","options":["Hypoglycemia and ketones","Hypercalcemia, kidney stones, bone loss, constipation, and confusion","Hypocalcemia, tetany, and positive Trousseau sign","Hyponatremia and concentrated urine"],"answer":1,"rationales":["This suggests diabetic metabolic decompensation.","Excess PTH raises serum calcium and can cause renal calculi, bone resorption, GI slowing, and altered mental status.","This is characteristic of hypoparathyroidism.","This pattern is associated with SIADH."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-052","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hypoparathyroidism","question":"A client develops muscle cramps, perioral tingling, and a positive Trousseau sign after thyroid surgery. Which laboratory abnormality is expected?","options":["High calcium and low phosphate","High sodium and low potassium","High glucose and low ketones","Low calcium and high phosphate"],"answer":3,"rationales":["This is more consistent with hyperparathyroidism.","This does not explain tetany.","Glucose and ketones are unrelated to the classic postoperative hypocalcemia pattern.","Low PTH decreases calcium and reduces phosphate excretion, producing hypocalcemia and hyperphosphatemia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-053","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hypocalcemia","question":"A client with symptomatic hypocalcemia is prescribed IV calcium gluconate. What is essential during administration?","options":["Mix with phosphate-containing solutions","Cardiac/ECG monitoring and controlled IV administration","Encourage hyperventilation","Rapid IV push without monitoring"],"answer":1,"rationales":["Calcium can precipitate with phosphate; compatibility must be checked.","IV calcium can affect cardiac conduction and must be administered carefully with ECG monitoring per protocol.","Hyperventilation can lower ionized calcium further and worsen symptoms.","Rapid unmonitored administration can cause serious dysrhythmias."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-054","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Addison disease","question":"Which assessment pattern is most consistent with primary adrenal insufficiency (Addison disease)?","options":["Heat intolerance, tremor, and tachycardia","Hypertension, truncal obesity, purple striae, and hyperglycemia","Edema, low sodium, and concentrated urine","Hypotension, weight loss, hyperpigmentation, hyponatremia, and hyperkalemia"],"answer":3,"rationales":["This suggests hyperthyroidism.","This is typical of Cushing syndrome.","This pattern may suggest SIADH or fluid overload, not Addison disease.","Low cortisol and aldosterone cause hypotension, sodium loss, potassium retention, and often hyperpigmentation from elevated ACTH."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-055","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Addisonian crisis","question":"A client with Addison disease has vomiting, severe hypotension, weakness, and confusion after an infection. What is the priority?","options":["Give levothyroxine","Restrict fluids and administer a diuretic","Treat as adrenal crisis: IV hydrocortisone and isotonic fluids as prescribed, with glucose/electrolyte monitoring","Delay treatment until cortisol results return"],"answer":2,"rationales":["Thyroid hormone does not treat adrenal crisis.","Fluid restriction worsens hypovolemia and shock.","Adrenal crisis is life-threatening; prompt glucocorticoid replacement and fluid resuscitation are critical.","Treatment should not be delayed in a suspected crisis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-056","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Addison disease","question":"Which medication regimen is commonly used for chronic primary adrenal insufficiency?","options":["Glucocorticoid replacement plus fludrocortisone when aldosterone replacement is needed","A thyroid hormone synthesis inhibitor and a non-endocrine medication","A diabetes medication and an unrelated rescue medication","Desmopressin only"],"answer":0,"rationales":["Hydrocortisone/prednisone replaces cortisol; fludrocortisone replaces mineralocorticoid activity in primary adrenal insufficiency.","These medications treat hyperthyroidism.","Insulin/glucagon are used in glucose regulation, not adrenal hormone replacement.","Desmopressin treats central diabetes insipidus."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-057","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Addison disease teaching","question":"Which statement by a client with Addison disease indicates understanding?","options":["I must not stop my corticosteroid replacement abruptly and may need stress-dose instructions during illness.","I can stop steroids once my blood pressure improves.","I should take less medication during fever or surgery.","I should avoid carrying medical identification."],"answer":0,"rationales":["Abrupt withdrawal can precipitate adrenal crisis; clients need sick-day/stress-dose guidance and medical identification.","Replacement is generally lifelong and should not be stopped without the prescriber.","Illness and surgery increase cortisol needs; dose adjustment is often required under a prescribed plan.","Medical alert identification helps emergency clinicians recognize adrenal insufficiency."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-058","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Cushing syndrome","question":"Which assessment findings are most consistent with Cushing syndrome?","options":["Moon face, truncal obesity, purple striae, thin skin, hypertension, and hyperglycemia","Cold intolerance, bradycardia, and constipation","Tetany, paresthesia, and low calcium","Weight loss, hyperpigmentation, hypotension, and hyperkalemia"],"answer":0,"rationales":["Excess cortisol causes characteristic fat redistribution, skin fragility, hypertension, and hyperglycemia.","This is typical of hypothyroidism.","This is typical of hypocalcemia.","This is typical of Addison disease."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-059","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Cushing syndrome","question":"Which nursing concern is especially important for a client with Cushing syndrome?","options":["Infection risk and impaired wound healing","Risk for dehydration from excessive dilute urine","Risk for acute tetany from high calcium","Risk for severe hypoglycemia as the primary effect"],"answer":0,"rationales":["Cortisol suppresses immune and inflammatory responses and impairs tissue repair; infection may be subtle.","Excess dilute urine suggests DI.","Tetany is associated with low calcium, not Cushing syndrome.","Cortisol excess more often causes hyperglycemia."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-060","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Corticosteroids","question":"Which instruction is essential for a client taking long-term systemic corticosteroids?","options":["Stop the medication once symptoms improve","Avoid reporting fever because steroids prevent infection","Take double doses when a dose is missed","Do not discontinue abruptly; follow tapering and stress-dose instructions"],"answer":3,"rationales":["Abrupt discontinuation can be dangerous.","Steroids can mask infection signs and increase infection risk; fever must be reported.","Doubling doses is unsafe; follow prescriber/pharmacist instructions.","Long-term steroids suppress the HPA axis; abrupt withdrawal can cause adrenal insufficiency."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-061","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Corticosteroids","question":"Which adverse effects should the nurse monitor during prolonged systemic corticosteroid therapy?","options":["Low infection risk and rapid wound healing","Hyperglycemia, hypertension, infection, osteoporosis, and weight gain","Hypoglycemia, hypotension, and increased bone density","Severe bradycardia and hypothermia"],"answer":1,"rationales":["Corticosteroids increase infection risk and can impair wound healing.","Glucocorticoids can raise glucose and blood pressure, suppress immunity, weaken bone, and cause weight gain.","These are opposite or unrelated effects.","These are not typical corticosteroid adverse effects."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-062","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Growth hormone","question":"Which medication is used as replacement therapy for growth hormone deficiency?","options":["Methimazole","Cinacalcet","Fludrocortisone","Somatropin"],"answer":3,"rationales":["Methimazole blocks thyroid hormone synthesis.","Cinacalcet lowers PTH secretion.","Fludrocortisone replaces mineralocorticoid activity.","Somatropin is recombinant human growth hormone used for selected growth hormone deficiencies."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-063","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Acromegaly","question":"An adult has enlarged hands and feet, coarse facial features, and an enlarged jaw. Which disorder should the nurse suspect?","options":["Addison disease","Acromegaly from excess growth hormone after epiphyseal closure","Gigantism from excess growth hormone during childhood","Growth hormone deficiency"],"answer":1,"rationales":["Addison disease causes cortisol/aldosterone deficiency.","Excess growth hormone after epiphyseal closure causes enlargement of acral and facial bones/tissues.","Gigantism occurs before epiphyseal closure in childhood.","Growth hormone deficiency causes short stature, not acral enlargement."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-064","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes mellitus","question":"Which statement best distinguishes type 1 from type 2 diabetes?","options":["Type 1 is caused only by obesity; type 2 is always autoimmune.","Type 2 always begins in childhood.","Type 1 involves autoimmune beta-cell destruction and absolute insulin deficiency; type 2 involves insulin resistance with progressive beta-cell dysfunction.","Both types are treated only with oral medication."],"answer":2,"rationales":["This reverses the underlying pathophysiology.","Type 2 can occur at many ages; age alone does not define the type.","Type 1 results from beta-cell destruction; type 2 is characterized by insulin resistance and inadequate insulin secretion over time.","Insulin is essential in type 1 and may be needed in type 2."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-065","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes mellitus","question":"Which symptoms are classic manifestations of hyperglycemia?","options":["Oliguria and edema only","Bradycardia, hypothermia, and constipation","Perioral tingling and tetany","Polyuria, polydipsia, and polyphagia"],"answer":3,"rationales":["Oliguria and edema are not the classic presentation of hyperglycemia.","These are associated with hypothyroidism.","These suggest hypocalcemia.","Hyperglycemia causes osmotic diuresis, leading to polyuria, thirst, and often increased hunger."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-066","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hypoglycemia","question":"A conscious client with diabetes has a blood glucose of 54 mg/dL and can swallow safely. What should the nurse do first?","options":["Withhold all food and fluids","Administer the scheduled rapid-acting insulin","Give 15 g of fast-acting carbohydrate and recheck glucose in 15 minutes","Give a high-fat meal and recheck in one hour"],"answer":2,"rationales":["Withholding carbohydrate worsens hypoglycemia.","Insulin worsens hypoglycemia.","The 15-15 approach treats mild/moderate hypoglycemia: 15 g rapid carbohydrate, recheck in 15 minutes, repeat if needed.","Fat slows carbohydrate absorption; treatment should use fast-acting carbohydrate."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-068","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetic ketoacidosis","question":"Which findings are most consistent with diabetic ketoacidosis (DKA)?","options":["Hyperglycemia, ketones, metabolic acidosis, dehydration, and Kussmaul respirations","Hypothermia with low TSH","Hypoglycemia, alkalosis, and bradycardia","Hypernatremia with dilute urine and no ketones"],"answer":0,"rationales":["DKA involves insulin deficiency, ketone production, metabolic acidosis, and osmotic diuresis/dehydration.","This suggests severe hypothyroidism.","This is not the DKA pattern.","This suggests diabetes insipidus, not DKA."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-069","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"DKA treatment","question":"A client with DKA is admitted with dehydration and a glucose of 620 mg/dL. Which intervention is generally initiated first?","options":["IV potassium bolus before obtaining potassium level","IV isotonic fluid resuscitation, followed by insulin and electrolyte-guided management","Sodium bicarbonate for every client","Oral fluids only"],"answer":1,"rationales":["Potassium replacement must be guided by serum potassium and renal function; IV bolus is dangerous.","Restoring circulating volume with isotonic fluids is an initial priority; insulin and potassium management follow lab-guided protocols.","Bicarbonate is reserved for selected severe acidosis cases, not routine DKA treatment.","Oral fluids are inadequate for severe dehydration and DKA."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-070","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"DKA potassium","question":"Why must potassium be monitored closely during DKA treatment?","options":["Insulin always causes hyperkalemia","Insulin shifts potassium into cells and can rapidly lower serum potassium","Potassium rises because urine output stops in all clients","Potassium is unrelated to cardiac rhythm"],"answer":1,"rationales":["Insulin generally lowers serum potassium by shifting it into cells.","Insulin drives potassium intracellularly; serum potassium can fall dangerously during treatment, increasing dysrhythmia risk.","DKA causes osmotic diuresis and total-body potassium depletion, not universal anuria.","Potassium is essential for cardiac conduction and rhythm."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-071","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Hyperosmolar hyperglycemic state","question":"Which feature is more characteristic of hyperosmolar hyperglycemic state (HHS) than DKA?","options":["Respiratory alkalosis caused by hypocalcemia","Low blood glucose","Marked ketosis and metabolic acidosis in every case","Profound hyperglycemia and dehydration with minimal or absent ketones"],"answer":3,"rationales":["This is unrelated to HHS.","HHS involves severe hyperglycemia.","Marked ketosis and acidosis are more characteristic of DKA.","HHS typically causes extreme hyperglycemia, hyperosmolality, and severe dehydration with little/no ketosis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-072","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetic neuropathy","question":"Which teaching helps prevent injury in a client with diabetic peripheral neuropathy?","options":["Use a heating pad on numb feet","Cut corns and calluses with a razor","Inspect feet daily, wear properly fitting shoes, and never walk barefoot","Soak feet in hot water every night"],"answer":2,"rationales":["Heat can cause burns when sensation is impaired.","Self-cutting can cause wounds and infection; refer foot lesions to a clinician.","Neuropathy reduces protective sensation; daily inspection and protective footwear prevent unnoticed injury.","Hot water can burn insensate skin; use lukewarm water and test temperature."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-073","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetic neuropathy","question":"A client with diabetic neuropathy is prescribed gabapentin. Which teaching is appropriate?","options":["May cause dizziness and drowsiness; avoid abrupt discontinuation and report mood changes","Stop suddenly when pain improves","It is an insulin replacement","Take extra doses for immediate relief"],"answer":0,"rationales":["Gabapentin can cause CNS effects and mood changes; tapering may be needed, and suicidal thoughts require prompt reporting.","Abrupt discontinuation can cause problems; follow prescriber tapering instructions.","Gabapentin treats neuropathic pain, not glucose deficiency.","Extra dosing increases adverse effects and is unsafe."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-074","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Pregabalin","question":"Which adverse effects should the nurse discuss with a client starting pregabalin for diabetic neuropathy?","options":["Severe hypoglycemia in all clients","Permanent hearing loss","Agranulocytosis as the most common effect","Dizziness, somnolence, edema, and possible mood or suicidal-thought changes"],"answer":3,"rationales":["Pregabalin is not an insulin or routine cause of hypoglycemia.","Hearing loss is not a common expected adverse effect.","Agranulocytosis is not the primary common pregabalin concern.","Pregabalin commonly causes dizziness/somnolence and can cause edema; monitor mood and report suicidal thoughts."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-075","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes foot care","question":"Which foot-care statement requires correction?","options":["I will wear shoes and socks that fit properly.","I will inspect between my toes every day.","I will soak my feet in hot water to soften the skin.","I will report blisters, redness, or wounds promptly."],"answer":2,"rationales":["Proper footwear reduces pressure and injury.","Daily inspection is appropriate.","Hot soaking can cause burns and maceration, especially with neuropathy; use lukewarm water and dry carefully.","Prompt reporting prevents progression to ulceration or infection."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-076","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes monitoring","question":"Which test best reflects average blood glucose over approximately the previous 2–3 months?","options":["Single fasting glucose","Serum potassium","Hemoglobin A1c","Urine ketones"],"answer":2,"rationales":["A single glucose is a point-in-time measurement.","Potassium is an electrolyte, not a chronic glycemic marker.","A1c reflects glycation over the lifespan of red blood cells and estimates average glucose over about 2–3 months.","Urine ketones detect ketone production, not average glucose."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-077","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes complications","question":"Which finding may indicate diabetic nephropathy?","options":["Positive Trousseau sign","High urine volume with very low specific gravity only","Low TSH","Persistent albumin/protein in the urine"],"answer":3,"rationales":["Trousseau sign indicates hypocalcemia.","Very dilute high-volume urine suggests DI rather than diabetic nephropathy.","TSH evaluates thyroid function.","Albuminuria is an early marker of diabetic kidney damage; monitor renal function and urine albumin."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-078","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Diabetes complications","question":"Which chronic complication is associated with damage to small retinal blood vessels from diabetes?","options":["Sjögren syndrome","Diabetic retinopathy","Myasthenia gravis","Acromegaly"],"answer":1,"rationales":["Sjögren syndrome affects exocrine glands.","Chronic hyperglycemia damages retinal microvasculature and can impair vision.","Myasthenia gravis is an autoimmune neuromuscular disorder.","Acromegaly is caused by excess growth hormone."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-079","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Nutrition — high calorie/high protein","question":"A client with increased metabolic needs and unintentional weight loss is prescribed a high-calorie, high-protein diet. Which meal best follows the plan?","options":["Only raw vegetables and water","Clear broth, gelatin, and diet soda","Low-fat crackers with unsweetened tea","Chicken, eggs, Greek yogurt, whole grains, and calorie-dense healthy fats"],"answer":3,"rationales":["This is nutritionally inadequate and low in protein/energy.","This provides inadequate calories and protein.","This is inadequate for a high-calorie/high-protein plan.","Protein-rich foods support tissue repair and lean mass; calorie-dense foods help meet increased energy needs."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-080","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Nutrition — low calorie/low fat","question":"Which meal best fits a low-calorie, low-fat diet when prescribed for metabolic risk reduction?","options":["Cream-based pasta with bacon","Large portions of processed meats and cheese","Fried chicken, fries, and milkshake","Grilled fish, steamed vegetables, and a modest portion of brown rice"],"answer":3,"rationales":["Cream and bacon increase saturated fat and calories.","Processed meats and cheese can be high in sodium and saturated fat.","Fried foods and milkshake are high in calories and fat.","Lean protein, vegetables, and controlled portions provide nutrients with less added fat and energy density."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-081","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Endocrine assessment","question":"Which assessment is especially important when evaluating a client with a suspected endocrine disorder?","options":["Trends in vital signs, weight, skin, mentation, activity tolerance, intake/output, and relevant hormone/electrolyte labs","Only the most recent temperature","Only the client’s pain score","Only the medication list without symptoms or labs"],"answer":0,"rationales":["Endocrine disorders affect multiple systems; trend assessment findings with targeted labs and medication history.","Temperature alone is insufficient to assess endocrine function.","Pain is only one component and may not reflect endocrine status.","Medication history matters but must be integrated with assessment and diagnostics."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-082","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Endocrine diagnostics","question":"Which lab pair is most useful when evaluating thyroid function?","options":["Troponin and CK-MB","Amylase and lipase","TSH and free T4","Rheumatoid factor and ANA"],"answer":2,"rationales":["These assess myocardial injury.","These assess pancreatic injury.","TSH and free T4 help distinguish primary thyroid disorders and central causes.","These are autoimmune markers, not thyroid function tests."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-083","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Endocrine diagnostics","question":"Which lab should be monitored closely in a client receiving insulin therapy for DKA?","options":["Serum bilirubin only","Serum potassium","Rheumatoid factor","ANA"],"answer":1,"rationales":["Bilirubin is not the primary electrolyte safety issue during insulin therapy.","Insulin shifts potassium into cells, so serial potassium monitoring is essential to prevent dysrhythmias.","Rheumatoid factor is not relevant to DKA treatment.","ANA is not relevant to DKA treatment."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-084","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Medication safety","question":"A client is prescribed a new endocrine medication. Which nursing action best supports safe administration?","options":["Administer without reviewing the medication list","Teach the client to stop medication if any expected effect occurs","Use the same dose for every client regardless of age or renal function","Verify indication, baseline labs, contraindications, timing, adverse effects, and required monitoring"],"answer":3,"rationales":["Medication reconciliation and assessment are core safety steps.","Clients should report concerning effects and follow specific instructions, not independently stop all therapy.","Doses often depend on weight, labs, organ function, and clinical response.","Endocrine medications can significantly alter metabolism, electrolytes, glucose, and cardiovascular status; individual assessment is essential."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-085","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Priority — airway","question":"Which client should the nurse assess first?","options":["A client with myasthenia gravis who has a weak cough and new difficulty swallowing","A client with stable rheumatoid arthritis requesting pain medication","A client with hypothyroidism reporting chronic constipation","A client with Sjögren syndrome requesting artificial tears"],"answer":0,"rationales":["Bulbar weakness can progress to aspiration and respiratory failure; airway threats take priority.","Pain should be treated, but this is not an immediate airway threat.","Constipation is important but generally not the immediate priority.","Dry eyes need care but are not immediately life-threatening."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-086","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Priority — endocrine emergency","question":"Which client requires immediate intervention?","options":["A client with chronic acromegaly reporting shoe-size changes","A client with stable hypothyroidism who feels cold","A client with controlled diabetes requesting a meal","A client with hyperthyroidism who has fever, severe tachycardia, and confusion"],"answer":3,"rationales":["Gradual acral enlargement is a chronic acromegaly finding.","Cold intolerance is expected in hypothyroidism and is not an emergency alone.","Meal coordination is routine care for stable diabetes.","Fever, severe tachycardia, and altered mental status suggest thyroid storm."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-087","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Priority — calcium","question":"Which postoperative client should the nurse see first?","options":["A client with a dry dressing and stable vital signs","A client after thyroidectomy reporting mild incisional pain","A client after thyroidectomy reporting perioral tingling and hand spasms","A client asking when discharge teaching will begin"],"answer":2,"rationales":["A dry dressing and stable vital signs are reassuring.","Mild pain is expected and can be managed after urgent issues.","Paresthesia and spasms suggest acute hypocalcemia/tetany, which can progress to laryngospasm and seizures.","Teaching can wait until immediate clinical concerns are addressed."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-088","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Priority — adrenal","question":"A client with chronic steroid use stopped prednisone abruptly and now has vomiting and hypotension. What is the priority concern?","options":["Thyroid storm","Hyperparathyroidism","SIADH","Acute adrenal insufficiency/adrenal crisis"],"answer":3,"rationales":["Thyroid storm is a hyperthyroid emergency.","Hyperparathyroidism causes hypercalcemia and is not the immediate likely cause.","SIADH causes water retention and hyponatremia, but abrupt steroid withdrawal points to adrenal crisis.","Chronic steroid therapy suppresses the HPA axis; abrupt withdrawal can precipitate adrenal crisis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-089","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Vaccine safety","question":"A client receiving high-dose immunosuppressive therapy asks about a live vaccine. What is the best response?","options":["All live vaccines are required during immunosuppression","Take an extra immunosuppressant dose before vaccination","Do not receive it until the prescribing team evaluates safety and timing","Live vaccines are always safer than inactivated vaccines"],"answer":2,"rationales":["Live vaccines may be contraindicated during significant immunosuppression.","Extra immunosuppression does not improve vaccine safety.","Live vaccines may cause infection in significantly immunosuppressed clients; timing and alternatives require clinician review.","Inactivated vaccines are generally safer for immunocompromised clients, though response may be reduced."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-090","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Therapeutic communication","question":"A client newly diagnosed with HIV says, “My life is over.” Which response is most therapeutic?","options":["“This is a lot to take in. What concerns you most right now?”","“You need to be positive.”","“You should not feel that way.”","“At least it is not cancer.”"],"answer":0,"rationales":["This acknowledges emotion and invites the client to express concerns without judgment.","This places pressure on the client rather than exploring needs.","This dismisses the client’s feelings.","This minimizes the client’s experience and makes an inappropriate comparison."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-091","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Client-centered care","question":"A client with lupus declines a treatment because of a cultural or spiritual belief. What should the nurse do first?","options":["Ask family to make the decision without the client","Threaten discharge if treatment is declined","Explore the client’s concerns and preferences, provide accurate information, and collaborate on an acceptable plan","Document noncompliance and end the discussion"],"answer":2,"rationales":["The competent client remains the decision-maker unless legally determined otherwise.","Coercion violates patient-centered ethical care.","Respect autonomy, assess understanding and values, and collaborate on informed decisions.","This is judgmental and fails to assess the reason for refusal."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-092","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Medication teaching — iodine","question":"Why may iodine or potassium iodide be prescribed before thyroid surgery for hyperthyroidism?","options":["To increase T3 and T4 production","To reduce thyroid vascularity and hormone release before surgery","To treat hypocalcemia","To replace cortisol"],"answer":1,"rationales":["Iodine does not increase thyroid hormone production in this therapeutic context.","Iodide can acutely inhibit thyroid hormone release and reduce gland vascularity before surgery when given in the prescribed sequence.","Calcium replacement treats hypocalcemia.","Cortisol replacement treats adrenal insufficiency."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-093","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroid medication safety","question":"Which symptom should a client taking methimazole or PTU report immediately?","options":["Mild temporary change in appetite only","Mild thirst after exercise","Fever, sore throat, jaundice, or dark urine","A single episode of hiccups"],"answer":2,"rationales":["Appetite change alone is not the key urgent warning.","Thirst after exercise is nonspecific and not a key medication toxicity signal.","Fever/sore throat may signal agranulocytosis; jaundice/dark urine may indicate liver injury, especially with PTU.","Hiccups are not a major thionamide warning sign."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-094","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Adrenal hormone function","question":"Which statement correctly describes aldosterone?","options":["It promotes sodium and water retention and potassium excretion.","It stimulates thyroid hormone release.","It causes the kidneys to retain potassium and excrete sodium.","It lowers blood glucose by moving glucose into cells."],"answer":0,"rationales":["Aldosterone increases renal sodium reabsorption and potassium secretion, supporting blood volume and pressure.","TSH stimulates thyroid hormone production.","This reverses aldosterone’s usual effects.","Insulin lowers blood glucose by promoting cellular uptake."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-095","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Cortisol function","question":"Which physiologic effect is associated with cortisol?","options":["Causes immediate calcium deposition in bone","Suppresses all cardiovascular responses","Directly lowers blood glucose in all circumstances","Raises blood glucose and supports the stress response"],"answer":3,"rationales":["Cortisol does not directly cause immediate bone calcium deposition.","Cortisol has broad effects and does not suppress all cardiovascular responses.","Cortisol tends to raise glucose and can cause hyperglycemia.","Cortisol supports stress adaptation and increases glucose availability through metabolic effects."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-096","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Parathyroid function","question":"What is the primary role of parathyroid hormone (PTH)?","options":["Regulate blood glucose as the primary hormone","Control thyroid T3 and T4 release","Regulate ADH release from the posterior pituitary","Regulate calcium and phosphate balance"],"answer":3,"rationales":["Insulin and glucagon are the primary glucose-regulating hormones.","TSH regulates thyroid hormone production.","ADH is released from the posterior pituitary.","PTH maintains calcium balance and influences phosphate handling through bone, kidneys, and vitamin D activation."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-097","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Pituitary function","question":"Which statement best describes the pituitary gland?","options":["It secretes hormones that regulate several other endocrine glands.","It produces parathyroid hormone.","It produces insulin for glucose uptake.","It is the main site of aldosterone production."],"answer":0,"rationales":["The pituitary releases trophic hormones that regulate thyroid, adrenal, gonadal, and growth functions.","PTH is produced by the parathyroid glands.","Insulin is produced by pancreatic beta cells.","Aldosterone is produced by the adrenal cortex."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-098","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Growth hormone safety","question":"A child receiving somatropin reports new hip or knee pain and limping. What should the nurse advise?","options":["Report promptly to the prescriber for evaluation","Stop all fluids","Double the next dose","Continue treatment and ignore the symptom"],"answer":0,"rationales":["Hip/knee pain and limping during growth hormone therapy require evaluation for orthopedic complications such as slipped capital femoral epiphysis.","Fluid restriction is unrelated.","Dose escalation is unsafe and unrelated.","This symptom should not be ignored."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-099","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Growth hormone adverse effects","question":"Which finding should be monitored in a client receiving somatropin?","options":["Hypoglycemia as the only possible adverse effect","Permanent neutropenia","Hyperglycemia and signs of intracranial hypertension such as severe headache or visual changes","Severe hyponatremia in every client"],"answer":2,"rationales":["Hyperglycemia, not hypoglycemia, is a recognized concern.","Neutropenia is not a typical somatropin adverse effect.","Somatropin can worsen glucose tolerance and rarely cause intracranial hypertension; monitor for headache/visual symptoms.","Hyponatremia is not an expected universal effect."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-100","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Endocrine feedback","question":"A client has low free T4 and a low TSH. Which disorder should the nurse consider?","options":["Primary hypothyroidism","Primary hyperthyroidism","Central hypothyroidism from pituitary or hypothalamic dysfunction","Thyroid storm"],"answer":2,"rationales":["Primary hypothyroidism usually causes elevated TSH with low T4.","Primary hyperthyroidism typically causes low TSH with high T3/T4.","In central hypothyroidism, inadequate pituitary/hypothalamic stimulation results in low TSH and low thyroid hormone.","Thyroid storm is a severe hyperthyroid emergency."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-101","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Pulse oximetry","question":"A client with an autoimmune neuromuscular disorder has normal oxygen saturation but increasing work of breathing. What should the nurse recognize?","options":["Wait until cyanosis appears","Normal saturation rules out respiratory failure","Encourage the client to sleep without reassessment","Pulse oximetry can remain normal early; assess ventilation and respiratory muscle strength"],"answer":3,"rationales":["Cyanosis is a late and dangerous sign; do not wait.","Normal SpO2 does not rule out impending ventilatory failure.","Ongoing monitoring is essential when respiratory muscle weakness is possible.","Oxygen saturation may not detect early hypoventilation; respiratory mechanics and clinical effort are essential."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-102","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Laboratory interpretation","question":"Which test is most useful for identifying inflammation but is nonspecific?","options":["Erythrocyte sedimentation rate (ESR)","Urine specific gravity","Hemoglobin A1c","Serum TSH"],"answer":0,"rationales":["ESR is a nonspecific marker of inflammation and may be elevated in autoimmune disease.","Urine specific gravity helps assess urine concentration/hydration.","A1c measures long-term glycemic control.","TSH evaluates thyroid function."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-103","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Laboratory interpretation","question":"Which test is commonly used as a screening marker for systemic lupus erythematosus?","options":["Urine ketones","Serum troponin","Serum lipase","Antinuclear antibody (ANA)"],"answer":3,"rationales":["Urine ketones assess ketone production.","Troponin assesses myocardial injury.","Lipase assesses pancreatic injury.","ANA is sensitive for SLE but can be positive in other conditions and in some healthy people."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-104","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Laboratory interpretation","question":"Which test is most directly used to assess rheumatoid arthritis-associated autoantibodies?","options":["TSH and free T4","Serum osmolality and urine sodium","Serum cortisol and ACTH","Rheumatoid factor and anti-CCP antibodies"],"answer":3,"rationales":["These assess thyroid function.","These help evaluate water-balance disorders such as SIADH.","These assess adrenal function.","RF and anti-CCP support RA evaluation; anti-CCP is more specific."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-105","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunoglobulins","question":"Which immunoglobulin is most associated with immediate allergic reactions and anaphylaxis?","options":["IgA","IgM","IgG","IgE"],"answer":3,"rationales":["IgA is prominent in mucosal secretions.","IgM is often the first antibody produced in a primary immune response.","IgG is the major circulating antibody and provides long-term immunity.","IgE binds to mast cells and basophils and participates in immediate hypersensitivity reactions."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-106","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunoglobulins","question":"Which immunoglobulin is the major antibody in blood and can cross the placenta?","options":["IgM","IgE","IgA","IgG"],"answer":3,"rationales":["IgM is a large pentamer and does not cross the placenta.","IgE is associated with allergic responses.","IgA is prominent in mucosal secretions such as saliva, tears, and breast milk.","IgG is the most abundant serum immunoglobulin and crosses the placenta to provide passive fetal immunity."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-107","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunoglobulins","question":"Which immunoglobulin is especially important in mucosal secretions, saliva, tears, and breast milk?","options":["IgD","IgM","IgE","IgA"],"answer":3,"rationales":["IgD primarily functions as a B-cell receptor.","IgM is the first antibody in a primary response.","IgE is associated with allergic and parasitic responses.","IgA protects mucosal surfaces and is found in secretions."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-108","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV diagnostics","question":"Which statement about HIV testing is accurate?","options":["A negative test immediately after exposure always excludes infection.","A viral load test measures antibody concentration.","Screening immunoassays are followed by supplemental testing when reactive; nucleic acid testing can detect HIV RNA.","A single CD4 count confirms HIV infection."],"answer":2,"rationales":["Testing during the window period may be negative; follow recommended repeat testing.","Viral load measures HIV RNA, not antibody concentration.","Modern HIV diagnosis uses antigen/antibody screening with supplemental differentiation testing; nucleic acid testing detects viral RNA in selected situations.","CD4 count assesses immune status, not the primary diagnostic confirmation."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-109","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"HIV monitoring","question":"What does an HIV viral load measure?","options":["The amount of circulating insulin","The number of red blood cells","The amount of HIV RNA in the blood","The number of neutrophils"],"answer":2,"rationales":["Insulin is a hormone and is not measured by HIV viral load.","Red blood cells are measured by CBC.","Viral load quantifies circulating HIV RNA and is used to monitor response to antiretroviral therapy.","Neutrophils are measured by CBC."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-110","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Rheumatoid factor","question":"A positive rheumatoid factor result should be interpreted how?","options":["It confirms RA in every client.","It measures the severity of joint destruction directly.","It supports RA evaluation but is not diagnostic by itself.","It confirms systemic lupus."],"answer":2,"rationales":["RF is not specific enough to confirm RA alone.","RF does not directly quantify structural joint damage.","RF can be positive in RA and other conditions; interpret with symptoms and more specific tests such as anti-CCP.","ANA and other findings are more relevant to lupus evaluation."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-111","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Creatinine","question":"Why should serum creatinine and estimated GFR be monitored in a client with lupus?","options":["To detect possible renal involvement and guide medication safety.","To measure oxygen-carrying capacity.","To confirm anaphylaxis.","To diagnose thyroid storm."],"answer":0,"rationales":["Lupus nephritis can impair kidney function; renal labs also guide dosing and toxicity monitoring for some medications.","Hemoglobin/hematocrit assess oxygen-carrying capacity.","Anaphylaxis is a clinical emergency, not diagnosed by creatinine.","Thyroid storm is assessed clinically with thyroid tests."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-112","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Pulse oximetry","question":"What does pulse oximetry estimate?","options":["Serum pH","Peripheral arterial oxygen saturation (SpO2)","Hemoglobin concentration","Serum carbon dioxide level directly"],"answer":1,"rationales":["pH is measured with arterial or venous blood gas testing.","Pulse oximetry estimates oxygen saturation; it does not directly measure ventilation, PaCO2, hemoglobin, or pH.","Hemoglobin is measured with a CBC.","PaCO2 is assessed with blood gas testing."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-113","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"DMARDs","question":"Which safety monitoring is important for a client taking methotrexate?","options":["No laboratory monitoring is needed.","Take it every day for rheumatoid arthritis.","CBC and liver function tests; report fever, sore throat, bruising, or jaundice.","Use live vaccines without checking with the prescriber."],"answer":2,"rationales":["Routine monitoring is required.","Daily dosing can cause fatal toxicity; verify the prescribed weekly schedule.","Methotrexate can cause bone marrow suppression and hepatotoxicity; it is generally taken weekly for RA, not daily.","Immunosuppression affects vaccine safety; consult the care team."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-114","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Calcineurin inhibitors","question":"Which adverse effect is a major concern with calcineurin inhibitors such as tacrolimus or cyclosporine?","options":["Severe hypocalcemia in all clients","Permanent hypoglycemia","Nephrotoxicity and increased infection risk","Immediate thyroid storm"],"answer":2,"rationales":["Hypocalcemia is not the defining toxicity.","They are not glucose-lowering medications.","Calcineurin inhibitors suppress T-cell activation and can cause nephrotoxicity, hypertension, neurotoxicity, and infection risk.","They do not cause thyroid storm."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-115","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Immunosuppressants","question":"Which teaching is appropriate for a client taking immunosuppressants?","options":["Stop medication whenever feeling well.","Receive live vaccines routinely without review.","Report fever promptly and avoid live vaccines unless specifically cleared.","Ignore wounds if there is no redness."],"answer":2,"rationales":["Stopping therapy can cause rejection or disease flare.","Live vaccines may be contraindicated.","Immunosuppression increases infection risk and may blunt inflammatory signs; vaccine plans require review.","Inflammatory signs may be muted; wounds still need monitoring."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-116","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Monoclonal antibodies","question":"What is an important nursing consideration before administering many biologic/monoclonal antibody therapies?","options":["Give the medication during an active severe infection without consultation.","Skip baseline assessment because the medication is not immunosuppressive.","Screen for latent infections such as tuberculosis and hepatitis as indicated.","Assume there is no infection risk because the drug is targeted."],"answer":2,"rationales":["Active infection may require delaying therapy and contacting the prescriber.","Baseline screening and monitoring are important.","Many biologics alter immune pathways and can reactivate latent infection; follow screening and monitoring protocols.","Targeted therapies can still cause serious immunosuppression and infection risk."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-117","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Antihistamines","question":"What effect should the nurse teach about first-generation antihistamines?","options":["They replace epinephrine during anaphylaxis.","Severe hypoglycemia in all clients.","Increased alertness and improved coordination.","Drowsiness and anticholinergic effects such as dry mouth and urinary retention."],"answer":3,"rationales":["Antihistamines do not replace epinephrine for anaphylaxis.","Hypoglycemia is not a routine effect.","Sedation can impair coordination and driving.","First-generation antihistamines cross the blood-brain barrier and can cause sedation and anticholinergic effects."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-118","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Epinephrine","question":"Which assessment is important after IM epinephrine for anaphylaxis?","options":["Assess only the skin rash.","Avoid repeat assessment because epinephrine acts permanently.","Discharge immediately if itching improves.","Reassess airway, breathing, blood pressure, heart rate, and response; monitor for recurrence."],"answer":3,"rationales":["Skin findings alone do not show whether airway or shock is resolving.","Epinephrine is not permanently protective.","Observation is needed because symptoms can recur.","Anaphylaxis can be biphasic or persistent; monitor cardiopulmonary status and be prepared for additional treatment."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-119","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Vasopressin/desmopressin","question":"Which adverse effect should be monitored in a client receiving desmopressin for central diabetes insipidus?","options":["Water intoxication and hyponatremia.","Severe hypercalcemia.","Agranulocytosis.","Hypernatremia from excessive water loss as the expected treatment effect."],"answer":0,"rationales":["Excess antidiuretic effect can cause water retention and dilutional hyponatremia; monitor sodium, weight, and fluid balance.","Calcium is not the key desmopressin toxicity.","Agranulocytosis is not a typical desmopressin adverse effect.","Effective therapy should reduce water loss; hypernatremia suggests inadequate control."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-120","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Vasopressin antagonists","question":"A client with SIADH receives a vasopressin receptor antagonist. What should the nurse monitor?","options":["Serum sodium, fluid balance, and neurologic status.","Only skin turgor once per shift.","Only blood glucose.","Only bowel sounds."],"answer":0,"rationales":["Vasopressin antagonists promote free-water excretion; monitor sodium correction, volume status, and neurologic changes.","Frequent fluid and sodium monitoring is needed, especially during correction.","Glucose is not the primary response measure.","Bowel sounds do not assess treatment response."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-121","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Glucocorticoids","question":"Which instruction is important for a client taking prednisone long term?","options":["Avoid reporting black stools.","Expect immunity to become stronger.","Stop suddenly when symptoms improve.","Take with food if directed, monitor glucose/infection, and do not stop abruptly."],"answer":3,"rationales":["Black/tarry stools may indicate GI bleeding and require prompt evaluation.","Immunity is suppressed, not strengthened.","Abrupt withdrawal can precipitate adrenal insufficiency.","Prednisone can irritate the GI tract, raise glucose, suppress immunity, and suppress the HPA axis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-122","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Mineralocorticoids","question":"Which finding suggests fludrocortisone is producing excessive mineralocorticoid effects?","options":["Hypotension, dehydration, and hyperkalemia.","Low body temperature and bradycardia.","Severe hypoglycemia.","Hypertension, edema, and hypokalemia."],"answer":3,"rationales":["These findings suggest inadequate mineralocorticoid effect or adrenal insufficiency.","These are more consistent with hypothyroidism.","Hypoglycemia is not the key fludrocortisone toxicity.","Fludrocortisone promotes sodium/water retention and potassium excretion; monitor BP, edema, and potassium."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-123","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroid replacement","question":"Which medication is used to replace thyroid hormone in hypothyroidism?","options":["Propylthiouracil.","Levothyroxine.","Radioactive iodine.","Methimazole."],"answer":1,"rationales":["PTU blocks thyroid hormone synthesis and peripheral T4-to-T3 conversion.","Levothyroxine is synthetic T4 used for thyroid hormone replacement.","Radioactive iodine ablates thyroid tissue in selected hyperthyroid conditions.","Methimazole blocks thyroid hormone synthesis."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-124","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Thyroid synthesis inhibitors","question":"How do methimazole and propylthiouracil help treat hyperthyroidism?","options":["They increase TSH secretion.","They directly replace cortisol.","They replace T4.","They inhibit thyroid hormone synthesis; PTU also reduces peripheral conversion of T4 to T3."],"answer":3,"rationales":["Thionamides do not increase pituitary TSH as their treatment mechanism.","Cortisol is replaced with glucocorticoids.","Levothyroxine replaces T4.","Thionamides reduce new thyroid hormone production; PTU also inhibits peripheral conversion of T4 to T3."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-125","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Iodine therapy","question":"Why is potassium iodide given after a thionamide in thyroid storm protocols?","options":["To treat hypocalcemia.","To inhibit release of stored thyroid hormone after synthesis has been blocked.","To replace ADH.","To stimulate thyroid hormone release."],"answer":1,"rationales":["Calcium gluconate treats symptomatic hypocalcemia.","Iodide acutely inhibits release of stored hormone; giving it after a thionamide helps avoid supplying substrate before synthesis is blocked.","Desmopressin replaces ADH activity.","Iodide is used to suppress release, not stimulate it."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-126","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Therapeutic devices","question":"A client with diabetes is using an insulin pump. Which instruction is most important?","options":["Remove the pump whenever glucose is elevated and take no insulin.","Stop basal insulin overnight without a prescribed plan.","Ignore unexplained hyperglycemia if the pump screen is on.","Know the backup plan for insulin delivery and check glucose/ketones when ill or glucose is high."],"answer":3,"rationales":["Stopping insulin can precipitate DKA.","Basal insulin should not be stopped without a specific clinical plan.","High glucose may indicate infusion-set failure; troubleshoot and follow sick-day guidance.","Pump interruption can rapidly cause insulin deficiency and DKA because many pumps use rapid-acting insulin only."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-127","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Telemetry","question":"Why may telemetry be appropriate for a client with severe hypo- or hypercalcemia?","options":["Calcium abnormalities can alter cardiac conduction and cause dysrhythmias.","Telemetry directly measures serum calcium.","Telemetry measures kidney filtration.","Calcium has no effect on the heart."],"answer":0,"rationales":["Severe calcium disturbances can prolong or shorten QT intervals and contribute to dysrhythmias.","Serum calcium requires laboratory testing.","Kidney function is assessed with labs such as creatinine/eGFR.","Calcium affects myocardial and neuromuscular function."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-128","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"IV access","question":"Why is reliable IV access important in an endocrine emergency such as adrenal crisis or DKA?","options":["It is used only for nutrition.","It allows timely administration of fluids, insulin/electrolyte therapy, and emergency medications.","It prevents all dysrhythmias.","It replaces the need for laboratory monitoring."],"answer":1,"rationales":["IV access has many urgent medication and fluid uses, not only nutrition.","These emergencies often require rapid IV resuscitation and carefully monitored medications/electrolytes.","IV access does not eliminate dysrhythmia risk; monitoring and correction are still needed.","Labs are essential to guide treatment."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-129","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Pyridostigmine mechanism","question":"How does pyridostigmine improve muscle strength in myasthenia gravis?","options":["It blocks acetylcholine receptors.","It inhibits acetylcholinesterase, allowing acetylcholine to remain available longer.","It destroys the antibodies that attack the neuromuscular junction.","It directly stimulates the thyroid gland."],"answer":1,"rationales":["Blocking acetylcholine receptors would worsen neuromuscular transmission.","Pyridostigmine is an acetylcholinesterase inhibitor. It slows acetylcholine breakdown and improves signaling at the neuromuscular junction.","Pyridostigmine does not remove the autoimmune antibodies.","It has no thyroid-stimulating action."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-130","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"IVIG","question":"A client with Guillain-Barré syndrome is prescribed IV immunoglobulin (IVIG). What is the purpose of this treatment?","options":["To directly stimulate skeletal muscle contraction.","To replace thyroid hormone.","To modulate the immune response and reduce the effects of harmful antibodies.","To increase acetylcholine breakdown."],"answer":2,"rationales":["IVIG does not directly stimulate muscle contraction.","Thyroid hormone replacement does not treat Guillain-Barré syndrome.","IVIG provides pooled immunoglobulins that modify immune activity in selected autoimmune conditions.","IVIG does not act as an acetylcholinesterase."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-131","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Plasmapheresis","question":"How does plasmapheresis help treat Guillain-Barré syndrome?","options":["It removes circulating plasma antibodies and replaces the removed plasma with replacement fluid.","It increases production of thyroid hormones.","It permanently repairs damaged peripheral nerves in one treatment.","It increases acetylcholine release at the neuromuscular junction."],"answer":0,"rationales":["Plasma exchange removes circulating antibodies and other plasma components that contribute to the immune attack.","It does not affect thyroid hormone production.","Nerve recovery takes time; plasmapheresis does not instantly repair nerves.","It does not directly increase acetylcholine release."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-132","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Plasmapheresis monitoring","question":"During plasmapheresis, which findings should the nurse monitor closely?","options":["Hypertension and hyperglycemia only.","Hypotension, bleeding, and signs of hypocalcemia such as tingling or muscle cramps.","Excessive thyroid hormone production.","Increased deep tendon reflexes only."],"answer":1,"rationales":["These are not the key complications associated with plasma exchange.","Plasma exchange can cause hemodynamic changes, bleeding/coagulation changes, and citrate-related hypocalcemia.","Plasmapheresis does not stimulate thyroid hormone production.","Reflexes alone do not assess the major treatment complications."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-133","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Propranolol","question":"A client with hyperthyroidism is prescribed propranolol. Which statement best describes the purpose of this medication?","options":["It destroys thyroid tissue permanently.","It replaces missing thyroid hormone.","It controls symptoms such as tachycardia, tremors, and palpitations but does not stop thyroid hormone synthesis.","It immediately normalizes TSH."],"answer":2,"rationales":["Radioactive iodine or surgery may destroy or remove thyroid tissue; propranolol does not.","Levothyroxine replaces thyroid hormone in hypothyroidism.","Propranolol is a beta blocker used for symptomatic control while definitive thyroid treatment takes effect.","TSH may take time to respond and propranolol does not directly normalize it."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-134","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Propranolol safety","question":"Before administering propranolol to a client with hyperthyroidism, which assessment is most important?","options":["Heart rate and blood pressure.","Bowel sounds only.","Visual acuity only.","Urine color only."],"answer":0,"rationales":["Beta blockers can lower heart rate and blood pressure. Assess both and follow prescribed hold parameters.","Bowel sounds do not identify the major immediate beta-blocker safety concerns.","Visual acuity is not the primary pre-administration assessment for propranolol.","Urine color is not the key assessment before a beta blocker."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-135","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"PTU in pregnancy","question":"A pregnant client requires antithyroid medication during the first trimester. Which medication is generally preferred when treatment is necessary?","options":["Radioactive iodine.","Propylthiouracil (PTU).","Methimazole in every trimester.","Levothyroxine as an antithyroid drug."],"answer":1,"rationales":["Radioactive iodine is contraindicated during pregnancy.","PTU is generally preferred during the first trimester because methimazole has a risk of specific congenital abnormalities; PTU also carries serious liver-injury risk and requires provider monitoring.","Methimazole is generally avoided during the first trimester when an appropriate alternative is available.","Levothyroxine replaces thyroid hormone and does not treat hyperthyroidism."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-136","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Radioactive iodine safety","question":"Which client should not receive radioactive iodine treatment for hyperthyroidism?","options":["A nonpregnant adult with Graves disease.","A client with a toxic thyroid nodule who is not breastfeeding.","A pregnant or breastfeeding client.","A client who can follow radiation-safety instructions."],"answer":2,"rationales":["Radioactive iodine may be an option for selected nonpregnant clients.","It may be considered for selected patients after provider evaluation.","Radioactive iodine can harm the fetal or infant thyroid and is contraindicated during pregnancy and breastfeeding.","Following radiation-safety instructions is necessary but does not override pregnancy or breastfeeding contraindications."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-137","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Graves ophthalmopathy","question":"A client with Graves disease has exophthalmos and cannot completely close the eyelids. Which intervention helps prevent corneal injury?","options":["Use prescribed lubricating eye drops or ointment and protect the eyes as directed.","Restrict all fluids.","Rub the eyes frequently to stimulate tear production.","Stop eye lubrication once the redness improves."],"answer":0,"rationales":["Lubrication and prescribed eye protection help prevent exposure-related dryness and corneal damage.","Fluid restriction does not protect the cornea.","Rubbing can injure the eye and worsen irritation.","Eye protection should continue according to the prescribed plan, not stop solely because redness improves."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-138","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Epinephrine auto-injector teaching","question":"Which instruction is appropriate for a client who carries an epinephrine auto-injector?","options":["Store it in a hot vehicle so it is easy to reach.","Check the expiration date and solution appearance regularly, and avoid exposure to extreme heat or cold.","Use it only after an oral antihistamine fails.","Remove the safety cap before storing it."],"answer":1,"rationales":["Extreme heat can damage the medication and a vehicle can reach unsafe temperatures.","Regular inspection and proper storage help ensure the medication remains usable; follow the specific product instructions.","Epinephrine is first-line for anaphylaxis and should not be delayed for an antihistamine trial.","Keep the device assembled with its safety features in place until needed."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null},{"id":"CH5-HY-139","moduleId":"ch5-high-yield-immunity-metabolism","category":"High-Yield Study Guide","tag":"Heparin and atrial fibrillation","question":"A client with atrial fibrillation related to hyperthyroidism is prescribed heparin. Which statement best explains the purpose of heparin?","options":["It lowers T3 and T4 levels.","It treats exophthalmos.","It reduces the risk of clot formation; it does not treat the underlying hyperthyroidism.","It converts atrial fibrillation directly to a normal rhythm."],"answer":2,"rationales":["Antithyroid medications treat excess thyroid hormone production.","Eye lubricants and other directed therapies address eye symptoms.","Heparin is an anticoagulant used when indicated to reduce thromboembolic risk; it does not correct thyroid hormone excess.","Heparin does not convert the cardiac rhythm."],"case":null,"noteId":"ch5-unit-syllabus-and-ati-endocrine-engage","noteTitle":"Chapter 5 Unit Syllabus + ATI Endocrine Function Review","conceptId":null}],"ch5-endocrine-function-ati-deep-dive":[{"id":"CH5-ENDO-001","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Growth hormone deficiency","question":"A child is being evaluated for growth hormone deficiency. Which finding best supports the diagnosis?","options":["New heat intolerance, tremor, and tachycardia","Growth velocity is persistently below the expected range for age and developmental stage","Early closure of all growth plates with accelerated height gain","Rapid linear growth with enlarged hands and feet"],"answer":1,"rationales":["These findings suggest excess thyroid hormone, not growth hormone deficiency.","Reduced growth velocity is a key clue; evaluation includes growth history, physical/developmental assessment, and endocrine testing.","Growth hormone deficiency does not cause accelerated height gain.","This suggests excess growth hormone rather than deficiency."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-002","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Growth hormone diagnostics","question":"Which diagnostic study may be used to evaluate suspected growth hormone deficiency?","options":["Rheumatoid factor","Growth hormone stimulation testing","Fecal occult blood testing","24-hour urine ketones only"],"answer":1,"rationales":["Rheumatoid factor is an autoimmune marker sometimes associated with rheumatoid arthritis.","Stimulation testing assesses whether the pituitary can release an adequate amount of growth hormone.","This evaluates possible gastrointestinal bleeding, not growth hormone secretion.","Urine ketones evaluate ketosis and do not diagnose growth hormone deficiency."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-003","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Somatropin safety","question":"A client receiving somatropin reports new hip pain and a limp. What should the nurse do?","options":["Notify the provider promptly and anticipate evaluation for a musculoskeletal complication","Tell the client to stop all fluids for 12 hours","Recommend doubling the next dose","Reassure the client that this is an expected sign of bone growth"],"answer":0,"rationales":["New hip or knee pain and limping during growth hormone therapy require prompt evaluation; the teaching material specifically emphasizes reporting these symptoms.","Fluid restriction does not address the potential medication-related complication.","The dose should never be independently increased; the symptom requires assessment.","Pain and limping should not be dismissed as expected."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-004","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Somatropin administration","question":"Which instruction is appropriate when administering prescribed somatropin?","options":["Give by the prescribed subcutaneous or intramuscular route, rotate sites, and do not shake the medication","Continue treatment after epiphyseal fusion without reassessment","Administer orally with a high-fat meal","Massage the same injection site vigorously after every dose"],"answer":0,"rationales":["The source identifies IM or subcutaneous administration, site rotation, and avoiding vigorous shaking.","The source notes therapy is discontinued after epiphyseal fusion or final height is reached.","Somatropin is not administered orally; it is given by injection.","Injection sites should be rotated; vigorous massage is not the recommended teaching."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-005","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Somatropin adverse effects","question":"Which finding should the nurse monitor in a client receiving somatropin?","options":["Reduced risk of respiratory infection","Hyperglycemia","Severe hypoglycemia as the expected effect","Persistent bradycardia as the defining adverse effect"],"answer":1,"rationales":["The source advises assessing for respiratory infection rather than expecting protection.","Somatropin can increase blood glucose; monitor for signs of diabetes and glucose changes.","Hyperglycemia, not hypoglycemia, is the listed metabolic adverse effect.","Bradycardia is not the characteristic adverse effect highlighted in the source."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-006","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Gigantism","question":"A client with childhood-onset excess growth hormone has extreme height and rapid linear growth. Which disorder is most likely?","options":["Myxedema","Acromegaly","Pituitary dwarfism","Gigantism"],"answer":3,"rationales":["Myxedema is severe hypothyroidism and does not cause this growth pattern.","Acromegaly is excess growth hormone after epiphyseal closure in adulthood.","Growth hormone deficiency causes reduced growth, not extreme height.","Excess growth hormone before epiphyseal closure causes excessive linear growth and extreme height."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-007","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Acromegaly treatment","question":"Which treatment may be used for acromegaly caused by excess growth hormone?","options":["Fludrocortisone monotherapy","Somatostatin analog therapy","Routine levothyroxine replacement","Desmopressin as the primary therapy"],"answer":1,"rationales":["Fludrocortisone replaces mineralocorticoid activity in adrenal insufficiency.","Somatostatin analogs suppress growth hormone secretion and are among the listed treatments for acromegaly.","Levothyroxine replaces thyroid hormone and does not treat excess growth hormone.","Desmopressin treats central diabetes insipidus, not acromegaly."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-008","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Gigantism vs acromegaly","question":"Which statement correctly compares gigantism and acromegaly?","options":["Acromegaly is caused by low growth hormone","Both occur only in infancy","Gigantism is caused by low thyroid hormone","Gigantism occurs before growth-plate closure; acromegaly occurs after growth-plate closure"],"answer":3,"rationales":["Acromegaly results from excess growth hormone.","Acromegaly occurs in adults; gigantism occurs during childhood/adolescence.","Gigantism is associated with excess growth hormone, often from a pituitary adenoma.","The timing relative to epiphyseal closure distinguishes the two disorders."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-009","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Aldosterone","question":"Which electrolyte action is associated with aldosterone?","options":["Lowers blood glucose by increasing insulin release","Retains sodium and promotes potassium excretion","Promotes calcium excretion and phosphate retention","Retains potassium and excretes sodium"],"answer":1,"rationales":["Aldosterone does not directly function as an insulin-releasing hormone.","Aldosterone supports sodium and water retention and potassium secretion, helping regulate blood pressure and volume.","Calcium/phosphate regulation is primarily associated with parathyroid hormone and vitamin D.","This reverses aldosterone's primary renal effects."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-010","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Cortisol","question":"Which physiologic effect is most closely associated with cortisol?","options":["Causes the kidneys to retain potassium and excrete sodium","Lowers blood glucose in the fasting state","Raises blood glucose and supports the stress response by altering carbohydrate, fat, and protein metabolism","Directly increases thyroid-stimulating hormone release"],"answer":2,"rationales":["That describes the opposite of aldosterone's main effect.","Cortisol tends to increase glucose availability, not lower it.","Cortisol is a stress hormone that increases glucose availability and affects metabolism of carbohydrates, fats, and proteins.","TSH is regulated through the hypothalamic-pituitary-thyroid axis."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-011","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Adrenal crisis risk","question":"A client with chronic adrenal insufficiency has stopped long-term prednisone abruptly. Which complication is the priority concern?","options":["Thyroid storm","Acute adrenal insufficiency or adrenal crisis","Hypercalcemic crisis","Myasthenic crisis"],"answer":1,"rationales":["Thyroid storm is a life-threatening complication of severe thyrotoxicosis.","Abrupt cessation after prolonged corticosteroid therapy can suppress the hypothalamic-pituitary-adrenal axis and precipitate adrenal crisis.","This is not the expected immediate consequence of abrupt steroid withdrawal.","Myasthenic crisis is caused by severe neuromuscular weakness and respiratory compromise."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-012","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Primary Addison disease","question":"Which finding is more characteristic of primary Addison disease than secondary adrenal insufficiency?","options":["Exophthalmos and heat intolerance","Polyuria with very dilute urine","Hyperpigmentation and salt craving","Moon face and truncal obesity"],"answer":2,"rationales":["These findings are associated with hyperthyroidism, especially Graves disease.","This pattern is associated with diabetes insipidus.","Primary adrenal failure increases ACTH, which can cause hyperpigmentation; aldosterone deficiency contributes to salt craving and electrolyte changes.","These are classic manifestations of Cushing syndrome."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-013","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"ACTH stimulation","question":"A client is undergoing an ACTH stimulation test for suspected primary adrenal insufficiency. Which result is expected?","options":["Cortisol rises dramatically and remains elevated for days","TSH falls while T4 rises","Serum calcium rises immediately after ACTH","Cortisol fails to rise appropriately after administered ACTH"],"answer":3,"rationales":["A robust rise is not expected in primary adrenal failure.","This is a thyroid laboratory pattern, not an ACTH stimulation result.","Calcium is not the primary measurement in this stimulation test.","With primary adrenal gland failure, the adrenal cortex cannot respond adequately to ACTH, so cortisol does not rise as expected."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-014","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Addison replacement","question":"A client with Addison disease is prescribed hydrocortisone and fludrocortisone. What is the purpose of this combination?","options":["Suppress thyroid hormone and increase insulin","Treat hypercalcemia by increasing urinary calcium","Replace growth hormone and antidiuretic hormone","Replace glucocorticoid and mineralocorticoid activity"],"answer":3,"rationales":["These medications do not treat thyroid excess or diabetes in this way.","This is not the purpose of adrenal hormone replacement.","Neither medication replaces growth hormone or ADH.","Hydrocortisone replaces cortisol/glucocorticoid activity; fludrocortisone replaces aldosterone-like mineralocorticoid activity."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-015","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Corticosteroid teaching","question":"Which instruction is essential for a client taking chronic corticosteroid replacement for adrenal insufficiency?","options":["Double every dose whenever a dose is missed","Stop medication whenever appetite increases","Avoid wearing medical identification","Take medication exactly as prescribed and never stop it abruptly"],"answer":3,"rationales":["Missed-dose instructions should follow the prescription/provider guidance; automatic doubling is unsafe.","The client should not independently stop replacement therapy.","Medical identification is important for clients with adrenal insufficiency, especially during emergencies.","Abrupt discontinuation can precipitate adrenal insufficiency; adherence and provider-directed tapering are essential."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-016","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Addison laboratory pattern","question":"Which laboratory pattern is most consistent with untreated primary Addison disease?","options":["Hyponatremia, hyperkalemia, and low glucose","Hypercalcemia with low potassium only","Hypernatremia and concentrated urine","Hypernatremia, hypokalemia, and hyperglycemia"],"answer":0,"rationales":["Loss of aldosterone causes sodium loss and potassium retention; low cortisol can contribute to hypoglycemia.","Hypercalcemia may occur, but the classic pattern includes low sodium and high potassium.","This may occur with water deficit such as diabetes insipidus.","This pattern is more consistent with mineralocorticoid excess or other conditions, not Addison disease."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-017","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Cushing infection risk","question":"A client with Cushing syndrome is admitted with a mild fever and new confusion. Why is prompt assessment important?","options":["Cortisol excess suppresses immune and inflammatory responses, so infection may be serious with muted signs","Fever confirms adrenal insufficiency","Cortisol excess prevents all infections","Confusion is always an expected harmless effect"],"answer":0,"rationales":["Cushing syndrome increases infection risk and can mask typical inflammatory findings.","Fever does not confirm adrenal insufficiency; the client's risk profile requires evaluation.","Cortisol excess suppresses immune function and increases infection risk.","New confusion requires assessment, especially in a client at risk for infection and metabolic disturbance."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-018","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Cushing diagnostics","question":"Which diagnostic finding supports Cushing syndrome?","options":["Elevated cortisol on appropriate testing, such as late-night salivary cortisol or 24-hour urinary free cortisol","Persistently low cortisol with a failed ACTH response","Low TSH with elevated T3 and T4","Low serum glucose with ketonuria"],"answer":0,"rationales":["Cortisol testing, including salivary and 24-hour urine testing, is used to evaluate suspected hypercortisolism.","This suggests adrenal insufficiency rather than Cushing syndrome.","This is a pattern of primary hyperthyroidism.","This may occur with hypoglycemia/fasting or other metabolic states, not as a diagnostic test for Cushing syndrome."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-019","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Steroid taper","question":"A client develops Cushing syndrome after prolonged systemic corticosteroid therapy. Which plan should the nurse anticipate if the medication can be reduced?","options":["A gradual, prescribed taper","Abrupt discontinuation today","Switching to an unprescribed herbal product","Taking all doses at bedtime without a prescription change"],"answer":0,"rationales":["Long-term corticosteroids must generally be tapered under medical supervision to avoid adrenal crisis.","Abrupt discontinuation can precipitate adrenal insufficiency.","Medication changes require provider direction and evidence-based treatment.","Timing should follow the prescribed regimen; this does not address safe reduction."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-020","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Adrenalectomy preoperative care","question":"Before a planned adrenalectomy for Cushing syndrome, which intervention is appropriate?","options":["Optimize blood pressure and glucose, correct electrolyte abnormalities, and support nutritional status","Withhold all prescribed glucocorticoids","Encourage a low-protein diet to reduce tissue repair","Avoid monitoring potassium"],"answer":0,"rationales":["Preoperative care includes controlling hypertension and hyperglycemia, correcting hypokalemia, and improving protein/calorie status.","The source notes glucocorticoids are given before surgery; withholding them can be unsafe.","A high-calorie, high-protein diet may be used to correct protein depletion and support healing.","Potassium and other electrolytes require monitoring and correction."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-021","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Adrenalectomy complications","question":"Which postoperative complication is a priority after adrenalectomy?","options":["Expected severe polyuria from excess ADH","Hemorrhage and hemodynamic instability","Immediate permanent hyperthyroidism","Loss of parathyroid function"],"answer":1,"rationales":["This is not the defining immediate risk after adrenalectomy.","Postoperative hemorrhage and abrupt changes in hormone levels can destabilize blood pressure, fluid balance, and electrolytes.","Adrenalectomy does not directly cause thyroid hormone excess.","Parathyroid glands are not removed during adrenalectomy."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-022","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Adrenalectomy postoperative monitoring","question":"After adrenalectomy, which assessment best helps detect early deterioration?","options":["Checking TSH once and discontinuing monitoring","Frequent vital signs with fluid balance, glucose, electrolytes, and signs of shock or infection","Avoiding intake and output documentation","Weekly height measurements only"],"answer":1,"rationales":["Thyroid testing alone cannot detect the major postoperative risks.","Postoperative care includes close monitoring of hemodynamics, I&O, glycemic control, infection, and acute adrenal insufficiency.","Fluid balance monitoring is specifically important after adrenalectomy.","Height measurement does not detect acute postoperative instability."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-023","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Levothyroxine administration","question":"A client with hypothyroidism takes levothyroxine. Which timing instruction matches the ATI teaching in the lecture slides?","options":["Stop once TSH returns to normal","Take it consistently on an empty stomach, about 1 hour before food or 3 hours after a meal","Take it only when fatigue occurs","Take it with calcium supplements at breakfast"],"answer":1,"rationales":["Many clients require ongoing or lifelong replacement; do not stop without provider direction.","The lecture specifies taking levothyroxine 1 hour before a meal or 3 hours after a meal to support consistent absorption.","Levothyroxine is scheduled replacement therapy, not an as-needed medication.","Calcium can interfere with levothyroxine absorption; doses should be separated."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-024","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Levothyroxine safety","question":"Which client history requires the nurse to clarify a new levothyroxine prescription before administration?","options":["Use of a daily multivitamin taken at a separate time","Untreated adrenal insufficiency","A remote history of a healed ankle sprain","Stable seasonal allergies"],"answer":1,"rationales":["Mineral supplements may affect absorption if taken together, but a separated multivitamin is not the same as untreated adrenal insufficiency.","The slide lists untreated adrenal insufficiency among contraindications/conditions requiring attention before levothyroxine.","This does not affect levothyroxine administration.","Seasonal allergies alone are not the contraindication highlighted in the teaching material."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-025","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Hyperthyroidism cardiac complications","question":"A client with hyperthyroidism has a rapid irregular pulse and palpitations. Which complication is the nurse most concerned about?","options":["Severe bradycardia from slowed metabolism","Acute hypocalcemia as the only concern","Atrial fibrillation and possible cardiac failure","Nephrotic syndrome"],"answer":2,"rationales":["Bradycardia is more consistent with hypothyroidism.","Calcium disturbance is not the primary concern from this hyperthyroid cardiac presentation.","Excess thyroid hormone increases cardiac workload and can cause tachycardia, atrial fibrillation, and heart failure.","This is not a typical direct complication of hyperthyroidism."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-026","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Thionamide agranulocytosis","question":"A client taking methimazole develops fever and a sore throat. What is the priority instruction?","options":["Use aspirin and continue the medication without reporting symptoms","Hold the medication and contact the provider immediately for evaluation of possible agranulocytosis","Take an extra dose to suppress thyroid function faster","Wait until the next routine appointment"],"answer":1,"rationales":["Symptom masking without evaluation can delay recognition of a serious adverse effect.","Fever and sore throat may signal a dangerously low granulocyte count; urgent CBC/provider evaluation is needed.","Increasing the dose is unsafe and does not address possible agranulocytosis.","Possible agranulocytosis requires prompt assessment."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-027","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"PTU hepatotoxicity","question":"A client taking propylthiouracil reports dark urine, right upper-quadrant pain, and unusual fatigue. Which adverse effect should the nurse suspect?","options":["Expected harmless urine discoloration","Hepatotoxicity","Hypocalcemia","Growth hormone excess"],"answer":1,"rationales":["Dark urine with abdominal symptoms and fatigue should not be dismissed.","PTU can cause serious liver injury; these symptoms require prompt evaluation and liver testing.","Hypocalcemia causes paresthesia, cramps, tetany, and related neuromuscular findings.","These findings do not indicate growth hormone excess."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-028","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Post-thyroidectomy hypocalcemia","question":"After thyroidectomy, a client reports tingling around the mouth and develops hand spasms. Which complication should the nurse suspect?","options":["Acute hypocalcemia from impaired parathyroid function","Hypercalcemia from excess PTH","Thyroid storm","Hypernatremia from diabetes insipidus"],"answer":0,"rationales":["Parathyroid injury or manipulation during thyroid surgery can lower PTH and calcium, producing paresthesia and tetany.","Hypercalcemia more often causes constipation, weakness, and renal calculi rather than tetany.","Thyroid storm causes severe hypermetabolic findings such as fever and tachycardia.","This does not explain perioral tingling and carpopedal spasm."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-029","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Hyperparathyroidism","question":"A client with hyperparathyroidism has confusion, constipation, thirst, and a history of renal calculi. Which laboratory finding is expected?","options":["Low serum calcium","Low PTH with high phosphate","Low sodium with dilute urine","Elevated serum calcium"],"answer":3,"rationales":["Low calcium is associated with hypoparathyroidism.","This pattern is associated with hypoparathyroidism.","This pattern is not characteristic of hyperparathyroidism.","Excess PTH increases serum calcium and can cause renal stones, constipation, thirst, and neurocognitive changes."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-030","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Post-parathyroidectomy airway","question":"Following parathyroidectomy, which equipment should be available at the bedside?","options":["Oxygen, suction, and emergency airway equipment including a tracheostomy kit","A warming blanket as the only emergency equipment","Defibrillator pads only, with no airway equipment","Insulin pump supplies only"],"answer":0,"rationales":["The lecture emphasizes respiratory monitoring and readiness for laryngeal edema/airway compromise after parathyroid surgery.","Temperature support alone is insufficient for possible laryngeal edema.","Airway compromise is a key concern; airway equipment must be readily available.","Insulin supplies do not address the immediate postoperative airway risk."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-031","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"IV calcium gluconate","question":"A client with symptomatic hypoparathyroidism is prescribed IV calcium gluconate. Which nursing action is essential?","options":["Monitor the ECG during administration and recheck calcium levels","Administer rapidly without cardiac monitoring","Restrict all calcium intake","Encourage high-phosphorus foods"],"answer":0,"rationales":["IV calcium can affect cardiac conduction; the lecture specifically calls for ECG monitoring and laboratory follow-up.","Rapid or unmonitored administration can be unsafe.","Treatment aims to increase calcium, not restrict it.","The lecture describes increasing calcium and using a low-phosphorus diet."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-032","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Hypoparathyroidism nutrition","question":"Which dietary pattern may be prescribed for a client with hypoparathyroidism?","options":["Increased calcium with reduced phosphorus","High potassium with low protein","High sodium with no calcium","Low calcium with high phosphorus"],"answer":0,"rationales":["The lecture identifies increasing calcium and using a low-phosphorus diet to support correction of hypocalcemia.","This is not the dietary approach described for hypoparathyroidism.","This does not address low PTH and hypocalcemia.","This worsens the underlying hypocalcemia/hyperphosphatemia pattern."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-033","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Gabapentin teaching","question":"A client with diabetic peripheral neuropathy is prescribed gabapentin. Which teaching is most appropriate?","options":["Take extra doses before driving","Dizziness and drowsiness can occur; avoid unsafe activities until the effects are known and do not stop it abruptly","Stop the medication immediately when pain improves","Expect improved sensation immediately after the first dose"],"answer":1,"rationales":["Extra doses can increase sedation and impair driving safety.","Gabapentin can cause dizziness and sedation; the lecture also emphasizes not discontinuing it suddenly.","Abrupt discontinuation is not recommended; follow prescriber instructions.","Neuropathic pain treatment may require titration and time; immediate restoration of sensation is not expected."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-034","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Pregabalin safety","question":"A client taking pregabalin for diabetic neuropathy reports new facial swelling and difficulty breathing. What should the nurse do?","options":["Encourage the client to lie flat and wait","Reassure the client that swelling is an expected harmless effect","Treat this as a possible serious hypersensitivity/angioedema reaction and seek emergency help","Recommend taking the next dose early"],"answer":2,"rationales":["Waiting is unsafe when airway compromise is possible.","Facial swelling with breathing difficulty is an emergency, not a routine effect.","Pregabalin can be associated with angioedema; airway symptoms require emergency response.","Another dose could worsen a serious reaction."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-035","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"Diabetic neuropathy foot safety","question":"Which instruction best reduces injury risk for a client with diabetic peripheral neuropathy?","options":["Trim calluses deeply with a razor","Use a heating pad on numb feet every night","Walk barefoot indoors to strengthen the feet","Inspect both feet every day, wear properly fitting shoes, and report sores promptly"],"answer":3,"rationales":["Self-treatment with sharp tools can cause wounds and infection.","Reduced sensation increases burn risk; direct heat should be avoided.","Barefoot walking increases risk of cuts, burns, and unnoticed trauma.","Loss of protective sensation increases injury risk; daily inspection and protective footwear help prevent unnoticed wounds."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null},{"id":"CH5-ENDO-036","moduleId":"ch5-endocrine-function-ati-deep-dive","category":"Endocrine Function — ATI PowerPoint","tag":"High-calorie high-protein nutrition","question":"A client with increased metabolic needs and unintentional weight loss is prescribed a high-calorie, high-protein diet. Which meal best supports the plan?","options":["Clear broth and sugar-free gelatin only","Black coffee and a small apple","Grilled chicken, eggs, Greek yogurt, beans, and a calorie-dense side","Plain lettuce with fat-free dressing"],"answer":2,"rationales":["This provides very little protein or energy.","This does not provide adequate calories or protein.","This meal provides concentrated protein and energy to support increased needs and tissue maintenance.","This is low in calories and protein."],"case":null,"noteId":"ch5-ati-endocrine-function-educator-ppt","noteTitle":"Chapter 5 — ATI Engage: Alterations in Endocrine Function","conceptId":null}],"ch5-immunity-inflammatory-process-ati-deep-dive":[{"id":"CH5-IMM-001","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which findings are the classic local manifestations of acute inflammation?","options":["Bradycardia, hypothermia, and constipation","Redness, heat, swelling, pain, and loss of function","Jaundice, ascites, and peripheral edema","Pallor, coolness, numbness, and decreased pulse only"],"answer":1,"rationales":["These findings are not the classic local inflammatory signs.","Acute inflammation produces vasodilation and increased vascular permeability, causing redness, warmth, swelling, pain, and sometimes loss of function.","These findings suggest hepatobiliary or fluid-balance problems.","These are not the classic inflammatory response."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-002","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which cells are more prominent in chronic inflammation than in an acute neutrophil-dominant response?","options":["Platelets and erythrocytes","Macrophages and lymphocytes","Eosinophils only","Neutrophils only"],"answer":1,"rationales":["These are not the predominant inflammatory leukocytes described.","Chronic inflammation is commonly associated with macrophages and lymphocytes and may cause subtle, persistent symptoms.","Eosinophils are associated with allergic and parasitic responses, not the typical chronic pattern.","Neutrophils are more characteristic of acute inflammation."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-003","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which statement best describes active immunity?","options":["The client’s own immune system produces antibodies after infection or vaccination","It occurs only through breast milk","Protection is immediate but always short-lived","Ready-made antibodies are transferred from another source"],"answer":0,"rationales":["Active immunity develops when the person’s immune system responds to an antigen; it takes time but is generally longer-lasting.","Breast milk provides passive immunity.","Active immunity takes time to develop and can be long-lasting.","This describes passive immunity."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-004","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which is an example of passive immunity?","options":["Antibodies transferred from a parent to an infant through the placenta","Long-term immune memory created by exposure","Antibodies produced after a vaccine","Antibodies produced after recovering from infection"],"answer":0,"rationales":["Placental antibody transfer provides ready-made antibodies and is a form of passive immunity.","Immune memory is a feature of active immunity.","Vaccination stimulates active immunity.","Recovery from infection stimulates active immunity."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-005","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"What is the primary difference between an autoimmune disorder and immunodeficiency?","options":["Immunodeficiency causes the immune system to attack healthy joints","Autoimmunity causes immune attack against self; immunodeficiency weakens immune defense","Both conditions always cause excess antibody production","Autoimmunity prevents all inflammation"],"answer":1,"rationales":["This describes autoimmunity, not immunodeficiency.","Autoimmune disease involves inappropriate targeting of the body’s own tissues, whereas immunodeficiency reduces the ability to fight infection.","They are different mechanisms.","Autoimmune disease can cause significant inflammation."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-006","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which assessment pattern is most characteristic of rheumatoid arthritis?","options":["Sudden severe pain limited to one great toe","Unilateral knee pain only after exercise","Painless joint enlargement without inflammation","Symmetric joint pain, swelling, and stiffness, commonly involving hands and wrists"],"answer":3,"rationales":["This is more suggestive of gout.","This is not the typical symmetric inflammatory pattern.","RA is an inflammatory disease with pain and swelling.","RA commonly affects joints symmetrically, especially hands, wrists, and knees, with inflammatory pain and stiffness."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-007","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"What happens in rheumatoid arthritis?","options":["Antibodies destroy peripheral nerve myelin","The immune system attacks synovial tissue, causing chronic joint inflammation and damage","Cartilage wears down solely from aging and mechanical use","The pancreas stops producing insulin"],"answer":1,"rationales":["This describes Guillain-Barré syndrome.","RA is an autoimmune disease in which inflammation of the synovium damages joints and can affect other organs.","This is closer to osteoarthritis.","This describes diabetes mellitus."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-008","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which laboratory findings can support assessment of rheumatoid arthritis activity?","options":["Elevated troponin and BNP only","Low TSH and elevated T4","Low serum sodium and low serum osmolality","Elevated ESR and CRP"],"answer":3,"rationales":["These are cardiac markers.","These are thyroid findings.","These suggest a water-balance disorder such as SIADH.","ESR and CRP are inflammatory markers and can rise with active RA; RF and anti-CCP may also support diagnosis."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-009","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with RA is starting an anti-TNF medication. Which screening is especially important before treatment?","options":["Daily peak-flow measurement","Tuberculosis screening","Fecal occult blood testing","Routine pregnancy test only"],"answer":1,"rationales":["This does not screen for latent TB.","Anti-TNF biologics increase the risk of serious infection, including reactivation of latent tuberculosis.","This does not screen for the major infection risk.","This is not the key screening precaution for anti-TNF therapy."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-010","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which instruction is important for a client taking a DMARD or other immunosuppressant for RA?","options":["Take an extra dose when a flare begins","Avoid all vaccinations permanently without consulting the provider","Report fever or signs of infection promptly","Stop the medication whenever joint pain improves"],"answer":2,"rationales":["Never self-adjust immunosuppressant doses.","Vaccination decisions should be individualized; live vaccines may be contraindicated, but not all vaccines are prohibited.","Immune suppression increases infection risk; fever and infection symptoms require prompt evaluation.","Do not stop prescribed therapy without guidance."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-011","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which teaching is appropriate for a client taking hydroxychloroquine?","options":["Expect urine to turn bright red","Keep regular eye examinations and report visual changes","Avoid all fluids after taking the medication","Use tanning beds to prevent photosensitivity"],"answer":1,"rationales":["Bright red urine is not the expected teaching point.","Hydroxychloroquine can cause retinal toxicity; routine ophthalmologic monitoring and prompt reporting of visual symptoms are important.","Fluid restriction is unrelated.","Photosensitivity precautions are needed; tanning beds increase UV exposure."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-012","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which nonpharmacologic intervention can help a client with RA maintain function?","options":["Avoid assistive devices even when balance is impaired","Perform high-impact exercise through severe joint pain","Low-impact exercise and prescribed range-of-motion or physical therapy","Complete bed rest during all disease phases"],"answer":2,"rationales":["Assistive devices can improve safety.","Exercise should be individualized and should not force activity through severe pain.","Low-impact activity, therapy, splints, and adaptive equipment can preserve mobility and function while reducing injury risk.","Prolonged immobility worsens function."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-013","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with RA reports new shortness of breath. What is the nurse’s priority?","options":["Assume it is caused by joint stiffness","Recommend increasing exercise immediately","Document it as an expected symptom without assessment","Assess respiratory status and promptly report the change"],"answer":3,"rationales":["Dyspnea is not explained by joint stiffness.","Exercise is not the first response to new dyspnea.","New respiratory symptoms require evaluation.","RA can affect the lungs and cardiovascular system; new dyspnea requires assessment for serious complications or medication effects."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-014","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which findings are most characteristic of Sjögren syndrome?","options":["Excessive tearing and salivation","Painful unilateral joint swelling only","Severe polyuria and polydipsia","Dry eyes and dry mouth"],"answer":3,"rationales":["The syndrome causes dryness, not excess secretions.","This is not the defining presentation.","These suggest diabetes insipidus or diabetes mellitus.","Sjögren syndrome is an autoimmune disorder that commonly causes keratoconjunctivitis sicca and xerostomia."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-015","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which intervention is appropriate for a client with Sjögren syndrome and dry mouth?","options":["Fluid restriction and alcohol-based mouthwash","Frequent sugary candies and poor oral hygiene","Avoid dental visits unless pain develops","Frequent fluids as allowed, good oral care, and sugar-free saliva stimulants"],"answer":3,"rationales":["These measures worsen dryness.","Sugar promotes dental caries.","Regular dental care helps prevent decay.","Hydration, oral hygiene, dental follow-up, humidification, and sugar-free lozenges can reduce dryness and dental complications."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-016","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which intervention may relieve dry eyes associated with Sjögren syndrome?","options":["Artificial tears and lubricating eye ointment as prescribed","Apply heat directly to the eyeball","Avoid blinking to conserve tears","Topical decongestant drops every hour indefinitely"],"answer":0,"rationales":["Artificial tears and lubricating ointments help protect the ocular surface.","Direct heat to the eye is unsafe.","Blinking helps distribute tears.","Frequent decongestant use can cause harm and is not standard dry-eye care."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-017","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which manifestation is a classic clue to systemic lupus erythematosus?","options":["A butterfly-shaped rash across the cheeks and bridge of the nose","A bull’s-eye rash after a tick bite","A vesicular rash confined to one dermatome","A painless chancre"],"answer":0,"rationales":["SLE may cause a malar or butterfly rash and can affect multiple organ systems.","This is associated with Lyme disease.","This is more typical of herpes zoster.","This may be associated with syphilis."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-018","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which organ systems should the nurse monitor closely in a client with SLE?","options":["Renal, cardiovascular, respiratory, and neurologic systems","Only the integumentary system","Only the gastrointestinal system","Only the musculoskeletal system"],"answer":0,"rationales":["SLE is systemic and can cause nephritis, cardiovascular inflammation, pulmonary involvement, and neurologic changes.","SLE is not limited to the skin.","SLE can affect many systems beyond the GI tract.","Joint involvement is common, but not the only concern."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-019","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which laboratory test is commonly used to help evaluate inflammation in a client with SLE?","options":["ESR","Troponin as the sole lupus marker","Serum amylase as the diagnostic test","Urine ketones as the primary autoimmune marker"],"answer":0,"rationales":["ESR may be elevated with systemic inflammation; ANA and other disease-specific antibodies are also used in evaluation.","Troponin evaluates myocardial injury.","Amylase is associated with pancreatic injury.","Urine ketones assess ketosis."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-020","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which teaching is most important for a client with lupus who experiences photosensitivity?","options":["Use broad-spectrum sun protection and protective clothing; avoid excessive UV exposure","Use tanning beds to build tolerance","Stop prescribed medications on sunny days","Avoid all physical activity"],"answer":0,"rationales":["UV exposure can trigger or worsen lupus manifestations; sun protection and trigger management are important.","UV exposure can worsen symptoms.","Medication changes require prescriber guidance.","Activity should be balanced with rest, not universally avoided."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-021","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with SLE reports foamy urine and new edema. What complication should the nurse suspect?","options":["Myasthenic crisis","Renal involvement such as lupus nephritis","Expected seasonal allergy symptoms","Acute appendicitis"],"answer":1,"rationales":["Myasthenic crisis causes severe muscle and respiratory weakness.","SLE can inflame renal structures and impair kidney function; proteinuria and edema require prompt evaluation.","These findings are not explained by allergies.","Appendicitis causes abdominal findings, not this renal pattern."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-022","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which statement about discoid lupus is accurate?","options":["It is a form of diabetes","It primarily affects the skin but can progress to systemic lupus","It is caused by a bacterial infection","It always causes immediate kidney failure"],"answer":1,"rationales":["It is not diabetes.","Discoid lupus is a cutaneous form that may cause scarring lesions and, in some clients, can progress to systemic disease.","Lupus is autoimmune, not bacterial.","Kidney failure is not inevitable."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-023","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which history is commonly associated with Guillain-Barré syndrome?","options":["A history of seasonal allergies without infection","A recent respiratory or gastrointestinal infection followed by progressive weakness","A recent high-calcium diet","A lifetime history of hypertension only"],"answer":1,"rationales":["Allergies alone are not the typical antecedent.","GBS often follows an infection by about 1–3 weeks and involves immune-mediated peripheral nerve injury.","Dietary calcium is unrelated.","Hypertension alone is not the typical trigger."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-024","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"What is the characteristic progression of Guillain-Barré syndrome?","options":["Intermittent tremor without weakness","Symmetric ascending weakness that can progress to respiratory muscle failure","Unilateral weakness limited to one arm","Descending paralysis beginning in the face in every case"],"answer":1,"rationales":["Weakness is a defining concern.","GBS commonly causes bilateral ascending weakness and can compromise respiratory muscles.","GBS is generally symmetric and ascending.","This is not the usual pattern."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-025","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with Guillain-Barré syndrome develops a weak cough and difficulty swallowing. What is the priority?","options":["Offer thin liquids to test swallowing","Delay assessment until the next scheduled vital signs","Assess airway and respiratory function immediately and prepare for escalation of support","Encourage ambulation without assistance"],"answer":2,"rationales":["Oral intake risks aspiration before swallowing is assessed.","Respiratory deterioration requires immediate assessment.","Bulbar weakness and respiratory muscle involvement can rapidly threaten airway protection and ventilation.","Weakness creates fall risk."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-026","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which assessment is especially important for a hospitalized client with Guillain-Barré syndrome?","options":["Abdominal girth alone","Frequent respiratory function and muscle-strength assessment","Daily visual acuity only","Routine hearing tests only"],"answer":1,"rationales":["Abdominal girth does not assess respiratory muscle weakness.","GBS can progress to neuromuscular respiratory failure; serial respiratory and strength assessments help identify deterioration.","Visual acuity is not the priority.","Hearing is not the primary risk."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-027","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which treatments may be used for Guillain-Barré syndrome?","options":["Thyroid hormone replacement only","IV immunoglobulin or plasmapheresis with supportive respiratory care","Insulin and oral glucose only","Antibiotics as the sole treatment"],"answer":1,"rationales":["This does not treat GBS.","IVIG and plasma exchange target the immune process; supportive care may include ICU monitoring and mechanical ventilation.","These do not treat GBS.","Antibiotics do not reverse the autoimmune nerve injury."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-028","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which cerebrospinal fluid finding may support Guillain-Barré syndrome?","options":["Elevated protein with a normal or near-normal white blood cell count","Markedly elevated glucose with no protein","Low protein with numerous red blood cells","High ketones as the defining finding"],"answer":0,"rationales":["Albuminocytologic dissociation—elevated CSF protein without a substantial WBC increase—is a classic supportive finding.","This is not the characteristic CSF pattern.","This does not describe the typical finding.","Ketones are unrelated."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-029","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which complication of Guillain-Barré syndrome requires the most urgent surveillance?","options":["Mild constipation","Temporary hair loss","Dry skin","Respiratory failure"],"answer":3,"rationales":["This is less urgent than respiratory compromise.","This is not a defining complication.","This is not the priority threat.","Ascending paralysis can involve respiratory muscles and cause life-threatening ventilatory failure."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-030","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which pattern is characteristic of myasthenia gravis?","options":["Voluntary muscle weakness that worsens with activity and improves with rest","Sudden ascending paralysis after infection","Muscle weakness that is always strongest after sleep and worsens only during rest","Sensory loss without muscle weakness"],"answer":0,"rationales":["MG affects neuromuscular transmission and produces fatigable weakness, often worse later in the day.","This describes GBS.","This reverses the typical pattern.","Sensory loss is not the hallmark."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-031","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which assessment findings are common in myasthenia gravis?","options":["Ptosis, diplopia, dysphagia, and generalized fatigable weakness","Malar rash and proteinuria","Ascending paresthesia with absent lower-extremity reflexes","Polyuria and extreme thirst"],"answer":0,"rationales":["MG commonly affects ocular, facial, bulbar, and limb muscles.","These suggest SLE.","These suggest GBS.","These suggest a water-balance disorder."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-032","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which medication is commonly prescribed to improve neuromuscular transmission in myasthenia gravis?","options":["Pyridostigmine","Fludrocortisone","Levothyroxine","Methimazole"],"answer":0,"rationales":["Pyridostigmine is an acetylcholinesterase inhibitor that increases acetylcholine availability at the neuromuscular junction.","Fludrocortisone is a mineralocorticoid replacement.","Levothyroxine treats hypothyroidism.","Methimazole treats hyperthyroidism."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-033","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with myasthenia gravis develops increasing dysphagia, weak cough, and dyspnea. What is the priority concern?","options":["Stable remission","Myasthenic crisis with impending respiratory failure","Expected medication response","Mild seasonal allergy"],"answer":1,"rationales":["This is not remission.","Severe bulbar and respiratory muscle weakness can indicate myasthenic crisis and requires emergency airway assessment.","These are dangerous worsening symptoms.","The symptoms indicate possible crisis."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-034","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which finding may help distinguish cholinergic crisis from myasthenic crisis?","options":["Both crises are treated by giving extra pyridostigmine without assessment","Cholinergic crisis always causes a butterfly rash","Cholinergic crisis may include excessive secretions, diaphoresis, and poor tongue control","Myasthenic crisis is defined by high fever and diarrhea only"],"answer":2,"rationales":["The cause must be assessed; additional medication may worsen cholinergic crisis.","A butterfly rash is associated with lupus.","Excess cholinergic activity can produce muscarinic symptoms such as sweating and increased secretions along with weakness.","These are not the defining findings."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-035","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which intervention is appropriate for a client with myasthenia gravis who has difficulty chewing?","options":["Ignore coughing during meals","Encourage eating while lying flat","Offer the largest meal late in the evening","Schedule meals when muscle strength is best and assess swallowing safety"],"answer":3,"rationales":["Coughing may indicate aspiration and requires assessment.","Lying flat increases aspiration risk.","Weakness commonly worsens later in the day.","Strength is often better in the morning; meal timing and aspiration precautions support safe nutrition."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-036","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which procedure may be considered in selected clients with myasthenia gravis?","options":["Thyroidectomy in every client","Colectomy","Thymectomy","Nephrectomy"],"answer":2,"rationales":["Thyroid removal does not treat MG.","Colon removal does not treat MG.","The thymus is involved in immune regulation; thymectomy may be part of treatment for selected clients, especially with thymoma.","Kidney removal does not treat MG."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-037","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which body fluids can transmit HIV?","options":["Airborne droplets from coughing","Sweat, tears, and intact-skin contact","Sharing utensils or toilet seats","Blood, semen, vaginal and rectal fluids, and breast milk"],"answer":3,"rationales":["HIV is not spread through airborne droplets.","These do not transmit HIV in ordinary contact.","Casual contact does not transmit HIV.","HIV transmission requires specific infected body fluids to enter the bloodstream or contact susceptible mucous membranes or damaged tissue."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-038","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which laboratory measure is used to monitor response to HIV treatment?","options":["TSH","HIV viral load","Serum amylase","Rheumatoid factor"],"answer":1,"rationales":["TSH evaluates thyroid function.","Viral load measures circulating HIV RNA and helps evaluate treatment effectiveness and disease activity.","Amylase evaluates pancreatic injury.","RF is associated with autoimmune assessment."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-039","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which immune cell count is especially important in assessing progression of HIV infection?","options":["Platelet count only","Reticulocyte count only","Eosinophil count only","CD4 T-cell count"],"answer":3,"rationales":["Platelets assess clotting-related cell levels.","Reticulocytes assess red-cell production.","Eosinophils are not the key HIV progression marker.","CD4 count reflects immune function and helps assess risk for opportunistic infections and AIDS-related immune suppression."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-040","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which condition is considered an opportunistic infection in a client with advanced HIV?","options":["Osteoarthritis","Uncomplicated tension headache","Pneumocystis jirovecii pneumonia","Seasonal allergic rhinitis"],"answer":2,"rationales":["Osteoarthritis is not an opportunistic infection.","Tension headache is not an opportunistic infection.","Advanced immune suppression increases risk for opportunistic infections such as Pneumocystis pneumonia, TB, and fungal infections.","Seasonal allergies are not opportunistic infections."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-041","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which statement about HIV transmission precautions is correct?","options":["Use separate dishes and utensils","Use standard precautions and safely handle blood and body fluids","Avoid touching the client","Place every client with HIV in airborne isolation"],"answer":1,"rationales":["Separate dishes are unnecessary.","Standard precautions prevent occupational exposure; HIV is not spread by casual contact, shared dishes, or ordinary touch.","Routine compassionate contact is safe.","Airborne isolation is not required for HIV alone."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-042","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client newly diagnosed with HIV asks whether the diagnosis means they have AIDS. What is the best response?","options":["Every positive HIV test means AIDS","HIV and AIDS are unrelated conditions","HIV infection does not automatically mean AIDS; AIDS is the advanced stage defined by severe immune suppression or specific conditions","AIDS is diagnosed by a positive influenza test"],"answer":2,"rationales":["This is incorrect.","AIDS is caused by advanced HIV infection.","HIV is the infection; AIDS is the most advanced stage and is diagnosed using CD4 criteria or AIDS-defining conditions.","Influenza testing does not diagnose AIDS."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-043","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which nursing action is important for a client with HIV who is immunosuppressed?","options":["Discourage nutrition support","Assume absence of fever rules out infection","Monitor for fever, weight loss, oral lesions, respiratory symptoms, and other infection cues","Avoid assessment of skin and oral mucosa"],"answer":2,"rationales":["Nutrition is important.","Immunosuppressed clients may have atypical presentations.","Immunosuppression increases infection risk; assessment includes systemic, respiratory, nutritional, skin, and oral findings.","Skin and oral assessment are essential."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-044","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client taking an ACE inhibitor develops swelling of the tongue and lips. What is the priority?","options":["Offer oral fluids and reassess in one hour","Assess airway immediately and prepare for emergency airway support","Document as an expected harmless effect","Apply a warm compress only"],"answer":1,"rationales":["Oral intake is unsafe with possible airway compromise.","ACE inhibitors are a common medication cause of angioedema; tongue or laryngeal swelling can rapidly obstruct the airway.","This is potentially life-threatening.","A compress does not address airway risk."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-045","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which finding in a client with angioedema signals possible upper-airway obstruction?","options":["Chronic knee stiffness","Increased appetite","Mild dry skin","Stridor or inability to swallow"],"answer":3,"rationales":["Joint stiffness is unrelated.","Appetite is unrelated.","Dry skin does not indicate airway obstruction.","Stridor, dysphagia, and throat tightness indicate possible laryngeal involvement and require immediate airway evaluation."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-046","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which event can trigger anaphylaxis?","options":["Only mild muscle strain","Only prolonged fasting","Re-exposure to an allergen such as a food, medication, latex, or insect venom","Only exposure to cold air"],"answer":2,"rationales":["Muscle strain is not a typical trigger.","Fasting alone is not a typical allergen trigger.","Anaphylaxis is a rapid systemic hypersensitivity reaction triggered by allergens; common triggers include foods, drugs, latex, and stings.","Cold air alone is not a typical trigger."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-047","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client develops wheezing, facial swelling, urticaria, and hypotension after an antibiotic. Which medication is the priority?","options":["Oral antihistamine as the only treatment","An oral pain reliever","A diuretic","Epinephrine"],"answer":3,"rationales":["Antihistamines are adjuncts and must not delay epinephrine.","Acetaminophen does not treat anaphylaxis.","Diuretics can worsen intravascular volume depletion.","IM epinephrine is first-line treatment for anaphylaxis because it supports blood pressure and reduces airway edema and bronchospasm."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-048","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Where should an epinephrine auto-injector be administered?","options":["Into the anterolateral thigh","Into the abdomen","Into the deltoid muscle","Into the buttock"],"answer":0,"rationales":["The anterolateral mid-thigh is the recommended site because it allows rapid intramuscular absorption; auto-injectors may be used through clothing if necessary.","The abdomen is not the recommended intramuscular auto-injector site and may not provide reliable emergency delivery.","The deltoid is not the recommended site for an epinephrine auto-injector; use the anterolateral thigh.","The buttock is not recommended because it can result in injection into adipose tissue rather than the intended muscle."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-049","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"After administering epinephrine for anaphylaxis, what should the nurse do?","options":["Withhold oxygen and IV fluids","Discharge the client as soon as the rash fades","Allow the client to stand and walk immediately","Activate emergency response, support airway/breathing, monitor vital signs, and prepare for additional treatment"],"answer":3,"rationales":["Oxygen and fluids may be necessary supportive treatments.","Biphasic reactions can occur after initial improvement.","Standing can worsen hypotension.","Anaphylaxis can recur or progress; emergency evaluation, monitoring, oxygen, IV fluids, and observation are often needed."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-051","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which teaching is essential for a client prescribed an epinephrine auto-injector?","options":["Wait until severe shock develops before using it","Carry it at all times, know how to use it, check expiration, and keep a second dose available","Store it in extreme heat for quick access","Remove the safety cap before carrying it"],"answer":1,"rationales":["Delaying epinephrine increases mortality risk.","Prompt use at the first signs of anaphylaxis is lifesaving; the device should be accessible, protected from temperature extremes, and checked regularly.","Extreme temperatures can damage medication.","The safety cap stays in place until use."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-052","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Why should a client be observed after anaphylaxis improves following epinephrine?","options":["Epinephrine permanently prevents all future allergic reactions","Observation is needed only to monitor appetite","The rash always returns within five minutes","A biphasic reaction can cause symptoms to recur after initial improvement"],"answer":3,"rationales":["Epinephrine treats the acute event but does not eliminate future risk.","Appetite is not the reason for observation.","Timing is variable; recurrence is not guaranteed.","A biphasic reaction is recurrence of anaphylaxis after initial resolution, so continued monitoring is important."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-053","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which nursing intervention is appropriate for a client receiving immunosuppressive therapy?","options":["Encourage contact with people who have active infections","Use strict aseptic technique and monitor closely for infection","Ignore minor fever because immune suppression prevents infection","Place fresh flowers at the bedside"],"answer":1,"rationales":["Exposure to infection should be minimized.","Immunosuppressants reduce immune defenses; infection prevention, asepsis, nutrition, and early recognition are essential.","Fever can be an important warning sign.","Flowers may harbor organisms and are often restricted in high-risk settings."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-054","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which effect is associated with systemic corticosteroid therapy?","options":["Permanent protection against osteoporosis","Consistent hypoglycemia and enhanced immune function","Immediate cure of autoimmune disease","Increased blood glucose and increased infection risk"],"answer":3,"rationales":["Long-term steroids can contribute to osteoporosis.","This reverses the expected effects.","Steroids control inflammation but do not cure autoimmune disease.","Corticosteroids suppress immune function and can raise glucose, increase infection risk, and cause bone and GI complications."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-055","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Why should long-term corticosteroids generally be tapered rather than stopped abruptly?","options":["Tapering prevents all allergic reactions","Abrupt withdrawal causes HIV infection","Abrupt withdrawal can cause adrenal insufficiency because endogenous cortisol production is suppressed","The medication accumulates permanently in the joints"],"answer":2,"rationales":["Tapering is not for allergy prevention.","Steroids do not cause HIV.","Long-term glucocorticoids suppress the hypothalamic-pituitary-adrenal axis; gradual tapering allows adrenal function to recover.","This is not the mechanism."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-056","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"What is the action of calcineurin inhibitors such as tacrolimus and cyclosporine?","options":["They inhibit T-cell activation by reducing cytokine synthesis","They stimulate antibody production","They increase histamine release","They destroy all circulating red blood cells"],"answer":0,"rationales":["Calcineurin inhibitors suppress immune activation, particularly T-cell signaling, and are used in autoimmune disease and transplant rejection prevention.","They suppress rather than stimulate immune activity.","They do not act by increasing histamine.","They do not target all red blood cells."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-057","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which medications are examples of cytotoxic immunosuppressants/DMARDs?","options":["Methotrexate, azathioprine, and mycophenolate","Antihistamines","Diuretics","Thyroid hormone and thyroid synthesis-inhibitor therapies"],"answer":0,"rationales":["These medications inhibit cell proliferation and are used in autoimmune disorders and transplant rejection prevention.","These are antihistamines.","These are diuretics.","These are thyroid medications."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-058","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which adverse effects should a client taking methotrexate report promptly?","options":["Fever, sore throat, unusual bruising, or bleeding","Temporary hunger before meals","A single episode of hiccups","Mild thirst after exercise only"],"answer":0,"rationales":["Methotrexate can suppress bone marrow and increase infection and bleeding risk; CBC monitoring and prompt reporting are important.","Hunger is not a typical urgent toxicity sign.","Hiccups are not the key toxicity sign.","These are not the key toxicity cues."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-059","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which statement best describes monoclonal or polyclonal antibody preparations used therapeutically?","options":["They provide immunoglobulin or targeted antibody effects for selected immune, inflammatory, cancer, or transplant conditions","They are used only to treat dehydration","They replace insulin in diabetes","They are always live vaccines"],"answer":0,"rationales":["Antibody preparations can modulate immune responses and are used in selected autoimmune, transplant, and cancer therapies.","They do not replace fluid therapy.","They do not replace insulin.","They are not live vaccines."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-060","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which teaching is appropriate for a client receiving immunosuppressive medications?","options":["Receive any live vaccine without consultation","Stop immunosuppressants before every vaccination on your own","Avoid all non-live vaccines permanently","Ask the healthcare provider before receiving vaccines; live vaccines may be unsafe"],"answer":3,"rationales":["Live vaccines can be unsafe with significant immunosuppression.","Medication changes should not be self-directed.","Non-live vaccines may still be recommended.","Immune suppression changes vaccine safety and response; the prescriber should guide timing and vaccine type, especially live vaccines."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-061","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which dietary pattern is listed in the immunity module for a client who needs a low-calorie, low-fat diet?","options":["Use high-sugar drinks as the primary calorie source","Choose nutrient-dense foods with reduced saturated fat and appropriate calorie control","Increase fried foods and high-fat processed meats","Eliminate all protein"],"answer":1,"rationales":["Sugar-sweetened drinks are not a balanced nutrition plan.","The module identifies a low-calorie, low-fat diet as a nutrition concept; choices should remain balanced and nutrient-dense.","These choices are high in fat.","Protein remains essential."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-062","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with SLE has confusion, a seizure, and a new severe headache. Which concern should the nurse prioritize?","options":["Expected harmless effect of photosensitivity","Uncomplicated dry mouth","Routine osteoarthritis pain","Possible central nervous system involvement from lupus"],"answer":3,"rationales":["Photosensitivity does not explain neurologic emergencies.","Dry mouth does not explain acute neurologic changes.","Osteoarthritis does not cause seizures.","SLE can affect the CNS and cause seizures, confusion, behavior changes, and other neurologic complications."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-063","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client with RA reports increasing fatigue and depressed mood during a prolonged flare. Which nursing response is best?","options":["Recommend stopping all prescribed medications","Assess coping, pain, function, and support needs; collaborate on symptom management","Tell the client these feelings are unrelated to chronic illness","Discourage discussion of emotional concerns"],"answer":1,"rationales":["Medication changes require provider guidance.","Chronic pain, fatigue, and functional changes can affect psychosocial health; holistic assessment and support are part of nursing care.","Psychosocial effects can accompany chronic disease.","Therapeutic communication encourages discussion."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-064","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which finding in a client with HIV requires prompt follow-up?","options":["Stable appetite and unchanged weight","Occasional dry skin","New fever, cough, weight loss, or oral white patches","A healed minor bruise"],"answer":2,"rationales":["These are not new warning signs.","Dry skin alone is nonspecific.","These findings can indicate opportunistic infection or disease progression in an immunocompromised client.","A healed bruise is not the priority."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-065","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which action is appropriate when caring for a client with suspected anaphylaxis?","options":["Encourage the client to walk to improve circulation","Wait for laboratory confirmation before treatment","Give an antihistamine and delay epinephrine","Stop exposure to the suspected trigger if possible and administer epinephrine promptly"],"answer":3,"rationales":["Walking can worsen hypotension.","Treatment is based on clinical presentation.","Antihistamines are adjuncts, not first-line replacement.","Anaphylaxis is a clinical emergency; treatment should not be delayed for diagnostic testing."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-066","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which clinical finding is most concerning in a client with suspected anaphylaxis?","options":["Chronic joint stiffness","Localized itching without other symptoms","Hypotension with wheezing or stridor","A small area of mild redness"],"answer":2,"rationales":["Joint stiffness is unrelated.","Localized itching alone is less severe.","Hypotension and respiratory compromise indicate systemic anaphylaxis and possible shock.","Mild localized redness is not shock."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-067","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which assessment is most important when a client with myasthenia gravis reports worsening weakness?","options":["Bowel sounds only","Hair texture and nail growth","Visual acuity alone","Respiratory effort, oxygenation, cough strength, and swallowing ability"],"answer":3,"rationales":["Bowel sounds do not assess crisis risk.","These are not the immediate safety priorities.","Ocular symptoms matter, but respiratory and swallowing safety take priority.","MG can progress to bulbar and respiratory muscle weakness, causing aspiration and respiratory failure."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-068","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which statement about HIV is accurate?","options":["Consistent antiretroviral therapy can suppress viral load and reduce transmission risk","A negative viral load means the infection has been cured","HIV is spread by hugging and sharing food","Treatment should stop once symptoms resolve"],"answer":0,"rationales":["Antiretroviral therapy can achieve sustained viral suppression; it is not a cure, and adherence is essential.","Undetectable does not mean cured.","Casual contact does not transmit HIV.","Treatment is continued as prescribed."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-069","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"Which nursing action helps prevent joint injury during an RA flare?","options":["Force full range of motion through severe pain","Use assistive devices, protect inflamed joints, and balance activity with rest","Keep the client on strict bed rest indefinitely","Use only the affected joints for transfers"],"answer":1,"rationales":["Forcing painful movement can worsen injury.","Joint protection, adaptive equipment, and individualized activity reduce strain while preserving function.","Prolonged bed rest worsens deconditioning.","Use stronger joints and safe techniques."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null},{"id":"CH5-IMM-070","moduleId":"ch5-immunity-inflammatory-process-ati-deep-dive","category":"Immunity & Inflammatory Process — ATI PowerPoint","tag":"Immunity","question":"A client receiving immunosuppressants has a temperature of 38.3°C (100.9°F). What should the nurse do?","options":["Give an antipyretic and ignore the temperature","Promptly notify the provider and initiate the facility’s infection evaluation protocol","Assume fever is impossible during immunosuppression","Wait until the temperature reaches 40°C (104°F)"],"answer":1,"rationales":["Antipyretics do not replace evaluation.","Fever may be the only early sign of infection in an immunosuppressed client and requires prompt evaluation.","Immunosuppression increases, not eliminates, infection risk.","Waiting can delay treatment."],"case":null,"noteId":"ch5-ati-immunity-inflammatory-process","noteTitle":"Chapter 5 — ATI Engage: Alterations in Immunity and Inflammatory Process","conceptId":null}],"ch5-ati-powerpoint-missed-topics":[{"id":"CH5-PPT-001","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Acute inflammation","question":"Which sequence best describes the local response during acute inflammation?","options":["Vasoconstriction followed by decreased permeability and reduced leukocyte movement","Vasodilation and increased capillary permeability that allow fluid and white blood cells to enter injured tissue","Immediate antibody destruction of all surrounding healthy tissue","Reduced blood flow that prevents immune cells from reaching the area"],"answer":1,"rationales":["This reverses the expected vascular response.","Acute inflammation increases local blood flow and vascular permeability, allowing fluid and leukocytes to reach the injured area.","The purpose is to contain injury and promote healing, not destroy all healthy tissue.","Blood flow increases rather than decreases during the typical acute response."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-002","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Chronic inflammation","question":"Which finding is more consistent with chronic rather than acute inflammation?","options":["Brief localized redness immediately after a minor injury","Sudden swelling that resolves as tissue heals","Persistent fatigue, malaise, body aches, and prolonged inflammatory symptoms","A short-lived inflammatory response lasting only hours"],"answer":2,"rationales":["This is a common acute local response.","Acute inflammation generally resolves after the injury heals.","Chronic inflammation may persist for months or years and can cause less-specific systemic symptoms such as fatigue, malaise, and body aches.","A short-lived response is acute, not chronic."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-003","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Osteoarthritis","question":"Which statement best distinguishes osteoarthritis from rheumatoid arthritis?","options":["Osteoarthritis is primarily degenerative joint disease; rheumatoid arthritis is an autoimmune inflammatory disease","Osteoarthritis is caused by HIV destroying CD4 cells","Rheumatoid arthritis is caused only by age-related cartilage wear","Both disorders are always caused by bacterial infection"],"answer":0,"rationales":["Osteoarthritis involves degeneration of joint structures, while RA is an autoimmune disease targeting synovial tissue.","HIV-related immune suppression is unrelated to the basic distinction between OA and RA.","This describes OA more closely, not RA.","Neither condition is always caused by bacterial infection."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-004","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Osteoarthritis","question":"Which assessment finding is most consistent with osteoarthritis?","options":["Symmetric inflammatory swelling of multiple small joints with prolonged morning stiffness","Joint discomfort that is often aggravated by use and may improve with rest","Ascending paralysis and absent reflexes","Malar rash with photosensitivity"],"answer":1,"rationales":["This pattern is more characteristic of rheumatoid arthritis.","OA pain is commonly related to joint use and mechanical stress; stiffness may occur after inactivity.","These findings suggest Guillain-Barré syndrome.","These findings suggest systemic lupus erythematosus."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-005","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Pancreatitis","question":"A client with suspected acute pancreatitis reports severe upper abdominal pain radiating to the back with nausea and vomiting. Which action is appropriate?","options":["Encourage a high-fat meal to stimulate digestion","Place the client flat and encourage alcohol intake","Assess pain and vital signs, maintain prescribed IV fluids, and anticipate pancreatic rest/NPO as ordered","Give an oral laxative before further assessment"],"answer":2,"rationales":["A high-fat meal can worsen pancreatic stimulation and is inappropriate in acute pancreatitis.","Alcohol can worsen pancreatic injury; positioning should be based on comfort and respiratory status.","Acute pancreatitis requires close assessment, fluid support, pain control, and often temporary restriction of oral intake as prescribed.","A laxative is not the priority and could worsen discomfort."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-006","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Pancreatitis","question":"Which laboratory finding is commonly associated with acute pancreatitis?","options":["Elevated lipase","Low troponin as the diagnostic marker","Elevated TSH only","Low rheumatoid factor"],"answer":0,"rationales":["Lipase is a key pancreatic enzyme that commonly rises with acute pancreatitis.","Troponin is used to assess myocardial injury.","TSH evaluates thyroid function.","Rheumatoid factor is used in autoimmune assessment and is not a pancreatitis marker."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-007","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Peritonitis","question":"Which assessment finding should raise concern for peritonitis?","options":["Soft, nontender abdomen with active bowel sounds","Rigid, board-like abdomen with severe tenderness and guarding","Isolated painless joint stiffness","Increased appetite and weight gain"],"answer":1,"rationales":["A soft, nontender abdomen is not the classic presentation.","Peritoneal inflammation can cause severe abdominal pain, guarding, rigidity, and systemic deterioration.","This suggests a joint disorder rather than peritonitis.","These are not typical findings."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-008","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Peritonitis","question":"A client with suspected peritonitis develops hypotension, tachycardia, fever, and worsening abdominal rigidity. What is the priority concern?","options":["Progression to sepsis and shock","Expected response to a meal","Mild dehydration only","An uncomplicated medication effect"],"answer":0,"rationales":["Peritonitis can progress rapidly to systemic infection, sepsis, and shock; urgent escalation and treatment are needed.","These findings are not an expected post-meal response.","The combination suggests a potentially life-threatening systemic process, not mild dehydration alone.","Do not dismiss these findings as a routine medication effect."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-009","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Influenza","question":"Which instruction is most appropriate for a client with influenza to reduce transmission?","options":["Share drinking glasses only with family","Practice hand hygiene, cover coughs, and avoid close contact while contagious","Stop all fluids until fever resolves","Use antibiotics for every influenza infection"],"answer":1,"rationales":["Sharing items that contact respiratory secretions can spread infection.","Respiratory hygiene, hand hygiene, and limiting close contact reduce spread.","Fluids are generally encouraged unless contraindicated.","Influenza is viral; antibiotics do not treat uncomplicated influenza itself."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-010","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Sinusitis","question":"Which symptom pattern is commonly associated with sinusitis?","options":["Facial pressure or pain with nasal congestion and drainage","Painless hematuria and flank mass","Ascending weakness with areflexia","Polyuria with dilute urine"],"answer":0,"rationales":["Sinus inflammation commonly causes facial pressure, congestion, and nasal drainage.","These suggest urinary or renal disease.","These suggest Guillain-Barré syndrome.","These suggest diabetes insipidus."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-011","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Meningitis","question":"A client has fever, severe headache, neck stiffness, and photophobia. Which condition should the nurse suspect?","options":["Meningitis","Osteoarthritis","Hypothyroidism","Sjögren syndrome"],"answer":0,"rationales":["Fever, headache, nuchal rigidity, and photophobia are concerning for meningitis.","OA is a degenerative joint disorder.","Hypothyroidism causes slowed metabolism, not this classic acute infectious presentation.","Sjögren syndrome is an autoimmune disorder associated with dryness."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-012","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Meningitis precautions","question":"When bacterial meningitis is suspected, what should the nurse do first regarding infection prevention?","options":["Initiate appropriate droplet precautions promptly per facility protocol","Place the client in a positive-pressure room with no mask","Wait for culture results before using precautions","Use only contact precautions for every meningitis organism"],"answer":0,"rationales":["Suspected meningococcal/bacterial meningitis requires prompt appropriate isolation, commonly droplet precautions, while evaluation and treatment proceed.","Positive-pressure rooms are not the routine isolation approach for meningococcal disease.","Precautions should not be delayed while awaiting results.","Precautions depend on the organism; droplet precautions are important for suspected meningococcal disease."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-013","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Resistant organisms","question":"Which nursing action is important when caring for a client with a known multidrug-resistant organism?","options":["Ignore isolation signage if the client has no fever","Follow organism-specific transmission precautions and perform hand hygiene consistently","Use antibiotics left over from another client","Discontinue precautions once the first antibiotic dose is given"],"answer":1,"rationales":["Absence of fever does not eliminate transmission risk.","Precautions and hand hygiene help prevent spread of resistant organisms.","Medications must never be shared between clients.","Precautions continue according to organism-specific policy and infection-control guidance."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-014","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Antimicrobial stewardship","question":"Which action supports prevention of antimicrobial resistance?","options":["Taking antibiotics only as prescribed and not using them for viral illnesses","Saving leftover antibiotics for the next illness","Stopping antibiotics as soon as symptoms improve without instructions","Requesting antibiotics for every cold"],"answer":0,"rationales":["Appropriate use reduces unnecessary antimicrobial exposure and resistance pressure.","Leftover antibiotics may be inappropriate, incomplete, or unsafe.","The client should follow the prescribed course and clinician instructions.","Antibiotics do not treat uncomplicated viral colds."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-015","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hypoparathyroidism","question":"A client with hypoparathyroidism develops perioral tingling and muscle spasms. Which electrolyte pattern should the nurse anticipate?","options":["Low calcium and high phosphate","High calcium and low phosphate","High calcium and high phosphate","Normal calcium and low phosphate"],"answer":0,"rationales":["Low PTH reduces serum calcium and decreases renal phosphate excretion, so hypocalcemia and hyperphosphatemia are expected.","This pattern is more consistent with increased PTH activity.","Low PTH does not produce hypercalcemia.","The symptoms suggest clinically significant hypocalcemia rather than normal calcium."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-016","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hyperparathyroidism","question":"Which laboratory pattern is most consistent with primary hyperparathyroidism?","options":["High calcium with elevated or inappropriately normal PTH","Low calcium with low PTH","Low sodium with low serum osmolality","Low T4 with elevated TSH"],"answer":0,"rationales":["Excess PTH commonly causes hypercalcemia and may be associated with low phosphorus.","This pattern is more consistent with hypoparathyroidism.","This suggests a water-balance disorder such as SIADH.","This suggests hypothyroidism."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-017","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hyperparathyroidism","question":"Which manifestations should the nurse associate with hyperparathyroidism?","options":["Renal calculi, constipation, increased thirst/urination, and confusion","Tetany, tingling around the mouth, and carpopedal spasm","Cold intolerance, bradycardia, and weight gain only","Ptosis and fatigable muscle weakness"],"answer":0,"rationales":["Hypercalcemia can cause kidney stones, constipation, polyuria, polydipsia, and altered mental status.","These findings suggest hypocalcemia, often associated with hypoparathyroidism.","These are typical hypothyroid manifestations.","These suggest myasthenia gravis."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-018","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hyperparathyroidism monitoring","question":"Which monitoring is appropriate for a client with significant hyperparathyroidism?","options":["Vital signs, cardiac rhythm, calcium/PTH-related labs, and intake/output","Only pupil response once per shift","Only daily visual acuity","No monitoring unless the client reports pain"],"answer":0,"rationales":["Hypercalcemia can affect cardiac conduction, fluid balance, renal function, and neurologic status.","This is not adequate monitoring.","This does not address the major risks.","Hypercalcemia can be clinically significant even without pain."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-019","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Cinacalcet","question":"What is the action of cinacalcet in the treatment of hyperparathyroidism?","options":["It decreases the amount of PTH the parathyroid gland produces","It replaces thyroid hormone","It increases blood calcium by stimulating PTH release","It directly replaces insulin"],"answer":0,"rationales":["Cinacalcet is a calcimimetic that reduces PTH secretion.","Levothyroxine replaces thyroid hormone.","Cinacalcet lowers PTH rather than stimulating it.","Insulin replacement is unrelated."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-020","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Alendronate","question":"Why might alendronate be prescribed for a client with hyperparathyroidism?","options":["To help increase bone density and reduce bone loss","To increase thyroid hormone production","To treat acute bacterial meningitis","To increase serum potassium"],"answer":0,"rationales":["Alendronate is a bisphosphonate that helps reduce bone resorption and improve bone density.","It does not stimulate thyroid hormone.","It is not an antimicrobial.","It does not treat potassium abnormalities."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-021","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Post-parathyroidectomy","question":"After parathyroidectomy, which complication requires close monitoring?","options":["Hypocalcemia with tetany and possible airway compromise","Hyperglycemia from excess insulin","Severe hypernatremia from excess ADH","Respiratory alkalosis from pain only"],"answer":0,"rationales":["Removal or manipulation of parathyroid tissue can lead to hypocalcemia; tetany and laryngeal spasm can threaten the airway.","This is not the expected primary complication.","Excess ADH causes water retention, not hypernatremia.","Pain can affect breathing but does not replace the specific post-op hypocalcemia risk."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-022","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Post-parathyroidectomy","question":"Which equipment should be readily available after parathyroid surgery according to the educator slides?","options":["Oxygen, suction, and a tracheostomy kit","Defibrillator only, with no airway equipment","A dialysis machine in every room","No emergency equipment is needed"],"answer":0,"rationales":["The slides emphasize readiness for respiratory distress or laryngeal edema, including oxygen, suction, and tracheostomy equipment.","Airway equipment is specifically important.","Dialysis is not routinely required.","Airway compromise is a potential emergency."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-023","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hypoparathyroidism","question":"Which findings suggest hypocalcemia after thyroid or parathyroid surgery?","options":["Perioral tingling, paresthesias, muscle twitching, and positive Chvostek or Trousseau signs","Polyuria, polydipsia, and hypercalcemia","Weight gain, constipation, and cold intolerance","Warm flushed skin and bounding pulses only"],"answer":0,"rationales":["Hypocalcemia increases neuromuscular excitability and can cause paresthesias, tetany, and positive Chvostek/Trousseau signs.","These findings suggest a different water/calcium pattern.","These are hypothyroid manifestations.","These are not characteristic signs of hypocalcemia."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-024","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hypothyroidism labs","question":"Which laboratory pattern is typical of primary hypothyroidism?","options":["Elevated TSH with low free T4","Low TSH with elevated T3 and T4","Elevated PTH with elevated calcium","Low cortisol with elevated ACTH only"],"answer":0,"rationales":["In primary hypothyroidism, the thyroid produces insufficient hormone, so pituitary TSH rises.","This pattern suggests primary hyperthyroidism.","This suggests hyperparathyroidism.","This suggests primary adrenal insufficiency."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-025","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hypothyroidism complications","question":"Which findings may occur with hypothyroidism?","options":["Fatigue, cold intolerance, constipation, dry skin, weight gain, and bradycardia","Heat intolerance, tremor, tachycardia, and weight loss","Severe abdominal rigidity and rebound tenderness","Ascending paralysis and absent reflexes"],"answer":0,"rationales":["A slowed metabolic state causes these common manifestations.","These suggest hyperthyroidism.","These suggest peritonitis.","These suggest Guillain-Barré syndrome."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-026","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Myxedema coma","question":"A client with severe hypothyroidism is hypothermic, bradycardic, hypotensive, lethargic, and hypoventilating. What is the priority concern?","options":["Myxedema coma","Thyroid storm","Anaphylaxis","Hyperparathyroidism"],"answer":0,"rationales":["Myxedema coma is a life-threatening decompensation of severe hypothyroidism with altered mental status and slowed vital functions.","Thyroid storm is a hypermetabolic emergency.","Anaphylaxis usually causes acute airway/circulatory compromise with an allergic trigger.","Hyperparathyroidism does not explain this pattern."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-027","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Levothyroxine monitoring","question":"Which laboratory value is most useful for routine monitoring of a client receiving levothyroxine for primary hypothyroidism?","options":["Thyroid-stimulating hormone (TSH)","Serum potassium","Absolute neutrophil count","Serum amylase"],"answer":0,"rationales":["TSH is commonly followed to assess adequacy of thyroid hormone replacement in primary hypothyroidism; timing of repeat testing follows the prescriber’s plan.","Potassium does not measure thyroid replacement effectiveness.","Neutrophil count is important with certain antithyroid drugs, not routine levothyroxine monitoring.","Amylase does not assess thyroid hormone replacement."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-028","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hyperthyroidism labs","question":"Which laboratory pattern is typical of primary hyperthyroidism?","options":["Low TSH with elevated T3 and/or T4","High TSH with low T4","Low PTH with low calcium","High ACTH with low cortisol"],"answer":0,"rationales":["Excess thyroid hormone suppresses pituitary TSH.","This suggests primary hypothyroidism.","This suggests hypoparathyroidism.","This suggests primary adrenal insufficiency."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-029","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Graves disease","question":"Which finding is particularly associated with Graves disease?","options":["Exophthalmos or bulging eyes","Board-like abdominal rigidity","Absent lower-extremity reflexes","Painless hematuria"],"answer":0,"rationales":["Graves disease can cause orbital tissue changes and eye prominence.","This suggests peritonitis.","This suggests Guillain-Barré syndrome.","This suggests urinary tract pathology."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-031","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Methimazole and PTU","question":"A client taking methimazole or propylthiouracil reports fever and sore throat. What should the nurse advise?","options":["Promptly contact the provider because these drugs can cause a low granulocyte count","This is expected and requires no assessment","Double the next dose","Stop all fluids"],"answer":0,"rationales":["Antithyroid drugs can cause agranulocytosis/neutropenia; fever and sore throat require prompt evaluation and CBC assessment.","These symptoms can signal a serious adverse effect.","Doubling a dose is unsafe.","Fluid restriction is unrelated."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-032","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Iodine therapy","question":"Why may potassium iodide or Lugol's solution be prescribed before thyroidectomy?","options":["To inhibit thyroid hormone release and decrease thyroid gland vascularity","To increase thyroid gland blood flow","To replace PTH","To cause immediate permanent hypothyroidism in all clients"],"answer":0,"rationales":["Iodine can inhibit thyroid hormone synthesis/release and reduce gland vascularity before surgery, lowering hemorrhage risk.","It decreases rather than increases vascularity.","PTH replacement is unrelated.","It is used short term in selected situations and does not universally cause permanent hypothyroidism."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-033","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Iodine toxicity","question":"Which finding should the nurse recognize as a possible adverse effect of therapeutic iodine?","options":["Excessive salivation, mucosal swelling, nausea/vomiting, or skin reactions","Severe hypoglycemia as the only expected effect","New painless hematuria","Absent reflexes"],"answer":0,"rationales":["The educator slides list mucosal swelling, excessive salivation, GI symptoms, and skin reactions as signs of iodine toxicity.","This is not the listed iodine toxicity pattern.","This suggests urinary pathology.","This suggests neurologic dysfunction."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-034","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Radioactive iodine","question":"Which teaching is important after radioactive iodine therapy for hyperthyroidism?","options":["Follow radiation-safety instructions and monitor for later hypothyroid symptoms","Expect the full effect within minutes","Assume thyroid replacement will never be needed","Avoid all follow-up thyroid testing"],"answer":0,"rationales":["RAI has a delayed effect, radiation precautions are needed, and post-treatment hypothyroidism is common enough to require monitoring.","The response can take weeks to months.","Many clients develop hypothyroidism and may need lifelong replacement.","Follow-up is necessary to monitor thyroid function."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-035","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Thyroidectomy post-op","question":"Which postoperative finding after thyroidectomy requires immediate assessment?","options":["Neck swelling, frequent swallowing, choking, or respiratory difficulty","Mild temporary hoarseness without distress","Small amount of expected incisional discomfort","A fading surgical scar"],"answer":0,"rationales":["These can indicate hemorrhage or tracheal compression and require urgent assessment.","Mild hoarseness can occur temporarily from edema, but must be monitored for worsening.","Some discomfort is expected and treated.","Scar appearance is not an acute threat."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-036","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Thyroidectomy positioning","question":"Which positioning is appropriate after thyroidectomy?","options":["Semi-Fowler's with the head supported and neck kept from excessive flexion or tension","Trendelenburg with the neck hyperextended","Prone with the head unsupported","Flat with a pillow forcing the neck forward"],"answer":0,"rationales":["Semi-Fowler's and head support reduce tension on the incision and support comfort and breathing.","This increases tension and is not the recommended position.","This is unsafe for the incision and airway monitoring.","Excessive neck flexion places tension on the suture line."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-037","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Thyroidectomy monitoring","question":"What should the nurse monitor closely after thyroidectomy in addition to airway and bleeding?","options":["Serum calcium and signs of hypocalcemia","Only serum cholesterol","Only urine ketones","Only rheumatoid factor"],"answer":0,"rationales":["Parathyroid injury or temporary dysfunction can cause hypocalcemia; monitor calcium and neuromuscular signs.","Cholesterol is not the immediate postoperative priority.","Urine ketones are unrelated to the key surgical complication.","RF is unrelated."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-038","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Hyperthyroidism nutrition","question":"Which dietary plan may be needed for a client with hyperthyroidism and significant weight loss?","options":["High-calorie, high-protein meals with frequent meals and snacks","Low-calorie, low-protein diet with skipped meals","High-caffeine drinks and highly seasoned foods","Strict fasting until thyroid levels normalize"],"answer":0,"rationales":["The slides describe high-calorie intake, frequent meals/snacks, and increased protein/carbohydrates to meet elevated metabolic needs.","This worsens nutritional deficit.","Caffeine and highly seasoned foods may worsen restlessness or GI stimulation.","Fasting is inappropriate for a client with increased metabolic needs."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-039","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Adrenal postoperative care","question":"After adrenal surgery, why are vital signs and fluid/electrolyte status monitored closely?","options":["Hormone shifts can cause circulatory instability and fluid/electrolyte imbalance","Adrenal surgery always causes immediate hyperthyroidism","The client is at no risk after surgery","Monitoring is needed only if pain is reported"],"answer":0,"rationales":["The educator material emphasizes close monitoring for BP, respiratory and heart-rate changes, intake/output, and corticosteroid imbalance during the postoperative period.","Adrenal surgery does not cause hyperthyroidism as a routine effect.","Postoperative endocrine instability can be serious.","Changes can occur without the client reporting pain."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null},{"id":"CH5-PPT-040","moduleId":"ch5-ati-powerpoint-missed-topics","category":"ATI PowerPoint Coverage — Additional Topics","tag":"Corticosteroid teaching","question":"Which teaching is important for a client taking prescribed corticosteroid therapy?","options":["Do not stop the medication abruptly; take it as directed and follow sick-day/provider instructions","Stop the medication once swelling improves","Avoid monitoring blood glucose","Take extra doses whenever tired"],"answer":0,"rationales":["Abrupt withdrawal can precipitate adrenal insufficiency; dosing and stress-dose instructions must follow the prescriber's plan.","Stopping independently is unsafe.","Corticosteroids can affect glucose and require monitoring.","Extra doses should not be self-prescribed."],"case":null,"noteId":"ch5-ati-powerpoint-missed-topics","noteTitle":"Chapter 5 — ATI Educator PowerPoints: Additional Topics","conceptId":null}],"ch5-critical-endocrine-dysfunction-ati-deep-dive":[{"id":"CH5-CED-001","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Central DI pathophysiology","question":"A client with central diabetes insipidus (DI) has which underlying problem?","options":["Excess insulin secretion","Insufficient secretion of antidiuretic hormone (ADH) from the hypothalamic-pituitary system","Excessive secretion of ADH","Kidney resistance to ADH"],"answer":1,"rationales":["Insulin secretion is not the mechanism of DI.","Central DI results from deficient ADH secretion; the slides identify pituitary/hypothalamic causes.","Excess ADH is associated with SIADH, not DI.","Kidney resistance to ADH describes nephrogenic DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-001","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-001","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":1,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-002","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Central vs. nephrogenic DI","question":"Which mechanism causes nephrogenic DI?","options":["The body retains excessive water","The kidneys do not respond adequately to ADH","The pancreas releases too little insulin","The pituitary gland fails to release ADH"],"answer":1,"rationales":["Excess water retention is characteristic of SIADH.","Nephrogenic DI is caused by renal resistance to ADH.","Insulin deficiency is unrelated to DI.","Pituitary ADH deficiency describes central DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-002","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-002","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":2,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-003","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Desmopressin response","question":"A client with central diabetes insipidus receives desmopressin. Which change best indicates the expected antidiuretic effect?","options":["Urine output decreases and urine becomes more concentrated","Urine output increases and urine becomes more dilute","Serum sodium rises as free-water loss increases","The client develops worsening thirst and orthostatic hypotension"],"answer":0,"rationales":["Desmopressin replaces ADH activity in central DI, so the kidneys retain more water and produce less concentrated-volume urine.","This would suggest ongoing or worsening DI rather than an effective response.","An effective response should reduce free-water loss; rising sodium may indicate inadequate treatment.","Worsening thirst and orthostasis can indicate persistent water deficit."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-003","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-003","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":3,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-004","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI laboratory pattern","question":"Which laboratory pattern is expected in DI?","options":["Hypernatremia, increased serum osmolality, and low urine specific gravity","Low serum osmolality with decreased urine output","Hyponatremia, low serum osmolality, and concentrated urine","Normal sodium with high urine specific gravity"],"answer":0,"rationales":["DI causes water loss, concentrating the serum and producing dilute urine.","DI typically causes increased urine output and increased serum osmolality.","This is the classic SIADH pattern.","Low urine specific gravity is expected in DI, not high."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-004","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-004","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":4,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-005","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Urine specific gravity","question":"A client with DI has a urine specific gravity of 1.002. How should the nurse interpret this result?","options":["It rules out DI","It is consistent with very dilute urine seen in DI","It indicates concentrated urine from SIADH","It confirms fluid volume excess"],"answer":1,"rationales":["A very low specific gravity supports DI.","The slides list urine specific gravity below 1.005 as a DI finding.","SIADH is associated with concentrated urine and high specific gravity.","DI causes free-water loss and dehydration risk, not fluid excess."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-005","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-005","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":5,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-006","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI assessment","question":"Which urine output finding should alert the nurse to possible DI?","options":["Nocturia with peripheral edema","Less than 400 mL/day of concentrated urine","A sudden decrease in urine output with high specific gravity","More than 3 L/day of dilute, odorless urine"],"answer":3,"rationales":["Nocturia may occur in DI, but edema is not the defining cue.","Oliguria with concentrated urine is more consistent with SIADH.","Decreased output and high specific gravity are SIADH findings.","The nursing-process slide identifies greater than 3 L of dilute, odorless urine as a cue."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-006","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-006","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":6,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-007","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI risk factors","question":"Which history places a client at increased risk for central DI?","options":["Chronic hypothyroidism","Recent pituitary or neurosurgery","Long-term SSRI therapy","Small-cell lung cancer"],"answer":1,"rationales":["Hypothyroidism is listed as a potential contributor to SIADH.","Neurosurgery and pituitary surgery are listed central DI risk factors.","SSRIs are listed among medications associated with SIADH.","Small-cell lung cancer is a classic SIADH cause in the slides."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-007","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-007","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":7,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-008","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Nephrogenic DI causes","question":"Which medication history is associated with nephrogenic DI?","options":["Tolvaptan therapy","Desmopressin therapy","Conivaptan therapy","Lithium therapy"],"answer":3,"rationales":["Tolvaptan is a vasopressin receptor antagonist used for SIADH-related hyponatremia.","Desmopressin replaces ADH and treats central DI.","Conivaptan is a vasopressin receptor antagonist used for SIADH-related hyponatremia.","The slides list lithium among causes of nephrogenic DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-008","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-008","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":8,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-009","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI safety and risk","question":"A client with DI is unable to communicate thirst after neurologic injury. What is the priority nursing concern?","options":["Peripheral edema from sodium retention","Dehydration and electrolyte imbalance","Hyperglycemia from insulin resistance","Fluid overload from excess ADH"],"answer":1,"rationales":["Peripheral edema is not the expected DI complication.","Impaired thirst perception or inability to communicate thirst increases risk for dehydration and electrolyte complications.","Hyperglycemia is not the primary DI concern in the slides.","Excess ADH and water retention describe SIADH."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-009","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-009","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":9,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-010","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI nursing assessment","question":"Which assessments are priorities for a hospitalized client with DI?","options":["Blood pressure once per shift without urine monitoring","Daily temperature only","Strict intake and output, vital signs, neurologic status, sodium, and urine concentration","Bowel sounds and stool color only"],"answer":2,"rationales":["Frequent urine and electrolyte monitoring are essential.","Temperature alone is insufficient to evaluate DI.","The slides emphasize BP/pulse, urine output, specific gravity, serum and urine osmolality, electrolytes, and neurologic changes.","GI assessment alone does not monitor water balance."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-010","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-010","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":10,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-011","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Water-deprivation test","question":"A client with DI is being evaluated with a water-deprivation test. Which nursing action is expected?","options":["Encourage unrestricted oral fluids","Withhold water as prescribed and measure weight and urine osmolality hourly","Administer a loop diuretic before each urine sample","Restrict sodium and measure glucose every 8 hours"],"answer":1,"rationales":["Unrestricted fluids invalidate the water-deprivation test.","The slides state water is withheld and body weight and urine osmolality are measured hourly.","A loop diuretic is not part of the described test.","Sodium restriction and glucose checks are not the described test protocol."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-011","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-011","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":11,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-012","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Water-deprivation test monitoring","question":"During a water-deprivation test, which change requires attention according to the slides?","options":["Serum glucose remains normal","The client reports hunger","Body weight decreases by more than 3%","Urine output increases slightly after drinking water"],"answer":2,"rationales":["Normal glucose is not the trigger described.","Hunger is not the specified trigger.","The slide states desmopressin is administered subcutaneously if weight decreases by more than 3% or sequential urine osmolality measurements differ by less than 30 mOsm/kg H2O.","The test involves withholding water; this is not the stated trigger."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-012","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-012","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":12,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-013","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Desmopressin response","question":"After desmopressin is given during diagnostic testing, which response supports central DI?","options":["Urine osmolality remains unchanged","Urine output increases and urine becomes more dilute","Serum sodium immediately rises","Urine osmolality rises substantially"],"answer":3,"rationales":["No rise is described for nephrogenic DI.","Desmopressin replaces ADH and should reduce urine output.","A sodium rise is not the diagnostic response described.","The slides state urine osmolality rises after desmopressin in central DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-013","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-013","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":13,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-014","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI pharmacology","question":"Which medication is a synthetic form of vasopressin used to replace ADH?","options":["Tolvaptan","Furosemide","Conivaptan","Desmopressin (DDAVP)"],"answer":3,"rationales":["Tolvaptan is a vasopressin receptor antagonist used in SIADH.","Furosemide is a loop diuretic.","Conivaptan is an IV vasopressin receptor antagonist used in SIADH.","Desmopressin is a synthetic vasopressin that replaces ADH and decreases urination."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-014","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-014","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":14,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-015","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Desmopressin therapeutic effect","question":"Which response should the nurse expect after desmopressin is effective?","options":["Serum sodium rises rapidly","Urine output increases sharply","Urine becomes more dilute","Urine output decreases within about 1 to 2 hours"],"answer":3,"rationales":["Rapid sodium correction is not the desired effect and can be dangerous.","A decrease in urine output is the expected therapeutic effect.","Desmopressin promotes water reabsorption, not more dilute urine.","The slides state DDAVP can decrease urine output in 1 to 2 hours."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-015","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-015","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":15,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-016","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Desmopressin safety","question":"Which adverse effect is an important concern with desmopressin?","options":["Hyponatremia from water retention","Hypercalcemia","Persistent polyuria from ADH blockade","Severe hypernatremia from water loss"],"answer":0,"rationales":["The slides list hyponatremia as an adverse reaction and warn that desmopressin can cause SIADH.","Hypercalcemia is not listed as a desmopressin adverse effect.","Desmopressin replaces ADH rather than blocking it.","Desmopressin decreases water loss; hypernatremia is not the listed adverse effect."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-016","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-016","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":16,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-017","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Nephrogenic DI pharmacology","question":"Which medication may be used for nephrogenic DI by reducing urine volume through a thiazide effect?","options":["Hydrochlorothiazide","Desmopressin","Tolvaptan","Conivaptan"],"answer":0,"rationales":["Thiazides such as hydrochlorothiazide are listed for nephrogenic DI.","Desmopressin replaces ADH and is most directly used for central DI.","Tolvaptan treats SIADH-related hyponatremia.","Conivaptan treats SIADH-related hyponatremia."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-017","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-017","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":17,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-018","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI medication review","question":"Which additional medication options are named in the slides for DI?","options":["Carbamazepine, chlorpropamide, and indomethacin","Tolvaptan, conivaptan, and furosemide only","Levothyroxine and methimazole","Anaphylaxis medications"],"answer":0,"rationales":["The slides list carbamazepine for central DI, chlorpropamide for nephrogenic DI, and NSAIDs such as indomethacin.","Tolvaptan and conivaptan are SIADH therapies; furosemide is listed for SIADH.","These are thyroid medications, not DI treatments.","These are used for allergic emergencies, not DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-018","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-018","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":18,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-019","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI fluid therapy","question":"A client with DI is prescribed hypotonic IV fluids. What is the purpose?","options":["Replace free-water losses and restore water balance","Increase serum sodium concentration","Cause additional diuresis","Prevent all urine production"],"answer":0,"rationales":["The treatment goal is to restore water balance and replace water losses.","Hypernatremia is a concern in DI; increasing sodium would worsen it.","Additional diuresis would worsen DI.","The goal is to control excessive urine output, not eliminate urine production."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-019","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-019","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":19,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-020","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI complication monitoring","question":"Which finding in a post-neurosurgical client receiving desmopressin should the nurse report promptly?","options":["New headache or neurologic changes suggesting possible cerebral edema","Improved urine output","Stable weight","Reduced thirst"],"answer":0,"rationales":["The slides specifically warn to monitor for cerebral edema in clients after neurosurgery who receive desmopressin; neurologic changes should be reported.","Improved urine output is an expected response.","Stable weight is reassuring.","Reduced thirst may occur as water balance improves."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-020","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-020","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":20,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-021","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH pathophysiology","question":"What is the underlying problem in SIADH?","options":["The pituitary releases too little ADH","ADH secretion cannot be appropriately suppressed, causing water retention","The kidneys cannot respond to ADH","The client loses excessive amounts of dilute urine"],"answer":1,"rationales":["ADH deficiency is central DI.","SIADH involves persistent ADH secretion and impaired water excretion.","Renal resistance to ADH is nephrogenic DI.","Excessive dilute urine is DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-021","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-021","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":21,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-022","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH laboratory pattern","question":"Which laboratory pattern is expected in SIADH?","options":["Hypernatremia with dehydration","Low serum sodium and low serum osmolality with concentrated urine","High urine output and low urine specific gravity","High serum sodium and high serum osmolality with dilute urine"],"answer":1,"rationales":["Hypernatremia and dehydration are DI findings.","Water retention dilutes serum sodium and lowers serum osmolality while urine remains concentrated.","High-volume dilute urine is DI.","This is the DI pattern."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-022","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-022","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":22,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-023","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH urinary findings","question":"Which urine finding is expected in SIADH?","options":["Persistently low urine osmolality","Decreased urine output with concentrated urine and high specific gravity","Urine output greater than 3 L/day","Large volumes of dilute urine with low specific gravity"],"answer":1,"rationales":["Urine is concentrated in SIADH.","SIADH causes decreased output of concentrated urine and high specific gravity.","Polyuria greater than 3 L/day is a DI cue.","This describes DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-023","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-023","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":23,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-024","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH causes","question":"Which malignancy is specifically associated with SIADH in the slides?","options":["Prostate cancer","Small-cell lung cancer","Basal cell skin cancer","Renal cell carcinoma"],"answer":1,"rationales":["Although other tumors can affect endocrine function, this slide specifically identifies small-cell lung cancer as a source of ectopic ADH.","Small-cell lung cancer can produce ectopic ADH, leading to inappropriate water retention and SIADH.","This malignancy is not the specific SIADH association identified in the ATI presentation.","This cancer is not the specific ectopic-ADH malignancy identified in the presentation."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-024","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-024","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":24,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-025","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH medication causes","question":"Which medication classes or drugs are listed as possible causes of SIADH?","options":["Thiazides and desmopressin only","Antihistamines and epinephrine only","SSRIs, carbamazepine, oxcarbazepine, and some chemotherapy agents","Insulin and glucagon only"],"answer":2,"rationales":["Thiazides are discussed as DI therapy; desmopressin can cause SIADH but is not the complete listed set.","These are not listed as SIADH causes in the presentation.","The slides list chemotherapy, carbamazepine, oxcarbazepine, chlorpropamide, and SSRIs as medication-related causes.","Insulin and glucagon are not listed as SIADH causes here."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-025","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-025","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":25,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-026","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH diagnostic evaluation","question":"Which condition is a potential contributor to SIADH that should be ruled out during evaluation?","options":["Iron-deficiency anemia","Hypothyroidism or adrenal insufficiency","Appendicitis","Osteoarthritis"],"answer":1,"rationales":["These conditions are not the endocrine mimics specifically identified for exclusion in the slide's SIADH evaluation.","Hypothyroidism and adrenal insufficiency can produce findings that resemble SIADH and should be excluded during evaluation.","This is not one of the endocrine conditions the slides specify ruling out before diagnosing SIADH.","This option does not identify the endocrine disorders emphasized in the SIADH differential diagnosis."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-026","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-026","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":26,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-027","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH neurologic complications","question":"Which neurologic finding can indicate worsening SIADH-related hyponatremia?","options":["New hypertension with bounding pulses","Confusion, lethargy, seizure, or declining level of consciousness","Polyuria and intense thirst only","Increased urine output with dilute urine"],"answer":1,"rationales":["The presentation notes SIADH is often euvolemic and does not necessarily cause hypertension or bounding pulses.","The slides list headache, lethargy, confusion, somnolence, seizures, obtundation, and coma as manifestations.","Polyuria and thirst are more characteristic of DI.","Increased dilute urine is DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-027","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-027","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":27,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-028","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH nursing priorities","question":"What is the priority safety intervention for a client with severe SIADH-related hyponatremia and neurologic changes?","options":["Institute seizure precautions and closely monitor neurologic status","Encourage unrestricted water intake","Encourage ambulation without assistance","Withhold all sodium-containing foods"],"answer":0,"rationales":["Seizure precautions and neurologic monitoring are specifically emphasized for SIADH.","Free-water intake worsens water retention and hyponatremia.","Neurologic impairment increases fall and injury risk.","The slides include encouraging a high-sodium diet as part of management."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-028","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-028","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":28,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-029","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH fluid management","question":"Which nursing intervention is central to SIADH management?","options":["Encourage large amounts of free water","Administer hypotonic IV fluids","Avoid daily weights","Implement prescribed fluid restriction and accurate intake/output monitoring"],"answer":3,"rationales":["Free water worsens dilutional hyponatremia.","Hypertonic, not hypotonic, IV fluids may be anticipated for symptomatic hyponatremia.","Daily weights are part of monitoring fluid balance.","Fluid restriction and accurate intake/output are emphasized in the slides."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-029","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-029","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":29,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-030","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH monitoring","question":"Which additional monitoring is emphasized for a client with SIADH?","options":["Daily weights and frequent or hourly monitoring of sodium, urine output, and mental status","Serum glucose only","Weekly weights only","Urine output once daily"],"answer":0,"rationales":["The slides call for daily weights and hourly assessment of mental status, sodium, and intake/output.","Glucose alone does not assess SIADH severity.","Weekly weights are too infrequent for acute fluid imbalance.","The slides call for close and hourly monitoring, not once daily."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-030","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-030","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":30,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-031","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH treatment","question":"A client with symptomatic SIADH-related hyponatremia is deteriorating neurologically. Which therapy should the nurse anticipate?","options":["Hypertonic IV solution as prescribed","Hypotonic IV solution","Desmopressin","Unrestricted oral water"],"answer":0,"rationales":["The slides state hypertonic IV fluids are anticipated for symptomatic hyponatremia.","Hypotonic fluids worsen dilutional hyponatremia.","Desmopressin increases water retention and is not SIADH treatment.","Unrestricted water worsens hyponatremia."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-031","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-031","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":31,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-032","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Vasopressin antagonists","question":"Which medication is an oral vasopressin receptor antagonist used for SIADH?","options":["Tolvaptan","Carbamazepine","Hydrochlorothiazide","Desmopressin"],"answer":0,"rationales":["Tolvaptan is an oral vasopressin receptor antagonist listed for SIADH.","Carbamazepine is listed as an option for central DI and as a potential SIADH cause.","Hydrochlorothiazide is listed for nephrogenic DI.","Desmopressin is a synthetic ADH replacement used for DI."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-032","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-032","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":32,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-033","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Vasopressin antagonists","question":"Which medication is administered IV as a vasopressin receptor antagonist?","options":["Chlorpropamide","Conivaptan","Tolvaptan","Desmopressin"],"answer":1,"rationales":["Chlorpropamide is listed as an option for nephrogenic DI.","Conivaptan is listed as an IV vasopressin receptor antagonist.","Tolvaptan is oral.","Desmopressin replaces ADH."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-033","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-033","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":33,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-034","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Vaptan black-box warning","question":"What is the major safety concern with tolvaptan or conivaptan therapy?","options":["A decrease in potassium always causes cardiac arrest","A rapid fall in serum glucose causes hypoglycemia","A rapid rise in serum sodium can cause osmotic demyelination and death","A sudden increase in ADH causes DI"],"answer":2,"rationales":["The slide does not state this.","This is not the warning described.","The slide gives a black-box warning that a sodium rise of 12 mEq/L in 24 hours can cause CNS demyelination and death.","These drugs antagonize vasopressin receptors; they do not increase ADH."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-034","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-034","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":34,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-035","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Vaptan monitoring","question":"Which assessments are important during vasopressin antagonist therapy?","options":["Only blood glucose","Only urine color","Only respiratory rate","Serum sodium, renal and hepatic function, other electrolytes, neurologic status, and infusion site if IV"],"answer":3,"rationales":["Glucose alone is insufficient.","Urine color alone is insufficient.","Respiratory rate alone is insufficient.","The slides emphasize sodium, renal/hepatic function, other electrolytes, neurologic changes, and injection-site reactions."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-035","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-035","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":35,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-036","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Vaptan client education","question":"Which teaching should the nurse provide to a client receiving a vasopressin antagonist?","options":["Drink unlimited water to prevent sodium from rising","Ignore new confusion unless a seizure occurs","Report headache, confusion, neurologic changes, and IV-site pain, redness, or swelling","Stop the medication when urine output increases"],"answer":2,"rationales":["Fluid intake should follow the prescribed plan; unlimited water is unsafe.","New confusion is an important neurologic change and should be reported promptly.","The slides instruct clients to report neurologic changes, headache, confusion, and injection-site symptoms.","The client should not stop therapy independently."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-036","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-036","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":36,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-037","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI vs. SIADH comparison","question":"Which comparison correctly distinguishes DI from SIADH?","options":["Both disorders cause concentrated urine and hypernatremia","DI: low urine output and hyponatremia; SIADH: high urine output and hypernatremia","Both disorders cause polyuria and high serum osmolality","DI: high urine output, high serum osmolality, hypernatremia; SIADH: low urine output, low serum osmolality, hyponatremia"],"answer":3,"rationales":["DI causes dilute urine and SIADH causes concentrated urine; SIADH causes hyponatremia.","This reverses the expected patterns.","SIADH causes water retention, low urine output, and low serum osmolality.","This matches the comparison and discussion table in the slides."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-037","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-037","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":37,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-038","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"Water-deprivation test complications","question":"A client with DI becomes dizzy when standing and has tachycardia during a water-deprivation test. What complication should the nurse suspect?","options":["Hypervolemia","Dehydration with reduced circulating volume","Acute SIADH","Fluid overload"],"answer":1,"rationales":["Hypervolemia is not consistent with the described water loss.","The slides identify dizziness, tachycardia, and postural hypotension as early dehydration manifestations during water deprivation.","The described symptoms during water deprivation are associated with dehydration.","These findings suggest volume depletion, not overload."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-038","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-038","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":38,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-039","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"DI plan of care","question":"Which plan best reflects the overall goal of DI treatment?","options":["Restrict all fluids and increase urine concentration through water loss","Suppress all pituitary hormone activity","Promote sodium retention and reduce serum osmolality","Hydrate the client, replace electrolytes, and normalize ADH effect"],"answer":3,"rationales":["Fluid restriction would worsen DI-related water loss.","Suppressing all pituitary hormones is not the treatment goal.","The goal is to correct hypernatremia and water deficit, not increase sodium.","The slides state the goal is hydration, electrolyte replacement, and normalization of ADH levels/effect."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-039","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-039","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":39,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"},{"id":"CH5-CED-040","moduleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","category":"Critical Endocrine Dysfunction","tag":"SIADH volume status","question":"Which statement about SIADH volume status is consistent with the presentation?","options":["All clients develop severe peripheral edema and hypertension","SIADH causes profound dehydration from polyuria","Clients may be euvolemic and may not have hypertension or peripheral edema","SIADH always causes shock"],"answer":2,"rationales":["The presentation explicitly notes these findings are not necessarily present.","Polyuria and dehydration are characteristic of DI.","The slides describe euvolemic hyponatremia and note hypertension and peripheral edema may be absent.","Shock is not described as the expected SIADH volume status."],"case":null,"noteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","noteTitle":"Critical Endocrine Dysfunction — DI & SIADH","conceptId":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-040","conceptTarget":{"id":"ch5-critical-endocrine-dysfunction-ati-deep-dive_q_ch5-ced-040","sourceModuleId":"ch5-critical-endocrine-dysfunction-ati-deep-dive","sourceNoteId":"ch5-critical-endocrine-dysfunction-ati-deep-dive-di-siadh","itemIndex":40,"title":"Critical Endocrine Dysfunction — DI & SIADH"},"distractorAudit":"source-grounded-ati-pptx-2026-11-11","distractorStandard":"same-domain-plausible-no-absurd-giveaways"}],"ch5-syllabus-gap-coverage":[{"id":"CH5-GAP-001","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Immune laboratory interpretation","question":"A client with suspected systemic lupus erythematosus has laboratory testing ordered. Which result is most directly associated with autoimmune activity?","options":["A positive urine ketone test","A positive antinuclear antibody (ANA) test","A low serum TSH","A low hemoglobin A1c"],"answer":1,"rationales":["Urine ketones indicate fat breakdown and may occur with fasting or diabetes; they do not identify lupus-related autoimmunity.","ANA detects antinuclear antibodies and is commonly positive in SLE, although a positive result alone does not establish the diagnosis.","TSH evaluates thyroid regulation; it is not a marker of lupus activity.","HbA1c estimates longer-term glycemic control and does not assess autoimmune activity."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-002","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Inflammation laboratory interpretation","question":"A client with a suspected inflammatory disorder has an erythrocyte sedimentation rate (ESR) ordered. What does an elevated ESR indicate?","options":["The exact level of immune suppression","A nonspecific marker of inflammation","The client’s current blood glucose","A definitive diagnosis of rheumatoid arthritis"],"answer":1,"rationales":["An ESR cannot quantify immune suppression; it is an indirect, nonspecific inflammatory marker.","ESR often rises with inflammation, but infection, autoimmune disease, and other conditions can elevate it, so it does not identify a specific cause.","Blood glucose is measured directly with glucose testing, not by ESR.","RA diagnosis uses clinical findings and supporting tests; ESR may reflect inflammation but cannot confirm RA."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-003","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Rheumatoid factor","question":"A client being evaluated for rheumatoid arthritis has a positive rheumatoid factor. How should the nurse interpret this result?","options":["It supports the evaluation but does not confirm RA by itself.","It confirms an acute bacterial infection.","It measures the severity of joint destruction.","It proves the client has RA."],"answer":0,"rationales":["Rheumatoid factor can support an RA evaluation, but it may also be present in other conditions or in some healthy people.","A positive rheumatoid factor is not a test for acute bacterial infection; cultures and other investigations address suspected infection.","RF does not measure joint damage; imaging and clinical assessment evaluate structural injury.","Some people with RA are RF-negative, and RF positivity alone is insufficient to prove RA."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-004","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Immunoglobulins","question":"A client with recurrent infections is being evaluated for an immune deficiency. Which test evaluates circulating antibody levels?","options":["Serum immunoglobulin levels","Thyroid-stimulating hormone","Serum potassium","Hemoglobin A1c"],"answer":0,"rationales":["Immunoglobulin testing measures antibody classes such as IgG, IgA, and IgM, helping evaluate humoral immune function.","TSH assesses thyroid function and does not quantify circulating antibodies.","Potassium is an electrolyte measurement; it does not measure antibody production.","HbA1c reflects average glucose over time, not immune antibody levels."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-005","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"HIV monitoring","question":"Which laboratory value is most useful for evaluating immune-system status in a client with HIV?","options":["Hemoglobin A1c","CD4 T-cell count","Serum calcium","ESR alone"],"answer":1,"rationales":["HbA1c evaluates glycemic control and is not the principal laboratory measure of HIV-related immune status.","CD4 T-cell count helps assess immune function and HIV-related immunosuppression, including risk for opportunistic infection.","Calcium is an electrolyte and metabolic measure, not a direct indicator of HIV-related immune status.","ESR is nonspecific and cannot replace CD4 count when assessing HIV-related immune function."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-006","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"HIV monitoring","question":"A client with HIV has a viral load test. Which outcome indicates that antiretroviral therapy is effectively suppressing viral replication?","options":["The client develops a positive ANA.","The CD4 count becomes zero.","The ESR increases.","The viral load becomes very low or undetectable."],"answer":3,"rationales":["ANA testing evaluates autoantibodies and does not show whether antiretroviral therapy is suppressing HIV replication.","A CD4 count of zero would indicate profound immunosuppression, not successful viral suppression.","ESR may change with inflammation but does not measure HIV replication or treatment response.","A very low or undetectable viral load indicates that treatment is suppressing HIV replication."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-007","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"HIV diagnostic testing","question":"A client asks why an initial HIV screening test may be followed by additional testing. Which response is accurate?","options":["An EIA measures viral load directly.","A reactive screening result requires supplemental testing to establish the diagnosis.","One reactive screening result always confirms HIV.","A Western blot measures the client’s CD4 count."],"answer":1,"rationales":["EIA/antigen-antibody screening does not directly quantify viral RNA; viral load testing is a separate test.","A reactive screening result must be followed by the recommended supplemental diagnostic algorithm before HIV is confirmed.","A single reactive screen can be false-positive and is not, by itself, definitive confirmation.","Western blot is a historical supplemental test, not a CD4 test; current diagnostic algorithms use other supplemental assays."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-008","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"CBC interpretation","question":"A client receiving immunosuppressive therapy has a markedly decreased absolute neutrophil count. Which action is the priority?","options":["Administer a live vaccine without checking the plan.","Encourage fresh flowers in the room.","Use a rectal thermometer for routine temperatures.","Initiate the prescribed neutropenic precautions and promptly report the result."],"answer":3,"rationales":["Live vaccines may be unsafe in severe immunosuppression and require review by the treating team; they are not the immediate priority with neutropenia.","Fresh flowers can carry microorganisms or mold and are generally avoided when neutropenic precautions are prescribed.","Rectal temperatures can injure mucosa and introduce infection; use an approved noninvasive route.","Marked neutropenia increases risk for rapidly progressive infection; implement ordered precautions and promptly escalate the critical result."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-009","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Renal laboratory interpretation","question":"A client with dehydration from diabetes insipidus has rising BUN and creatinine. What does this finding suggest?","options":["A normal response to desmopressin","Reduced renal perfusion or kidney function related to fluid depletion.","Increased thyroid hormone production","Improved hydration"],"answer":1,"rationales":["Desmopressin treats central DI by replacing ADH activity; rising renal markers during dehydration are not a normal treatment response.","Fluid depletion can reduce renal perfusion and raise BUN and creatinine, requiring assessment and correction of the volume deficit.","Thyroid hormone production is unrelated to the rise in BUN and creatinine described in DI-related dehydration.","Rising BUN and creatinine in a dehydrated client do not indicate improved hydration; they may signal worsening volume depletion or kidney injury."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-010","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Thyroid laboratory interpretation","question":"A client has primary hypothyroidism. Which laboratory pattern should the nurse expect?","options":["Elevated serum sodium with dilute urine","Decreased TSH with elevated free T4","Elevated TSH with decreased free T4","Elevated cortisol with decreased ACTH"],"answer":2,"rationales":["High sodium with dilute urine is more consistent with water loss such as DI, not primary hypothyroidism.","In primary hypothyroidism, the thyroid produces too little hormone, so pituitary TSH typically rises rather than falls.","High TSH with low free T4 is the expected pattern when the thyroid gland itself is underactive.","Cortisol and ACTH are adrenal-axis tests and do not define primary hypothyroidism."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-011","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Thyroid laboratory interpretation","question":"A client has primary hyperthyroidism. Which laboratory pattern is expected?","options":["Elevated TSH with low T4","Suppressed TSH with elevated T3 and/or T4","Low cortisol with high ACTH","Low serum sodium with concentrated urine"],"answer":1,"rationales":["High TSH with low T4 indicates primary hypothyroidism, not primary hyperthyroidism.","Excess thyroid hormone feeds back to suppress pituitary TSH; T3 and/or T4 are elevated.","Low cortisol with high ACTH suggests primary adrenal insufficiency, not thyroid hormone excess.","Low sodium with concentrated urine may occur in SIADH and does not identify hyperthyroidism."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-012","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Adrenal laboratory interpretation","question":"A client is being evaluated for adrenal insufficiency. Which finding supports low cortisol production?","options":["Low TSH as the defining test","High HbA1c as a direct measure of cortisol","Low cortisol, with ACTH helping distinguish primary from secondary causes.","High cortisol in every form of adrenal insufficiency"],"answer":2,"rationales":["TSH evaluates the thyroid axis and is not the defining laboratory test for adrenal insufficiency.","HbA1c reflects average blood glucose and does not directly measure cortisol production.","Low cortisol supports adrenal insufficiency; ACTH helps distinguish primary adrenal failure (often elevated ACTH) from central causes (low or inappropriately normal ACTH).","Adrenal insufficiency is characterized by inadequate cortisol, not high cortisol."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-013","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Diabetes monitoring","question":"Which test best reflects average blood glucose over approximately the previous 2 to 3 months?","options":["A single point-of-care glucose","Urine specific gravity","Serum TSH","Hemoglobin A1c"],"answer":3,"rationales":["A single point-of-care glucose is a snapshot and cannot represent the average over several months.","Urine specific gravity reflects urine concentration and hydration, not long-term blood glucose.","TSH evaluates thyroid function and is unrelated to average glycemic control.","HbA1c reflects average glucose over roughly the preceding 2 to 3 months."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-014","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Diabetes assessment","question":"A client with diabetes reports sweating, tremors, and sudden confusion. What should the nurse do first?","options":["Obtain a fasting lipid profile.","Wait until the next scheduled HbA1c.","Measure the TSH.","Check the blood glucose promptly."],"answer":3,"rationales":["A lipid profile is not the immediate assessment when symptoms suggest acute hypoglycemia.","Waiting for HbA1c delays assessment of a potentially urgent low blood glucose; HbA1c is not a point-in-time test.","TSH does not identify hypoglycemia and should not delay checking glucose.","Sweating, tremors, and confusion are compatible with hypoglycemia; promptly check point-of-care glucose and treat per protocol."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-015","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Urinalysis","question":"A client with diabetes has a urinalysis ordered. Which finding may indicate glucose spilling into the urine?","options":["Low urine specific gravity proves hypothyroidism","Ketonuria is always absent in diabetes","Hematuria confirms hyperglycemia","Glucosuria"],"answer":3,"rationales":["Low specific gravity reflects dilute urine and does not establish hypothyroidism or explain glucosuria.","Ketonuria can occur in diabetes, particularly with insulin deficiency or fasting; it is not always absent.","Hematuria means blood in urine and does not confirm hyperglycemia.","Glucosuria means glucose is present in urine, which can occur when blood glucose exceeds the renal threshold or with certain renal conditions."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-016","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Lipid profile","question":"Why is a lipid profile relevant when caring for a client with diabetes?","options":["Diabetes increases cardiovascular risk, so lipid abnormalities require assessment and management.","It determines the client’s CD4 count.","It measures insulin secretion directly.","It confirms diabetic ketoacidosis."],"answer":0,"rationales":["Diabetes increases atherosclerotic cardiovascular risk; lipid testing identifies dyslipidemia that may need treatment.","CD4 count assesses immune status, particularly in HIV, and is not measured by a lipid profile.","Lipid testing measures cholesterol and triglycerides; it does not directly measure pancreatic insulin secretion.","DKA is assessed using glucose, ketones, acid-base status, and electrolytes; a lipid profile does not confirm it."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-017","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Glucometer safety","question":"The nurse prepares to obtain a point-of-care glucose. Which action supports accurate testing?","options":["Use the meter and test strip according to manufacturer instructions and verify quality-control requirements.","Share a lancing device after changing the lancet.","Reuse a lancet between clients if the skin is cleaned.","Use expired test strips if the result appears plausible."],"answer":0,"rationales":["Following the meter and strip instructions, checking expiration/storage, and meeting quality-control requirements supports reliable results.","Changing the lancet alone does not make a shared lancing device safe; finger-stick devices must never be shared between clients.","Reusing a lancet between clients risks bloodborne pathogen transmission even if the skin is cleaned.","Expired strips can produce inaccurate readings; use in-date supplies and follow quality-control procedures."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-018","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Insulin administration safety","question":"Before administering insulin, which nursing action is essential?","options":["Verify the insulin type, dose, timing, blood glucose, and meal status as appropriate.","Assume all insulin products have the same onset.","Mix any two insulin products without checking compatibility.","Give rapid-acting insulin and then delay the meal indefinitely."],"answer":0,"rationales":["Insulin is a high-alert medication; verify the correct product and dose and coordinate administration with glucose level and meal availability.","Insulin formulations have different onsets, peaks, and durations; assuming they are interchangeable can cause hypo- or hyperglycemia.","Only compatible insulins may be mixed, and product-specific instructions must be followed; never mix without verification.","Rapid-acting insulin should be coordinated with food availability; delaying the meal can cause hypoglycemia."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-019","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Telemetry","question":"A client with severe potassium imbalance is on telemetry. What is the primary purpose?","options":["Continuous monitoring for dysrhythmias associated with electrolyte changes.","Measurement of blood glucose every minute","Direct measurement of serum potassium","Replacement of the need for physical assessment"],"answer":0,"rationales":["Telemetry monitors electrical cardiac activity; it does not measure glucose or replace electrolyte laboratory testing.","Telemetry displays cardiac rhythm and does not provide minute-by-minute blood glucose measurements.","Serum potassium requires a blood test; telemetry may reveal cardiac effects but cannot determine the potassium concentration.","Telemetry supplements, rather than replaces, assessment of symptoms, vital signs, and laboratory results."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-020","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"IV access","question":"A client with severe dehydration from diabetes insipidus requires IV fluid replacement. What should the nurse prioritize?","options":["Assess IV access patency and monitor the prescribed fluid rate and response.","Use an infiltrated IV site because fluids are urgent.","Infuse hypotonic fluid rapidly without an order.","Stop monitoring intake and output once fluids begin."],"answer":0,"rationales":["Confirm a functioning IV site, administer only the prescribed fluid at the ordered rate, and monitor hemodynamic status, electrolytes, and response.","An infiltrated IV cannot safely deliver the prescribed fluid and may cause tissue injury; stop using it and establish appropriate access.","Hypotonic fluids and their rate require a specific prescription and careful monitoring; rapid unprescribed infusion can cause dangerous sodium shifts.","Strict intake and output remain important during fluid replacement to evaluate response and avoid under- or over-replacement."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-021","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Urinary catheter monitoring","question":"A client with diabetes insipidus has an indwelling urinary catheter for strict output measurement. Which nursing action is appropriate?","options":["Place the drainage bag above bladder level.","Maintain a closed drainage system and measure output accurately.","Disconnect the tubing routinely to obtain samples.","Irrigate the catheter on a fixed schedule without an indication."],"answer":1,"rationales":["The drainage bag must remain below bladder level to prevent backflow and reduce infection risk.","A closed system reduces catheter-associated infection risk; measure and document urine output accurately.","Routine disconnection breaks the closed system and increases the risk of introducing microorganisms.","Routine irrigation without an indication is not recommended and can disrupt the system or cause harm."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-022","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Pulse oximetry","question":"A client with Guillain-Barré syndrome has a normal oxygen saturation but worsening respiratory effort. What should the nurse recognize?","options":["Oxygen saturation directly measures vital capacity.","Pulse oximetry alone may not detect early ventilatory muscle failure.","The client no longer needs respiratory assessment.","A normal saturation rules out respiratory compromise."],"answer":1,"rationales":["Pulse oximetry estimates oxygen saturation; it does not measure vital capacity or directly assess respiratory muscle strength.","GBS can weaken respiratory muscles before oxygen saturation falls; assess respiratory effort and trends in vital capacity/negative inspiratory force as ordered.","A normal saturation does not remove the need for close respiratory assessment because neuromuscular weakness can progress.","Normal SpO2 does not rule out impending ventilatory failure in GBS; worsening effort is an urgent warning sign."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-023","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — immunosuppressants","question":"A client taking an immunosuppressant reports fever and sore throat. What is the best nursing response?","options":["Tell the client to stop every prescribed medication permanently.","Promptly notify the provider and evaluate for infection.","Recommend a live vaccine immediately.","Reassure the client that fever is an expected harmless effect."],"answer":1,"rationales":["Stopping all medications permanently is not an appropriate response; promptly assess and escalate possible infection while the prescriber guides medication decisions.","Fever and sore throat during immunosuppression may signal infection or a medication-related blood-cell problem and require prompt evaluation.","Live vaccines may be contraindicated or require specialist review during immunosuppressive therapy; do not recommend one immediately.","Fever in an immunosuppressed client is potentially serious and should never be dismissed as harmless."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-024","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — DMARDs","question":"A client taking a disease-modifying antirheumatic drug (DMARD) asks why laboratory monitoring is needed. Which response is best?","options":["Laboratory testing replaces assessment for infection.","Some DMARDs can cause serious adverse effects, so blood counts and organ function may need monitoring.","DMARDs cannot affect blood cells or organs.","Monitoring is only needed to measure pain intensity."],"answer":1,"rationales":["Laboratory monitoring does not replace clinical assessment; infection can occur even when routine tests are stable.","Some DMARDs can suppress bone marrow or affect liver and kidney function, so monitoring depends on the specific medication.","Certain DMARDs can cause cytopenias and organ toxicity; claiming they cannot affect blood cells or organs is unsafe.","Laboratory monitoring evaluates potential medication toxicity and safety, not simply pain intensity."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-025","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — glucocorticoids","question":"A client has taken long-term systemic glucocorticoids. Which teaching is most important?","options":["Stop the medication as soon as symptoms improve.","Avoid reporting fever because steroids prevent infection.","Do not stop the medication abruptly; follow the prescribed taper or replacement plan.","Take extra doses whenever fatigue occurs."],"answer":2,"rationales":["Long-term glucocorticoids suppress the hypothalamic-pituitary-adrenal axis; abrupt withdrawal can precipitate adrenal insufficiency.","Steroids can mask infection signs and increase infection risk; fever or other symptoms still require prompt reporting.","Follow the prescribed taper or replacement regimen; do not discontinue systemic steroids suddenly after prolonged use.","Extra doses without an order can worsen adverse effects such as hyperglycemia and infection risk."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-026","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — thyroid replacement","question":"A client prescribed levothyroxine asks how to take it. Which instruction is appropriate?","options":["Stop it when energy improves.","Take it consistently as prescribed, commonly on an empty stomach, and separate it from interfering supplements as directed.","Take it only when symptoms occur.","Double the next dose whenever one dose is missed without checking instructions."],"answer":1,"rationales":["Levothyroxine is replacement therapy and should not be stopped just because symptoms improve; treatment is often lifelong.","Consistent administration, commonly on an empty stomach, supports absorption; calcium and iron supplements can interfere and should be separated as directed.","Levothyroxine replaces thyroid hormone continuously; it is not a PRN medication for symptoms.","Doubling doses without individualized instructions can cause excessive thyroid hormone exposure; follow the missed-dose guidance from the prescriber or pharmacist."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-027","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — antithyroid drugs","question":"A client taking propylthiouracil reports fever and sore throat. What should the nurse instruct?","options":["Take an extra dose to suppress thyroid activity.","Report these symptoms promptly because they may indicate a serious blood dyscrasia.","Continue the medication and wait several weeks.","Ignore the symptoms unless a rash appears."],"answer":1,"rationales":["An extra PTU dose does not address possible agranulocytosis and could increase medication toxicity.","Fever and sore throat may indicate agranulocytosis, a serious adverse effect; the client should contact the prescriber promptly for evaluation and instructions.","Waiting several weeks could delay recognition of a potentially life-threatening blood dyscrasia.","A rash is not required for agranulocytosis; fever or sore throat alone warrants prompt reporting."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-028","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Medication safety — epinephrine","question":"A client develops airway swelling, wheezing, and hypotension after an allergen exposure. Which medication is the priority?","options":["Intramuscular epinephrine","Oral antihistamine alone","A topical corticosteroid","A thyroid hormone"],"answer":0,"rationales":["IM epinephrine is first-line for anaphylaxis because it treats airway edema, bronchospasm, and hypotension; administer promptly per emergency protocol.","An oral antihistamine may help itching or hives but does not adequately treat airway compromise or shock and must not delay epinephrine.","A topical corticosteroid cannot reverse systemic airway swelling, bronchospasm, or hypotension.","Thyroid hormone has no role in the immediate treatment of anaphylaxis."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-029","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Gabapentin safety","question":"A client taking gabapentin for diabetic neuropathy reports feeling dizzy when standing and nearly falling. What is the best nursing response?","options":["Assess fall risk and sedation, reinforce safety precautions, and report persistent or severe effects","Tell the client to take an extra dose at bedtime","Explain that dizziness means the nerve damage is being reversed","Instruct the client to stop the medication abruptly"],"answer":0,"rationales":["Dizziness and somnolence can occur with gabapentin; assess severity, reduce fall risk, and communicate concerning effects to the prescriber.","Extra dosing may worsen CNS adverse effects and increase fall risk.","Dizziness is an adverse effect, not evidence that nerve damage is reversing.","The client should not discontinue it abruptly without prescriber guidance."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-030","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Nutrition — high calorie/high protein","question":"A client with increased metabolic demands and poor nutritional intake is prescribed a high-calorie, high-protein diet. Which meal best follows this plan?","options":["Chicken, eggs, Greek yogurt, and a calorie-dense side.","Black coffee and a piece of celery","Clear broth and unsweetened gelatin only","A small lettuce salad with diet dressing"],"answer":0,"rationales":["Chicken and eggs provide protein, Greek yogurt adds protein and calories, and a calorie-dense side helps meet increased energy needs.","Coffee and celery provide very little energy or protein and would not meet increased nutritional demands.","Clear broth and gelatin alone are low in protein and calories and are inadequate for this nutrition goal.","A small lettuce salad with diet dressing is low in both calories and protein."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-031","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Nutrition — low calorie/low fat","question":"A client is prescribed a low-calorie, low-fat diet. Which choice best fits the plan?","options":["Grilled fish, steamed vegetables, and a modest portion of whole grain.","Fried chicken with cream sauce","Bacon cheeseburger and fries","Whole-milk milkshake and pastries"],"answer":0,"rationales":["Grilled fish supplies lean protein, vegetables add fiber and micronutrients, and a moderate whole-grain portion fits a balanced lower-calorie, lower-fat plan.","Fried chicken and cream sauce add substantial fat and calories, making this a poor fit.","A bacon cheeseburger and fries are typically high in saturated fat and calories.","A whole-milk milkshake and pastries are calorie-dense and high in fat, so they do not fit the prescribed plan."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-032","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Therapeutic communication","question":"A client newly diagnosed with HIV says, “My life is over.” Which response is therapeutic?","options":["“Tell me what concerns you most right now.”","“You need to stay positive.”","“At least it is not AIDS.”","“You should not feel that way.”"],"answer":0,"rationales":["This open-ended response invites the client to identify their immediate fears and feelings without judgment.","Directing the client to stay positive can minimize distress rather than exploring what the diagnosis means to them.","Comparing the diagnosis with another condition dismisses the client's fear and does not encourage expression.","Telling the client how they should feel is judgmental and may shut down communication."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-033","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Cultural and spiritual care","question":"A client with a complex immune disorder requests a cultural or spiritual practice during care. What should the nurse do?","options":["Proceed without discussing the request.","Ask about the practice, assess safety, and incorporate it when possible with the client’s preferences guiding care.","Assume all clients from the same culture want the same care.","Dismiss the request if it differs from the nurse’s beliefs."],"answer":1,"rationales":["Proceeding without discussion disregards the client's preferences and misses an opportunity to assess safety and meaning.","Ask the client what the practice involves, assess for safety or treatment conflicts, and accommodate it when possible while respecting their beliefs.","People within a cultural group are individuals; assuming identical preferences can lead to stereotyping and culturally unsafe care.","The nurse should not impose personal beliefs; dismissing a safe spiritual or cultural request undermines respectful, person-centered care."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-034","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Ethical/legal accountability","question":"A nurse identifies that a prescribed medication dose appears unsafe. What is the nurse’s responsibility?","options":["Document the concern but take no action.","Administer it because the provider prescribed it.","Hold the medication as appropriate, clarify the order with the prescriber, and follow the chain of command.","Ask an unlicensed assistive personnel to decide whether it is safe."],"answer":2,"rationales":["Documentation alone does not resolve a potentially unsafe order; the nurse must take appropriate action to protect the client.","A prescription does not remove the nurse's accountability to question an order that appears unsafe before administration.","Clarify the questionable order with the prescriber, withhold it when indicated under policy, and use the chain of command if the concern remains unresolved.","Medication safety decisions require a licensed nurse's assessment and appropriate prescriber communication, not delegation to assistive personnel."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-035","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Delegation and scope","question":"Which task is appropriate to delegate to trained assistive personnel for a stable client with an immune disorder?","options":["Teach the client how to manage immunosuppressant therapy.","Assess new-onset shortness of breath.","Interpret a new abnormal CD4 count.","Obtain routine vital signs and report abnormal findings."],"answer":3,"rationales":["Teaching medication management requires nursing judgment and assessment of learning, so it is not delegated to assistive personnel.","New shortness of breath requires prompt assessment by the nurse because it may signal deterioration.","Interpreting an abnormal CD4 result requires clinical judgment and is the nurse's responsibility.","Routine vital signs on a stable client may be delegated to trained assistive personnel, with abnormal findings reported to the nurse."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-036","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Older adult assessment","question":"When assessing an older adult with a complex immune alteration, which approach is most appropriate?","options":["Assume fever will always be the first sign of infection.","Exclude the caregiver even when the client requests support.","Assess baseline function, cognition, nutrition, medications, infection signs, and the client’s ability to perform self-care.","Use the same baseline expectations as a healthy young adult."],"answer":2,"rationales":["Older adults may have atypical infection presentations, including no fever; do not rely on fever as the only warning sign.","When the client wants caregiver support, include that person with the client's permission while maintaining the client's autonomy.","Assessment must include function, cognition, nutrition, medications, infection cues, and self-care capacity rather than relying on one narrow data source.","Age-related changes and comorbidities mean a healthy young-adult baseline may not be appropriate; compare with the individual's baseline."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-037","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Psychosocial coping","question":"A client with a chronic immune disorder reports isolation and difficulty coping. What is the nurse’s best action?","options":["Assume family support is available.","Tell the client to avoid discussing emotions.","Focus only on laboratory results.","Assess coping, support systems, stressors, and preferred resources; collaborate on support."],"answer":3,"rationales":["Do not assume family support exists; assess the client's actual support network and preferences.","Discouraging discussion of emotions can increase isolation and prevents assessment of coping needs.","Laboratory monitoring is important but does not address psychosocial distress, coping, or social isolation.","Explore coping, stressors, support people, and resources the client prefers, then collaborate on an individualized support plan."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-038","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Patient education and safety","question":"A client receiving immunosuppressive therapy is preparing for discharge. Which teaching is most important?","options":["Ignore mild infection symptoms until the next appointment.","Report fever or signs of infection promptly and review vaccine safety with the care team.","Stop medication whenever exposed to infection.","Receive any live vaccine without consultation."],"answer":1,"rationales":["Delaying mild infection symptoms can be dangerous during immunosuppression; teach prompt reporting of fever and other infection signs.","Prompt reporting and individualized vaccine review help reduce infection risk; live vaccines may be unsafe depending on the medication and immune status.","Clients should not independently stop immunosuppressants; contact the treating team for individualized instructions after exposure or infection.","Live vaccines can pose risk during significant immunosuppression; vaccine decisions must be reviewed with the care team."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-039","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Endocrine assessment","question":"A client with a suspected endocrine disorder reports fatigue, weight changes, and altered temperature tolerance. Which assessment approach is best?","options":["Use one symptom to establish the diagnosis.","Assess only the affected gland’s location.","Review laboratory values without assessing the client.","Combine symptom history, focused physical assessment, vital signs, medication history, and relevant hormone/lab results."],"answer":3,"rationales":["One symptom such as fatigue is nonspecific and cannot establish an endocrine diagnosis.","Endocrine disorders may produce systemic effects; assessment should not be limited to the anatomical location of one gland.","Laboratory values need to be interpreted alongside symptoms, examination findings, and clinical context.","Combining history, focused examination, vital signs, medication review, and relevant hormone results provides a safer, more complete assessment."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-040","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Acid-base and electrolyte assessment","question":"A client with a severe metabolic alteration has an abnormal arterial pH and electrolyte results. What should the nurse do?","options":["Treat the laboratory value without assessing the client.","Delay reporting a critical result until the next routine round.","Correlate the results with respiratory status, cardiac rhythm, mentation, vital signs, and the clinical condition.","Assume all electrolyte abnormalities produce identical symptoms."],"answer":2,"rationales":["Treating a number without assessing the client can miss the cause and the immediate threat to organ function.","Critical pH or electrolyte abnormalities can cause rapid deterioration; follow critical-result policy and escalate promptly.","Correlating acid-base and electrolyte results with respiratory, cardiac, neurologic, and hemodynamic findings helps identify severity and guide urgent care.","Different electrolyte disturbances have different effects; assess the specific abnormality rather than assuming one symptom pattern."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null},{"id":"CH5-GAP-041","moduleId":"ch5-syllabus-gap-coverage","category":"Syllabus Gap Coverage","tag":"Client advocacy","question":"A client declines a recommended treatment after receiving information. What is the nurse’s best action?","options":["Proceed because the treatment is beneficial.","Assess understanding and concerns, support informed decision-making, and communicate the decision to the team.","Ask family to override the client automatically.","Threaten the client with loss of care."],"answer":1,"rationales":["Providing treatment against the client's informed refusal violates autonomy and the right to make decisions about care.","Assess the client's understanding and concerns, support informed choice, document appropriately, and communicate the decision to the healthcare team.","Family members do not automatically have authority to override a capable adult client's decision.","Threatening or coercing the client is inappropriate; maintain a therapeutic relationship and respect informed decision-making."],"case":null,"noteId":"ch5-unit5-syllabus-and-three-ati-powerpoints","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints","conceptId":null}],"ch5-advanced-nclex-priority-clinical-judgment":[{"id":"CH5-FINAL-001","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"DKA vs HHS","question":"A client with diabetes has glucose 560 mg/dL, deep rapid respirations, abdominal pain, and positive serum ketones. Which complication is most likely?","options":["Hyperosmolar hyperglycemic state (HHS)","Diabetic ketoacidosis (DKA)","Diabetes insipidus","Hypoglycemia"],"answer":1,"rationales":["HHS usually causes profound dehydration and hyperosmolality with little or no ketosis; the positive ketones and Kussmaul-type respirations point away from HHS.","DKA is characterized by hyperglycemia, ketone production, and metabolic acidosis; Kussmaul respirations and abdominal pain are common clues.","Diabetes insipidus causes excessive dilute urine and water-balance abnormalities; it does not explain marked hyperglycemia with ketones.","Hypoglycemia is a low-glucose state and does not fit a glucose of 560 mg/dL with ketones and metabolic-acidosis clues."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-002","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"DKA priority intervention","question":"A client is admitted with DKA, hypotension, dehydration, and an elevated glucose. Which intervention is generally initiated first?","options":["Administer long-acting insulin and withhold fluids.","Give oral potassium without reviewing the serum level.","Restrict fluids until glucose normalizes.","Begin prescribed isotonic IV fluid replacement."],"answer":3,"rationales":["Long-acting insulin is not the initial priority in a hypotensive, volume-depleted client; restore circulating volume and use the prescribed DKA protocol.","Potassium must be checked and replacement guided by the measured level and protocol; empiric oral potassium is unsafe and does not correct shock.","Fluid restriction worsens the severe dehydration and hypovolemia associated with DKA.","Initial management prioritizes restoring circulating volume with isotonic fluids; insulin and electrolyte management follow the protocol and lab findings."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-003","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"DKA potassium safety","question":"A client with DKA has a potassium level of 3.0 mEq/L. The insulin infusion is prescribed. What should the nurse anticipate?","options":["Restrict potassium and continue insulin.","Give sodium bicarbonate as the only treatment.","Notify the provider and anticipate potassium replacement before insulin is started.","Start insulin immediately because potassium is low."],"answer":2,"rationales":["Potassium is already low; restricting it while giving insulin can worsen hypokalemia and increase dysrhythmia risk.","Bicarbonate is not the sole treatment for DKA and is reserved for selected severe-acidosis situations under protocol; it does not correct the immediate potassium deficit.","Insulin shifts potassium into cells and can worsen hypokalemia; potassium must be corrected according to protocol before insulin when significantly low.","Insulin shifts potassium into cells and can lower serum potassium further; with a potassium of 3.0 mEq/L, correct potassium first according to protocol."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-004","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"HHS recognition","question":"An older adult with type 2 diabetes has profound dehydration, altered mental status, glucose 880 mg/dL, and negative/trace ketones. Which condition is most consistent?","options":["SIADH","Diabetic ketoacidosis (DKA)","Myxedema coma","Hyperosmolar hyperglycemic state (HHS)"],"answer":3,"rationales":["SIADH causes water retention and typically hyponatremia, not extreme hyperglycemia with profound dehydration.","DKA generally produces significant ketones and metabolic acidosis; negative/trace ketones with extreme hyperglycemia and profound dehydration favor HHS.","Myxedema coma is severe hypothyroidism with hypothermia, bradycardia, and depressed mentation; it does not explain this hyperglycemic crisis.","HHS commonly presents with extreme hyperglycemia, hyperosmolality, severe dehydration, and neurologic changes with little or no ketosis."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-005","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Thyroid storm","question":"A client with untreated hyperthyroidism develops a temperature of 104°F (40°C), severe tachycardia, agitation, and vomiting. What complication should the nurse suspect?","options":["Adrenal insufficiency","Myxedema coma","Thyroid storm","Diabetes insipidus"],"answer":2,"rationales":["Adrenal insufficiency more often causes hypotension, weakness, and electrolyte/glucose abnormalities; it does not produce the hypermetabolic fever/tachycardia pattern.","Myxedema coma is the opposite thyroid emergency: hypothermia, bradycardia, and depressed respirations from severe hypothyroidism.","High fever, marked tachycardia, and acute CNS/GI changes in a hyperthyroid client suggest life-threatening thyroid storm.","Diabetes insipidus causes polyuria, thirst, and possible hypernatremia; it does not account for the acute hypermetabolic findings."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-006","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Thyroid storm priority","question":"A client is suspected of having thyroid storm. Which nursing action has the highest priority?","options":["Encourage ambulation to reduce anxiety.","Support airway, breathing, circulation, and initiate urgent escalation while preparing prescribed treatment.","Apply warming blankets for chills without checking temperature.","Delay notifying the provider until thyroid tests return."],"answer":1,"rationales":["Acutely ill clients with thyroid storm need stabilization and rest; ambulation increases metabolic demand and risk.","Thyroid storm is an endocrine emergency; stabilize the client and escalate immediately rather than waiting for confirmatory labs.","The client is already severely hyperthermic; warming blankets could worsen dangerous hyperthermia. Use cooling measures as prescribed.","Thyroid storm is a clinical emergency. Escalation and treatment must not wait for thyroid laboratory confirmation."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-007","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Myxedema coma","question":"An older adult with known hypothyroidism is difficult to arouse, hypothermic, bradycardic, and hypoventilating. Which emergency is most likely?","options":["Myxedema coma","Pheochromocytoma crisis","HHS","Thyroid storm"],"answer":0,"rationales":["Severe hypothyroidism can cause myxedema coma, with hypothermia, depressed mental status, bradycardia, and respiratory depression.","Pheochromocytoma crisis is associated with episodic severe hypertension, headache, sweating, and palpitations rather than the classic hypothermic, bradycardic hypothyroid picture.","HHS presents with severe hyperglycemia, dehydration, and hyperosmolality; it does not explain the characteristic hypothermia and bradycardia.","Thyroid storm causes hyperthermia, tachycardia, and agitation; this client has the opposite pattern."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-008","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Myxedema coma priority","question":"A client with suspected myxedema coma has shallow respirations and decreased level of consciousness. Which concern takes priority?","options":["Respiratory failure and the need for airway/ventilatory support.","Constipation","Weight gain","Dry skin"],"answer":0,"rationales":["Hypoventilation and reduced consciousness can compromise airway protection and ventilation; respiratory support is the immediate priority.","Constipation can occur with hypothyroidism but is not the immediate threat when consciousness and ventilation are declining.","Weight gain is a chronic hypothyroid manifestation, not an acute priority over inadequate ventilation.","Dry skin is a chronic hypothyroid manifestation and does not take priority over respiratory compromise."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-009","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Adrenal crisis recognition","question":"A client with Addison disease develops vomiting, severe weakness, hypotension, and confusion after an infection. Which complication should the nurse suspect?","options":["Cushing syndrome","Acute adrenal crisis","SIADH","Thyroid storm"],"answer":1,"rationales":["Cushing syndrome reflects chronic cortisol excess and is not the likely explanation for acute hypotension and deterioration in a client with Addison disease.","Acute adrenal insufficiency can be precipitated by illness and cause profound hypotension, weakness, GI symptoms, and altered mentation.","SIADH causes water retention and hyponatremia; it does not best explain the acute adrenal-insufficiency picture after infection.","Thyroid storm presents with hyperthermia, marked tachycardia, and hypermetabolic symptoms, not the typical adrenal-crisis pattern."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-010","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Adrenal crisis priority","question":"A client is suspected of having adrenal crisis with severe hypotension. Which treatment should the nurse anticipate?","options":["Insulin infusion as the sole intervention.","Rapid IV isotonic fluids and prescribed IV glucocorticoid replacement.","Oral thyroid hormone only.","Fluid restriction and a loop diuretic."],"answer":1,"rationales":["Insulin alone does not replace deficient cortisol or restore circulating volume; it is not the primary treatment for adrenal crisis.","Adrenal crisis requires urgent volume resuscitation and glucocorticoid replacement; treat precipitating causes and monitor electrolytes/glucose.","Oral thyroid hormone treats hypothyroidism and does not address acute adrenal hormone deficiency or shock.","Fluid restriction and diuretics worsen hypovolemia and hypotension in adrenal crisis."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-011","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Cushing syndrome complication","question":"A client with Cushing syndrome is being monitored. Which finding requires particular attention because of cortisol excess?","options":["Severe dehydration from dilute urine as the expected finding.","Persistent hypoglycemia and low infection risk.","Bradycardia with hypothermia as the defining pattern.","Signs of infection and hyperglycemia."],"answer":3,"rationales":["Dilute urine with severe dehydration is not the defining expected pattern of Cushing syndrome; cortisol excess more commonly promotes sodium/fluid retention.","Cortisol excess raises blood glucose and suppresses immune/inflammatory responses, increasing rather than lowering infection risk.","Bradycardia and hypothermia suggest severe hypothyroidism, not the typical effects of excess cortisol.","Cortisol excess suppresses immune response and raises blood glucose; infection may be subtle and healing impaired."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-012","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"SIADH laboratory pattern","question":"A client with SIADH has which expected laboratory pattern?","options":["High serum sodium and dilute urine.","Low serum sodium with very dilute urine.","Low serum sodium and low serum osmolality with concentrated urine.","High serum osmolality and high urine output."],"answer":2,"rationales":["SIADH causes dilutional hyponatremia and concentrated urine, not high serum sodium with dilute urine.","Low sodium fits SIADH, but very dilute urine does not; inappropriate antidiuretic hormone activity concentrates urine.","Excess ADH causes water retention, dilutional hyponatremia, low serum osmolality, and inappropriately concentrated urine.","In SIADH, serum osmolality is low and urine is inappropriately concentrated; high serum osmolality and high urine output are inconsistent."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-013","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"SIADH neurologic priority","question":"A client with SIADH becomes confused and then has a seizure. What is the nurse’s priority?","options":["Protect the client from injury, support airway, and urgently escalate care.","Ambulate the client to improve sodium levels.","Delay action until the next sodium result.","Encourage free-water intake."],"answer":0,"rationales":["Severe hyponatremia can cause cerebral edema, confusion, and seizures; immediate safety and emergency response are required.","A client with a seizure is at risk for injury and airway compromise; ambulation is unsafe and does not correct hyponatremia.","Delaying action during a seizure risks injury and respiratory compromise; protect the client and escalate immediately.","Free-water intake can worsen water retention and dilutional hyponatremia in SIADH."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-014","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Diabetes insipidus pattern","question":"A client with central diabetes insipidus is experiencing intense thirst and large volumes of dilute urine. Which finding is expected?","options":["Glucosuria with elevated HbA1c as the defining pattern.","Decreased serum sodium with concentrated urine.","Increased serum sodium/osmolality with low urine specific gravity.","Low serum osmolality with concentrated urine."],"answer":2,"rationales":["Glucosuria and elevated HbA1c relate to diabetes mellitus, not the defining water-loss pattern of diabetes insipidus.","Central DI causes loss of dilute urine and can raise serum sodium/osmolality; low sodium with concentrated urine is more consistent with excess ADH activity.","Lack of effective ADH causes free-water loss, dilute urine, and risk for hypernatremia and increased serum osmolality.","Low serum osmolality with concentrated urine is more consistent with SIADH; DI produces dilute urine and often increased serum osmolality."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-015","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Desmopressin monitoring","question":"A client with central diabetes insipidus receives desmopressin. Which finding best suggests the medication is having the intended effect?","options":["Urine output increases and urine becomes more dilute.","The client develops worsening thirst and hypotension.","Serum sodium rises rapidly.","Urine output decreases and urine becomes more concentrated."],"answer":3,"rationales":["Desmopressin replaces ADH activity in central DI, so urine volume should fall and urine concentration should rise rather than the reverse.","Worsening thirst and hypotension suggest ongoing fluid loss or inadequate response, not effective control of central DI.","A rapid rise in sodium is not the desired response; monitor sodium carefully because excessive water retention can cause hyponatremia.","Desmopressin replaces ADH activity, reducing excessive urine output and increasing urine concentration."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-016","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Myasthenic crisis","question":"A client with myasthenia gravis develops increasing difficulty swallowing, a weak cough, and shallow respirations. What is the priority concern?","options":["A sign of SIADH.","A mild adverse effect of antihistamines only.","Impending respiratory failure from myasthenic crisis.","Expected fatigue that requires no action."],"answer":2,"rationales":["SIADH is a water-balance disorder and does not explain progressive bulbar and respiratory muscle weakness in myasthenia gravis.","Antihistamine effects do not adequately explain this pattern; worsening dysphagia, weak cough, and shallow respirations signal possible myasthenic crisis.","Bulbar weakness and respiratory muscle involvement can rapidly compromise ventilation and airway protection.","Progressive swallowing and respiratory weakness are not routine fatigue; they can precede respiratory failure and require immediate escalation."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-017","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Myasthenia gravis medication timing","question":"A client with myasthenia gravis is prescribed pyridostigmine. Which nursing action supports safe administration?","options":["Give doses only after meals regardless of the prescription.","Hold all doses whenever the client feels weak.","Double the next dose if one is late.","Give doses on schedule and coordinate timing with meals as prescribed to support swallowing."],"answer":3,"rationales":["Pyridostigmine timing should follow the prescription; giving it only after meals can leave swallowing strength inadequate during meals.","Weakness may signal inadequate control or crisis; holding doses without an order can worsen symptoms.","Doubling a dose increases risk of cholinergic adverse effects and is not a safe response to a late dose.","Maintaining prescribed timing helps sustain neuromuscular function; meal coordination may help reduce dysphagia-related risk."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-018","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Guillain-Barré syndrome priority","question":"A client with Guillain-Barré syndrome has ascending weakness. Which assessment is most important to trend?","options":["Visual acuity only.","Respiratory effort, vital capacity/respiratory function, and ability to protect the airway.","Bowel sounds alone.","Daily hair loss."],"answer":1,"rationales":["Visual acuity alone does not track the most dangerous complication of ascending neuromuscular weakness.","Ascending paralysis can involve respiratory muscles; frequent respiratory assessment detects deterioration early.","Bowel sounds may be assessed but do not detect the immediate life-threatening risk of respiratory muscle paralysis.","Hair loss is unrelated to the acute progression and respiratory risk of Guillain-Barré syndrome."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-019","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Guillain-Barré autonomic instability","question":"A client with Guillain-Barré syndrome develops sudden blood-pressure fluctuations and an irregular heart rate. What should the nurse suspect?","options":["Autonomic nervous system involvement requiring close monitoring and escalation.","A normal expected finding that needs no follow-up.","An isolated skin allergy.","Improved neuromuscular function."],"answer":0,"rationales":["GBS can affect autonomic function, causing dangerous blood-pressure and heart-rate instability.","Blood-pressure swings and dysrhythmias can reflect Guillain-Barré-related autonomic dysfunction and may become life-threatening; they are not benign findings.","An isolated skin allergy does not explain simultaneous cardiovascular instability in this neurologic disorder.","Autonomic instability is not evidence of neurologic recovery; it requires monitoring and prompt escalation."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-020","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Anaphylaxis first-line medication","question":"A client develops wheezing, facial swelling, and hypotension minutes after an antibiotic. Which medication is the priority first-line treatment?","options":["A topical corticosteroid.","An oral antacid.","An oral antihistamine alone.","Intramuscular epinephrine."],"answer":3,"rationales":["Topical corticosteroids do not rapidly reverse systemic airway edema, bronchospasm, and hypotension in anaphylaxis.","Antacids do not treat the systemic allergic reaction or airway/circulatory compromise.","Oral diphenhydramine may relieve some skin symptoms but is not first-line treatment for anaphylaxis and must not delay epinephrine.","IM epinephrine is first-line for anaphylaxis because it treats airway edema, bronchospasm, and hypotension."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-021","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Anaphylaxis follow-up","question":"After receiving epinephrine for anaphylaxis, the client reports that breathing is easier. What should the nurse do?","options":["Discharge immediately because symptoms improved.","Stop vital-sign monitoring.","Encourage the client to walk unassisted.","Continue emergency monitoring and prepare for further treatment because symptoms can recur."],"answer":3,"rationales":["Improvement after epinephrine does not eliminate the risk of recurrence or a biphasic reaction; emergency observation is still needed.","Continuous reassessment of respiratory status, circulation, and vital signs remains necessary after initial improvement.","After anaphylaxis, the client may deteriorate again; unassisted ambulation is not a priority and may be unsafe.","Anaphylaxis can be biphasic or persistent; ongoing airway, respiratory, and circulatory monitoring is necessary."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-022","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Angioedema airway","question":"A client taking an ACE inhibitor develops swelling of the tongue and lips. Which action is the priority?","options":["Document the swelling and reassess in several hours.","Assess and protect the airway; activate emergency response for progressive swelling or breathing difficulty.","Place the client supine and leave the room.","Offer food and fluids to test swallowing."],"answer":1,"rationales":["Tongue and lip swelling can progress rapidly to airway obstruction; waiting several hours is unsafe.","Angioedema can rapidly obstruct the airway; airway assessment and urgent escalation take priority.","Leaving the client without airway assessment or emergency support delays treatment of a potentially obstructed airway.","Offering food or fluids is unsafe when tongue swelling may impair swallowing and airway protection."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-023","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"DMARD infection precautions","question":"A client taking a biologic DMARD reports fever and a productive cough. What should the nurse advise?","options":["Receive a live vaccine immediately.","Ignore the symptoms unless a rash develops.","Take the next dose early to control inflammation.","Promptly contact the healthcare provider for evaluation of possible infection."],"answer":3,"rationales":["Live vaccines may be contraindicated during significant immunosuppression; the client needs infection assessment and prescriber guidance, not immediate live vaccination.","Fever and productive cough may indicate a serious infection in an immunosuppressed client and should not be ignored.","Taking a biologic DMARD early can increase immunosuppression and is not appropriate when infection is suspected; the prescriber should guide whether to hold it.","DMARDs and biologic immunosuppressants can increase infection risk; fever and respiratory symptoms require prompt evaluation."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-024","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Immunosuppressant monitoring","question":"A client is prescribed a calcineurin inhibitor after transplantation. Which monitoring is especially important?","options":["Only daily visual acuity.","No laboratory monitoring once the dose is prescribed.","Renal function, blood pressure, drug levels as ordered, and signs of infection.","Only serum amylase."],"answer":2,"rationales":["Visual acuity alone does not monitor the major toxicities and safety concerns of calcineurin inhibitors.","Calcineurin inhibitors require ongoing laboratory and clinical monitoring because of nephrotoxicity, hypertension, drug-level concerns, and infection risk.","Calcineurin inhibitors can cause nephrotoxicity and hypertension and require therapeutic monitoring; immunosuppression increases infection risk.","Serum amylase alone does not assess the key risks of calcineurin inhibitors; renal function, blood pressure, ordered drug levels, and infection signs are important."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-025","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Glucocorticoid safety","question":"A client has taken long-term systemic glucocorticoids. Which instruction is most important?","options":["Double the dose whenever blood glucose rises.","Do not stop the medication abruptly; follow the prescribed taper.","Avoid reporting fever because steroids prevent infection.","Stop the medication as soon as symptoms improve."],"answer":1,"rationales":["Clients should not independently double glucocorticoid doses for hyperglycemia; dose changes and sick-day instructions must come from the prescriber.","Long-term glucocorticoids suppress the hypothalamic-pituitary-adrenal axis; abrupt withdrawal can precipitate adrenal insufficiency.","Glucocorticoids can mask infection signs and increase infection risk; fever or other infection symptoms should be reported.","Symptom improvement does not mean long-term glucocorticoids can be stopped abruptly; tapering prevents adrenal insufficiency."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-026","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Radioactive iodine safety","question":"A client is scheduled for radioactive iodine treatment for hyperthyroidism. Which teaching is appropriate?","options":["Stop all follow-up thyroid testing after treatment.","Share utensils and close sleeping space without checking instructions.","Assume there are no precautions because the treatment is oral.","Follow the prescribed radiation-safety precautions and pregnancy-related restrictions."],"answer":3,"rationales":["Thyroid function must be followed after radioactive iodine because hypothyroidism can develop and treatment response must be assessed.","Close-contact and other radiation precautions may be required for a specified period; follow the individualized written instructions rather than assuming sharing is safe.","Oral administration does not mean the treatment has no radiation-safety restrictions; follow the nuclear-medicine team’s instructions.","Radioactive iodine requires individualized radiation-safety instructions and is contraindicated in pregnancy; thyroid function needs follow-up."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-027","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Diabetic neuropathy medication","question":"A client taking pregabalin for diabetic neuropathy reports dizziness and sleepiness. What is the best nursing response?","options":["Recommend combining it with alcohol to improve sleep.","Tell the client to stop it abruptly without contacting the prescriber.","Explain that these effects prove blood glucose is too low.","Reinforce fall precautions and advise the client to avoid driving until effects are known."],"answer":3,"rationales":["Alcohol can increase dizziness and central nervous system depression with pregabalin, raising fall and injury risk.","Pregabalin should not be stopped abruptly without prescriber guidance; the client should report troublesome effects and receive an individualized plan.","Dizziness and sleepiness are known pregabalin adverse effects and do not by themselves prove hypoglycemia; check glucose if symptoms or context warrant it.","Pregabalin can cause dizziness and somnolence; safety precautions reduce injury risk."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-028","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Endocrine clinical judgment","question":"A client with an endocrine disorder has new confusion, abnormal vital signs, and a critical electrolyte result. What should the nurse do first?","options":["Focus on routine discharge teaching.","Assess airway, breathing, circulation, neurologic status, and escalate the acute change immediately.","Delegate the assessment to assistive personnel.","Wait for a complete endocrine panel before acting."],"answer":1,"rationales":["Routine discharge teaching is inappropriate while the client has acute confusion, abnormal vital signs, and a critical electrolyte result.","Acute mental-status and vital-sign changes with critical electrolytes may signal life-threatening deterioration; immediate nursing assessment and escalation are required.","Assessment and clinical judgment for acute deterioration cannot be delegated to assistive personnel.","Waiting for a complete endocrine panel delays response to potentially life-threatening deterioration; act on the current assessment and critical result."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-029","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Prioritization — infection","question":"The nurse receives reports on four clients receiving immune-related treatment. Which client should be assessed first?","options":["A client asking for routine medication teaching.","A client requesting a low-fat diet menu.","A client with stable chronic joint pain.","A client receiving immunosuppressants who has a new fever and chills."],"answer":3,"rationales":["Routine medication teaching is not as urgent as a possible acute infection in an immunosuppressed client.","A diet request is a stable, nonurgent need compared with fever and chills during immunosuppressive therapy.","Chronic stable joint pain is less urgent than possible infection in a client whose immune response is suppressed.","Fever and chills in an immunosuppressed client may indicate serious infection and require prompt assessment."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-030","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Guillain-Barré respiratory deterioration","question":"Which change in a client with Guillain-Barré syndrome requires the nurse to intervene immediately?","options":["The cough is becoming weaker and respiratory effort is increasing","The client reports chronic morning stiffness","The client with stable hypothyroidism reports dry skin","The client with controlled diabetes requests a snack"],"answer":0,"rationales":["A weakening cough with increasing respiratory effort signals possible respiratory muscle failure and requires immediate airway and breathing assessment/escalation.","Chronic morning stiffness is not an immediate threat to breathing.","Dry skin is a stable hypothyroid symptom and is not the immediate priority.","A snack request in a stable client is less urgent than possible respiratory failure."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-031","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Nutrition — diabetes and cardiovascular risk","question":"A client with diabetes and dyslipidemia asks how diet supports the treatment plan. Which response is best?","options":["Choose a balanced eating pattern that supports glucose control and cardiovascular risk reduction, following the prescribed calorie and fat goals.","Use a high-saturated-fat diet because diabetes only affects glucose.","Eliminate all carbohydrates permanently.","Replace meals with high-sugar drinks."],"answer":0,"rationales":["Nutrition planning should align with individualized glucose and lipid goals; diabetes also increases cardiovascular risk.","A diet high in saturated fat increases cardiovascular risk; diabetes management includes attention to lipid and cardiovascular health.","Carbohydrates do not need to be eliminated permanently; individualized carbohydrate quality, amount, and meal planning support safe glucose management.","High-sugar drinks can worsen hyperglycemia and do not provide balanced nutrition for diabetes and dyslipidemia."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-032","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Patient education — teach-back","question":"A client with a new endocrine diagnosis is preparing for discharge. Which method best evaluates understanding of medication and self-management instructions?","options":["Ask a family member to answer for the client without permission.","Ask the client to explain or demonstrate the plan using teach-back.","Give written instructions without discussion.","Ask, “Do you understand?” and end teaching."],"answer":1,"rationales":["Family involvement should occur with the client’s permission; a family member answering does not establish the client’s own understanding.","Teach-back verifies the client can restate or demonstrate key actions and reveals gaps needing clarification.","Written instructions can support learning but do not confirm that the client understands or can perform the self-management plan.","Clients may answer yes without understanding; teach-back asks them to explain or demonstrate the instructions in their own words."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-033","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Cultural and spiritual preferences","question":"A client declines a recommended intervention because of a spiritual belief. What is the nurse’s best initial response?","options":["Dismiss the belief as irrational.","Assume the client lacks decision-making capacity.","Proceed without consent because the intervention is standard.","Explore the client’s understanding and preferences, provide clear information, and collaborate on acceptable options."],"answer":3,"rationales":["Dismissing the client’s belief damages trust and does not support respectful, client-centered decision-making.","A spiritual belief or refusal alone does not establish impaired decision-making capacity; assess understanding and capacity when clinically indicated.","A capable client has the right to informed refusal; a standard recommendation does not authorize treatment without consent.","Respectful assessment and shared decision-making support autonomy and culturally sensitive care."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null},{"id":"CH5-FINAL-034","moduleId":"ch5-advanced-nclex-priority-clinical-judgment","category":"NCLEX Clinical Judgment","tag":"Scope and delegation","question":"A stable client with diabetes needs routine capillary glucose monitoring and teaching about a new insulin regimen. Which task may the nurse delegate to trained assistive personnel?","options":["Teach insulin injection technique.","Obtain the capillary glucose result and report it to the nurse, according to facility policy.","Interpret the glucose trend and adjust the insulin dose.","Assess new confusion and determine its cause."],"answer":1,"rationales":["Teaching a new insulin regimen requires nursing assessment, individualized education, and evaluation of learning; it is not a UAP task.","Routine data collection may be delegated when permitted; interpretation, teaching, and clinical assessment remain nursing responsibilities.","Interpreting glucose trends and changing insulin doses require nursing judgment and an authorized prescriber order, not UAP action.","Assessing new confusion and determining its cause require nursing assessment and clinical judgment; these responsibilities cannot be delegated to UAP."],"case":null,"noteId":"ch5-unit5-syllabus-three-ati-powerpoints-nclex-enrichment","noteTitle":"Chapter 5 Unit 5 Syllabus + Three ATI PowerPoints — NCLEX Clinical Judgment Enrichment","conceptId":null}]});
